14: 
15: class StoreProductRequest extends FormRequest
16: {
17:     use LimitsArrayInput;
18: 
19:     protected function arrayLimits(): array
20:     {
21:         return ['variants' => 100];
22:     }
23: 
24:     public function authorize(): bool
25:     {
26:         return $this->user() !== null;
27:     }
28: 
29:     /**
30:      * @return array<string, array<mixed>|string|ValidationRule>
31:      */
32:     public function rules(): array
33:     {
34:         $rules = [
35:             'category_id' => ['required', 'integer', Rule::exists('categories', 'id')->whereNull('deleted_at')],
36:             'brand_id' => ['nullable', 'integer', Rule::exists('brands', 'id')->whereNull('deleted_at')],
37:             'supplier_id' => ['nullable', 'integer', 'min:1'],
38:             'name_ar' => ['required', 'string', 'max:255'],
39:             'name_en' => ['required', 'string', 'max:255'],
40:             'slug' => ['nullable', 'alpha_dash:ascii', 'max:255', new UniqueCatalogIdentifier('products', 'slug')],
41:             'description_ar' => ['nullable', 'string'],
42:             'description_en' => ['nullable', 'string'],
43:             'material_ar' => ['nullable', 'string', 'max:150'],
44:             'material_en' => ['nullable', 'string', 'max:150'],
45:             'length_cm' => ['nullable', 'numeric', 'min:0', 'max:999999.99'],
46:             'width_cm' => ['nullable', 'numeric', 'min:0', 'max:999999.99'],
47:             'height_cm' => ['nullable', 'numeric', 'min:0', 'max:999999.99'],
48:             'weight_kg' => ['nullable', 'numeric', 'min:0', 'max:99999.999'],
49:             'warranty_months' => ['nullable', 'integer', 'min:0', 'max:120'],
50:             'warranty_details' => ['nullable', 'string', 'max:255'],
51:             'country_of_origin' => ['nullable', 'string', 'max:100'],
52:             'status' => ['nullable', Rule::in(['draft'])],
53:             'sales_channel' => ['required', Rule::enum(SalesChannel::class)],
54:             'is_featured' => ['nullable', 'boolean'],
55:             // اختياري: متغيرات مع الإنشاء
56:             'variants' => ['nullable', 'array', 'max:100'],
57:             'variants.*' => ['array:'.implode(',', array_keys(VariantRules::base()))],
58:         ];
59: 
60:         foreach (VariantRules::base(null, 'variants.*.') as $field => $rule) {
61:             if (in_array($field, ['sku', 'barcode'], true)) {
62:                 $rule[] = 'distinct';
63:             }
64:             $rules["variants.*.$field"] = $rule;
65:         }
66: 
67:         return $rules;
68:     }
