14: 
15: class UpdateProductRequest extends FormRequest
16: {
17:     use NormalizesCatalogInput;
18: 
19:     protected function prepareForValidation(): void
20:     {
21:         parent::prepareForValidation();
22:         $this->normalizeCatalogIdentifiers();
23:     }
24: 
25:     public function authorize(): bool
26:     {
27:         return $this->user() !== null;
28:     }
29: 
30:     /**
31:      * @return array<string, array<mixed>|string|ValidationRule>
32:      */
33:     public function rules(): array
34:     {
35:         return [
36:             'category_id' => ['sometimes', 'required', 'integer', Rule::exists('categories', 'id')->whereNull('deleted_at')],
37:             'brand_id' => ['sometimes', 'nullable', 'integer', Rule::exists('brands', 'id')->whereNull('deleted_at')],
38:             'supplier_id' => ['sometimes', 'nullable', 'integer', 'min:1'],
39:             'name_ar' => ['sometimes', 'required', 'string', 'max:255'],
40:             'name_en' => ['sometimes', 'required', 'string', 'max:255'],
41:             'slug' => ['sometimes', 'nullable', 'alpha_dash:ascii', 'max:255', new UniqueCatalogIdentifier('products', 'slug', $this->route('product')->id)],
42:             'description_ar' => ['sometimes', 'nullable', 'string'],
43:             'description_en' => ['sometimes', 'nullable', 'string'],
44:             'material_ar' => ['sometimes', 'nullable', 'string', 'max:150'],
45:             'material_en' => ['sometimes', 'nullable', 'string', 'max:150'],
46:             'length_cm' => ['sometimes', 'nullable', 'numeric', 'min:0', 'max:999999.99'],
