  82:       <div className="grid grid-cols-2 gap-3">
  83:         <Field label="الاسم بالعربي" required><Input value={v.ar || ''} onChange={(e) => setV({ ...v, ar: e.target.value })} /></Field>
  84:         <Field label="الاسم بالإنجليزي" required><Input ltr value={v.en || ''} onChange={(e) => setV({ ...v, en: e.target.value })} /></Field>
  85:       </div>
  86:       <Field label="الرابط (slug)" hint="اتركه فارغًا ليتولد من الاسم الإنجليزي"><Input ltr value={v.slug || ''} placeholder={(v.en || '').toLowerCase().replace(/[^a-z0-9]+/g, '-')} onChange={(e) => setV({ ...v, slug: e.target.value })} /></Field>
  87:       <Field label="الوصف بالعربي"><Textarea rows={2} /></Field>
  88:       <Field label="الوصف بالإنجليزي"><Textarea rows={2} className="ltr" dir="ltr" /></Field>
  89:       <div className="grid grid-cols-[120px_1fr] gap-3">
  90:         <Field label="الترتيب"><Input ltr type="number" value={v.order || ''} onChange={(e) => setV({ ...v, order: e.target.value })} /></Field>
  91:         <div className="v-subcard p-3.5 flex items-center justify-between self-end h-[42px] !rounded-[13px]"><span className="text-[12.5px] font-semibold t-1">نشط</span><Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} /></div>
  92:       </div>
  93:     </div>
  94:   );
  95: }
