  97: /* ====================== PRODUCTS LIST ====================== */
  98: function ProductsPage() {
  99:   const { user } = useApp();
 100:   const [q, setQ] = useQueryState({ page: 1, per_page: 10, search: '', category: '', sub: '1', brand: '', status: '', channel: '', featured: '', sort: 'newest' });
 101:   const [phase, retry] = useLoad([q.page, q.per_page, q.search, q.category, q.sub, q.brand, q.status, q.channel, q.featured, q.sort]);
 102:   if (!user.can('products.view')) return <Forbidden perm="products.view" />;
 103:   const flat = flattenCats(CATEGORIES);
 104:   const catNode = q.category && flat.find((f) => String(f.id) === String(q.category));
 105:   let rows = PRODUCTS.filter((p) =>
 106:     (!q.search || (p.ar + p.en + p.code).toLowerCase().includes(q.search.toLowerCase())) &&
 107:     (!q.status || p.status === q.status) && (!q.channel || p.channel === q.channel) &&
 108:     (!q.brand || p.brand === (BRANDS.find((b) => String(b.id) === String(q.brand)) || {}).ar) &&
 109:     (!q.featured || p.featured) &&
 110:     (!catNode || p.cat === catNode.ar || (q.sub === '1' && p.catPath.includes(catNode.ar))));
 111:   if (q.sort === 'oldest') rows = [...rows].reverse();
 112:   if (q.sort === 'name') rows = [...rows].sort((a, b) => a.ar.localeCompare(b.ar, 'ar'));
 113:   const res = fakeQuery(rows, { page: +q.page, per_page: +q.per_page });
 114:   const activeFilters = ['category', 'brand', 'status', 'channel', 'featured'].filter((k) => q[k]).length + (q.search ? 1 : 0);
 115:   const counts = { all: PRODUCTS.length, published: PRODUCTS.filter((p) => p.status === 'published').length, draft: PRODUCTS.filter((p) => p.status === 'draft').length, archived: PRODUCTS.filter((p) => p.status === 'archived').length };
 116:   return (
 117:     <div className="space-y-5">
 118:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'المنتجات' }]} title="المنتجات" subtitle="المنتج بيتعمل مسودة الأول، بعدها الصور، وبعدها النشر."
 119:         actions={user.can('products.create') && <button className="btn btn-ink" onClick={() => nav('/products/new')}><Icon name="plus" size={15} />منتج جديد</button>} />
 120: 
 121:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stagger s2">
 122:         {[['', 'كل المنتجات', counts.all, 'box'], ['published', 'منشور', counts.published, 'globe'], ['draft', 'مسودة', counts.draft, 'edit'], ['archived', 'مؤرشف', counts.archived, 'folder']].map(([k, l, n, ic], i) => {
 123:           const on = q.status === k;
 124:           return (
 125:             <button key={k} onClick={() => setQ({ status: k, page: 1 })} className={cx('rounded-[22px] p-5 text-start transition', on ? 'v-orange shadow-sm' : 'v-card hover:shadow-sm')}>
 126:               <div className={cx('flex items-center justify-between text-[12.5px] font-medium', on ? 'text-white/90' : 't-2')}>{l}<span className={cx('w-7 h-7 rounded-full flex items-center justify-center', on ? 'bg-white/15' : 'v-well')}><Icon name={ic} size={14} /></span></div>
 127:               <div className={cx('font-display text-[32px] font-bold mt-3 num', !on && 't-1')}>{n}</div>
 128:               <div className={cx('mt-2 h-1.5 rounded-full overflow-hidden', on ? 'bg-white/20' : 'hatched-track')}><div className={cx('h-full rounded-full', on ? 'bg-white' : 'hatched-acc')} style={{ width: `${(n / counts.all) * 100}%` }} /></div>
 129:             </button>
 130:           );
 131:         })}
 132:       </div>
 133: 
 134:       <div className="stagger s3">
 135:         <DataTable state={phase} onRetry={retry} rows={res.data} meta={res.meta} filtered={activeFilters > 0}
 136:           onPage={(p) => setQ({ page: p })} onPerPage={(n) => setQ({ per_page: n, page: 1 })} onRowClick={(r) => nav('/products/' + r.id)}
 137:           empty={activeFilters > 0 ? <EmptyState icon="search" title="لا منتجات مطابقة" body="البحث بيشمل الاسم والكود وSKU والباركود. جرّب كلمات أقل أو امسح الفلاتر." action={<button className="btn btn-soft" onClick={() => setQ({ search: '', category: '', brand: '', status: '', channel: '', featured: '', page: 1 })}>مسح كل الفلاتر</button>} />
 138:             : <EmptyState icon="box" title="لا توجد منتجات بعد" body="ابدأ بأول منتج كمسودة — تقدر تضيف الصور وتنشره بعدين." action={<button className="btn btn-ink" onClick={() => nav('/products/new')}><Icon name="plus" size={15} />منتج جديد</button>} />}
 139:           toolbar={
 140:             <div className="space-y-3">
 141:               <div className="flex flex-wrap items-center gap-2">
 142:                 <SearchBox value={q.search} onChange={(v) => setQ({ search: v, page: 1 })} placeholder="الاسم، الكود، SKU أو الباركود…" width={320} />
 143:                 <div className="w-[230px]"><SearchSelect value={q.category ? +q.category : null} onChange={(v) => setQ({ category: v, page: 1 })} placeholder="كل الأقسام" options={flat.map((f) => ({ value: f.id, label: f.ar, depth: f.depth }))} /></div>
 144:                 {q.category && <label className="h-10 px-3.5 rounded-full v-subcard !rounded-full flex items-center gap-2 text-[12px] font-medium t-1 cursor-pointer" onClick={() => setQ({ sub: q.sub === '1' ? '0' : '1', page: 1 })}><Check on={q.sub === '1'} />تضمين الأقسام الفرعية</label>}
 145:                 <FilterMenu label="البراند" value={q.brand ? +q.brand : null} onChange={(v) => setQ({ brand: v, page: 1 })} options={BRANDS.map((b) => ({ value: b.id, label: b.ar }))} />
 146:                 <FilterMenu label="القناة" value={q.channel || null} onChange={(v) => setQ({ channel: v, page: 1 })} options={[{ value: 'retail', label: 'تجزئة' }, { value: 'wholesale', label: 'جملة' }, { value: 'both', label: 'تجزئة + جملة' }]} />
 147:                 <button onClick={() => setQ({ featured: q.featured ? '' : '1', page: 1 })} className={cx('h-10 px-3.5 rounded-full inline-flex items-center gap-2 text-[12.5px] font-medium border transition', q.featured ? 'bg-ink border-transparent' : 'btn-outline')}><Icon name="star" size={14} />مميز</button>
 148:                 <div className="ms-auto flex items-center gap-2">
 149:                   <span className="text-[12px] t-3">ترتيب</span>
 150:                   <Seg value={q.sort} onChange={(v) => setQ({ sort: v, page: 1 })} options={[{ value: 'newest', label: 'الأحدث' }, { value: 'oldest', label: 'الأقدم' }, { value: 'name', label: 'الاسم' }]} />
 151:                 </div>
 152:               </div>
 153:               {activeFilters > 0 && (
 154:                 <div className="flex items-center gap-2 text-[12px] pop">
 155:                   <span className="t-3"><span className="num font-semibold t-1">{res.meta.total}</span> نتيجة ·</span>
 156:                   <button className="font-semibold t-acc" onClick={() => setQ({ search: '', category: '', brand: '', status: '', channel: '', featured: '', page: 1 })}>مسح الفلاتر ({activeFilters})</button>
 157:                   <span className="t-3 ms-auto hidden md:flex items-center gap-1"><Icon name="link" size={12} />الفلاتر محفوظة في الرابط</span>
 158:                 </div>
 159:               )}
 160:             </div>
 161:           }
 162:           columns={[
 163:             { key: 'p', label: 'المنتج', render: (r) => (
 164:               <div className="flex items-center gap-3 min-w-[240px]">
 165:                 <span className="w-12 h-12 rounded-[14px] shrink-0 relative" style={{ background: r.img }}>{r.featured && <span className="absolute -top-1 -end-1 w-5 h-5 rounded-full bg-acc flex items-center justify-center" style={{ boxShadow: '0 0 0 2px var(--bg-card)' }}><Icon name="star" size={10} sw={2.5} /></span>}</span>
 166:                 <div className="min-w-0"><div className="font-semibold t-1 truncate">{r.ar}</div><div className="text-[11px] t-3 ltr inline-block">{r.code}</div></div>
 167:               </div>), skel: () => <div className="flex items-center gap-3"><Skel w={48} h={48} r={14} /><div className="space-y-1.5 flex-1"><Skel w="70%" h={10} /><Skel w="40%" h={8} /></div></div> },
 168:             { key: 'cat', label: 'القسم / البراند', render: (r) => <div><div className="t-1 text-[12.5px]">{r.cat}</div><div className="text-[11px] t-3">{r.brand}</div></div> },
 169:             { key: 'status', label: 'الحالة', render: (r) => <StatusBadge s={r.status} /> },
 170:             { key: 'channel', label: 'القناة', render: (r) => <span className="text-[12px] t-2 whitespace-nowrap">{CHANNEL_LABEL[r.channel]}</span> },
 171:             { key: 'variants', label: 'المتغيرات', align: 'center', render: (r) => <span className="inline-flex w-7 h-7 rounded-full v-well items-center justify-center text-[11.5px] font-bold num t-1">{r.variants}</span> },
 172:             { key: 'price', label: 'سعر التجزئة', render: (r) => r.channel === 'wholesale' ? <span className="t-3 text-[12px]">جملة فقط</span> : r.min == null ? <span className="text-[11.5px] font-medium" style={{ color: 'var(--badge-amber-text)' }}>غير مكتمل</span> : <span className="num font-semibold t-1 whitespace-nowrap">{r.min === r.max ? fmtMoney(r.min) : `${fmtMoney(r.min)} – ${fmtMoney(r.max)}`} <span className="text-[10.5px] t-3 font-medium">ج.م</span></span> },
 173:             { key: 'a', label: '', render: (r) => <RowActions onEdit={() => nav('/products/' + r.id)} /> },
 174:           ]} />
 175:       </div>
 176:     </div>
 177:   );
 178: }
