 241: function flattenCats(nodes, depth = 0, path = []) {
 242:   return nodes.flatMap((n) => [{ ...n, depth, path: [...path, n.ar] }, ...flattenCats(n.children || [], depth + 1, [...path, n.ar])]);
 243: }
 244: 
 245: // Fake server: paginate + filter, returning {data, meta, links}
 246: function fakeQuery(all, { page = 1, per_page = 10 }) {
 247:   const total = all.length; const last = Math.max(1, Math.ceil(total / per_page));
 248:   const p = Math.min(page, last); const start = (p - 1) * per_page;
 249:   return {
 250:     data: all.slice(start, start + per_page),
 251:     meta: { current_page: p, last_page: last, per_page, total, from: total ? start + 1 : 0, to: Math.min(start + per_page, total) },
 252:     links: { first: '?page=1', last: `?page=${last}`, prev: p > 1 ? `?page=${p - 1}` : null, next: p < last ? `?page=${p + 1}` : null },
 253:   };
 254: }
