 329: function Icon({ name, size = 16, className = '', style, sw = 1.9 }) {
 330:   return (
 331:     <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
 332:       strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round" className={'shrink-0 ' + className} style={style} aria-hidden="true">
 333:       {ICON_PATHS[name] || ICON_PATHS.info}
 334:     </svg>
 335:   );
 336: }
 337: 
 338: function seedProduct(id) {
 339:   const p = PRODUCTS.find((x) => String(x.id) === String(id));
 340:   if (!p) return null;
 341:   const colors = [PRESET_COLORS[0], PRESET_COLORS[1], PRESET_COLORS[4]];
 342:   const sizes = ['240×160', '280×180'];
 343:   const rows = [];
 344:   colors.forEach((c) => sizes.forEach((s, j) => rows.push({ ...emptyVariant(c, s, '', rows.length), sku: `MIL-${c.en.slice(0, 3).toUpperCase()}-${j + 1}`, barcode: `62210${40000 + rows.length * 37}`, retail: String(28500 + j * 6400), wholesale: String(24000 + j * 5200), cost: String(17800 + j * 3900), compare: j ? '' : '31900' })));
 345:   return {
 346:     status: p.status, code: p.code,
 347:     basic: { ar: p.ar, en: p.en, category: 111, brand: 1, channel: p.channel, slug: 'milano-corner-sofa', desc_ar: 'كنبة زاوية بتصميم معاصر، هيكل من خشب الزان المجفف وإسفنج عالي الكثافة.', desc_en: 'Contemporary corner sofa with kiln-dried beech frame and high-density foam.', mat_ar: 'قماش شانيل', mat_en: 'Chenille fabric', l: '280', w: '180', h: '85', kg: '96', warranty: '24', warranty_details: 'ضمان على الهيكل ضد عيوب التصنيع', origin: 'مصر', featured: p.featured, supplier: null },
 348:     mode: 'matrix', axes: { colors, sizes, capacities: [] }, rows,
 349:     media: { general: [
 350:       { id: 'g1', name: 'milano-front.jpg', size: '2.1MB', status: 'done', bg: IMG[0] },
 351:       { id: 'g2', name: 'milano-side.jpg', size: '1.8MB', status: 'done', bg: IMG[7] },
 352:       { id: 'g3', name: 'milano-detail.jpg', size: '3.4MB', status: 'done', bg: IMG[4] },
 353:     ], byVariant: { 'Charcoal': [{ id: 'v1', name: 'charcoal.jpg', size: '1.2MB', status: 'done', bg: 'linear-gradient(135deg,#5c5363,#2a2530)' }], 'Beige': [], 'Terracotta': [] }, video: null },
 354:   };
 355: }
 356: function blankProduct() {
 357:   return {
 358:     status: null, code: null,
 359:     basic: { ar: '', en: '', category: null, brand: null, channel: 'retail', slug: '', desc_ar: '', desc_en: '', mat_ar: '', mat_en: '', l: '', w: '', h: '', kg: '', warranty: '', warranty_details: '', origin: '', featured: false, supplier: null },
 360:     mode: 'single', axes: { colors: [], sizes: [], capacities: [] }, rows: [emptyVariant(null, '', '', 0)],
 361:     media: { general: [], byVariant: {}, video: null },
 362:   };
 363: }
 364: 
 365: function ProductForm({ id }) {
 366:   const { user, publishScenario } = useApp();
 367:   const isNew = id === 'new';
 368:   const [p, setP] = useState(() => isNew ? blankProduct() : (seedProduct(id) || blankProduct()));
 369:   const [saved, setSaved] = useState(JSON.stringify(p));
 370:   const [tab, setTabQ] = useQueryState({ tab: 'basic' });
 371:   const [errs, setErrs] = useState({ basic: {}, variants: {} });
 372:   const [summary, setSummary] = useState(null);
 373:   const [flow, setFlow] = useState(null); // {steps:[{k,label,state}], done}
 374:   const [blockModal, setBlockModal] = useState(null);
 375:   const [leave, setLeave] = useState(false);
 376:   const canCost = user.can('products.view_cost');
 377:   const canPublish = user.can('products.publish');
 378:   const dirty = JSON.stringify(p) !== saved;
 379:   useUnsavedGuard(dirty);
 380:   const setBasic = (k, val) => setP({ ...p, basic: { ...p.basic, [k]: val } });
 381:   const B = p.basic;
 382:   const flat = flattenCats(CATEGORIES);
 383:   const catNode = flat.find((f) => f.id === B.category);
 384:   const vErrs = validateVariants(p.rows, B.channel, p.mode);
 385: 
 386:   // Readiness
 387:   const catChain = catNode ? catNode.path.map((name) => flat.find((f) => f.ar === name)) : [];
 388:   const inactiveAncestor = catChain.find((c) => c && c.status !== 'active');
 389:   const activeRows = p.rows.filter((r) => r.status === 'active' && r.available);
 390:   const needRetail = B.channel !== 'wholesale', needWh = B.channel !== 'retail';
 391:   const missingPrice = activeRows.filter((r) => (needRetail && !r.retail) || (needWh && !r.wholesale));
 392:   const imgCount = p.media.general.length + Object.values(p.media.byVariant).flat().length;
 393:   const ready = [
 394:     { k: 'cat', ok: !!catNode && !inactiveAncestor, label: 'القسم وكل الأقسام الأب نشطين', detail: !catNode ? 'لم يتم اختيار قسم' : inactiveAncestor ? `القسم «${inactiveAncestor.ar}» غير نشط` : catNode.path.join(' › '), tab: 'basic' },
 395:     { k: 'var', ok: activeRows.length > 0, label: 'متغير نشط واحد على الأقل', detail: `${activeRows.length} متغير نشط من ${p.rows.length}`, tab: 'variants' },
 396:     { k: 'price', ok: activeRows.length > 0 && missingPrice.length === 0, label: 'أسعار المتغيرات النشطة مكتملة حسب قناة البيع', detail: missingPrice.length ? `${missingPrice.length} متغير ناقصه ${needRetail && needWh ? 'سعر تجزئة أو جملة' : needRetail ? 'سعر التجزئة' : 'سعر الجملة'}` : `القناة: ${CHANNEL_LABEL[B.channel]}`, tab: 'variants' },
 397:     { k: 'img', ok: imgCount > 0, label: 'صورة واحدة على الأقل', detail: `${imgCount} صورة`, tab: 'media' },
 398:     { k: 'perm', ok: canPublish, label: 'صلاحية نشر المنتجات', detail: canPublish ? 'متاحة لدورك' : 'دورك لا يحتوي products.publish', tab: null },
 399:   ];
 400:   const readyCount = ready.filter((r) => r.ok).length;
 401: 
 402:   const tabState = (t) => {
 403:     if (t === 'basic') return Object.keys(errs.basic).length ? 'error' : (B.ar && B.en && B.category ? 'done' : null);
 404:     if (t === 'variants') return Object.keys(vErrs).length && (errs.variantsShown) ? 'error' : (activeRows.length && !missingPrice.length ? 'done' : null);
 405:     if (t === 'media') return imgCount ? 'done' : null;
 406:     if (t === 'review') return readyCount === ready.length ? 'done' : null;
 407:   };
 408: 
 409:   const validateBasic = () => {
 410:     const e = {};
 411:     if (!B.ar) e.ar = 'الاسم العربي مطلوب';
 412:     if (!B.en) e.en = 'الاسم الإنجليزي مطلوب';
 413:     if (!B.category) e.category = 'اختر القسم';
 414:     if (!B.channel) e.channel = 'اختر قناة البيع';
 415:     return e;
 416:   };
 417: 
 418:   const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
 419:   const run = async (publish) => {
 420:     const be = validateBasic();
 421:     const ve = validateVariants(p.rows, B.channel, p.mode);
 422:     // Drafts tolerate missing prices; only structural errors block
 423:     const structural = Object.fromEntries(Object.entries(ve).map(([k, e]) => [k, Object.fromEntries(Object.entries(e).filter(([f]) => publish || !['retail', 'wholesale'].includes(f)))]).filter(([, e]) => Object.keys(e).length));
 424:     setErrs({ basic: be, variants: structural, variantsShown: true });
 425:     if (Object.keys(be).length || Object.keys(structural).length) {
 426:       const items = [
 427:         ...Object.values(be).map((t) => ({ text: t, tab: 'البيانات الأساسية', go: 'basic' })),
 428:         ...Object.entries(structural).flatMap(([rid, e]) => { const i = p.rows.findIndex((r) => r._id === rid); return Object.entries(e).map(([f, t]) => ({ text: `variants.${i}.${f === 'dup' ? 'combination' : f === 'retail' ? 'retail_price' : f === 'wholesale' ? 'wholesale_price' : f} — ${t}`, tab: 'المتغيرات', go: 'variants' })); }),
 429:       ];
 430:       setSummary({ title: 'تعذّر الحفظ — راجع الحقول التالية', subtitle: 'الخادم رجّع 422. كل خطأ مربوط بالحقل بتاعه في التبويب.', items });
 431:       setTabQ({ tab: items[0].go });
 432:       return;
 433:     }
 434:     setSummary(null);
 435:     const steps = [
 436:       { k: 'save', label: p.status ? 'تحديث المسودة والمتغيرات' : 'حفظ المسودة والمتغيرات', state: 'run' },
 437:       { k: 'upload', label: `رفع الصور (${p.media.general.filter((f) => f.status !== 'done').length + Object.values(p.media.byVariant).flat().filter((f) => f.status !== 'done').length + (p.media.video && p.media.video.status !== 'done' ? 1 : 0)} ملف)`, state: 'wait' },
 438:       ...(publish ? [{ k: 'publish', label: 'تحديث الحالة إلى منشور', state: 'wait' }] : []),
 439:     ];
 440:     setFlow({ steps: [...steps], publish });
 441:     const mark = (k, state, extra) => setFlow((f) => ({ ...f, steps: f.steps.map((s) => s.k === k ? { ...s, state, ...extra } : s) }));
 442:     await sleep(900);
 443:     mark('save', 'done');
 444:     const code = p.code || 'PRD-000' + (111 + Math.floor(Math.random() * 80));
 445:     let next = { ...p, code, status: p.status || 'draft', rows: p.rows.map((r, i) => ({ ...r, sku: r.sku || `${(B.en || 'PRD').slice(0, 3).toUpperCase()}-${String(i + 1).padStart(3, '0')}`, barcode: r.barcode || `6221${String(Date.now()).slice(-8)}${i}` })) };
 446:     // Upload
 447:     mark('upload', 'run');
 448:     const pending = next.media.general.filter((f) => f.status !== 'done');
 449:     for (let pct = 0; pct <= 100; pct += 20) {
 450:       await sleep(160);
 451:       next = { ...next, media: { ...next.media, general: next.media.general.map((f, i) => f.status === 'done' ? f : (publishScenario === 'upload_fail' && i === next.media.general.length - 1 && pct >= 60) ? { ...f, status: 'failed', progress: 60, error: 'انقطع الاتصال أثناء الرفع' } : { ...f, status: pct >= 100 ? 'done' : 'uploading', progress: pct }) } };
 452:       setP(next);
 453:     }
 454:     const failed = next.media.general.filter((f) => f.status === 'failed').length;
 455:     if (failed) {
 456:       mark('upload', 'fail', { note: `${failed} صورة فشلت — المسودة محفوظة` });
 457:       if (publish) mark('publish', 'skip');
 458:       setSaved(JSON.stringify(next)); setFlow((f) => ({ ...f, done: 'upload_fail', code }));
 459:       if (isNew) history.replaceState(null, '', '#/products/101?tab=media');
 460:       return;
 461:     }
 462:     mark('upload', 'done');
 463:     if (publish) {
 464:       mark('publish', 'run'); await sleep(800);
 465:       if (publishScenario === 'publish_blocked') {
 466:         mark('publish', 'fail', { note: 'errors.status' });
 467:         setSaved(JSON.stringify(next)); setFlow((f) => ({ ...f, done: 'blocked', code }));
 468:         return;
 469:       }
 470:       next = { ...next, status: 'published' }; mark('publish', 'done');
 471:     }
 472:     setP(next); setSaved(JSON.stringify(next)); setFlow((f) => ({ ...f, done: 'ok', code }));
 473:   };
 474: 
 475:   const onDeactivateLast = () => {
 476:     if (p.status === 'published' && activeRows.length <= 1) { setBlockModal('last'); return true; }
 477:     return false;
 478:   };
 479: 
 480:   const tabs = [
 481:     { value: 'basic', label: 'البيانات الأساسية', num: 1, state: tabState('basic') },
 482:     { value: 'variants', label: 'المتغيرات والأسعار', num: 2, state: tabState('variants') },
 483:     { value: 'media', label: 'الصور والفيديو', num: 3, state: tabState('media') },
 484:     { value: 'review', label: 'المراجعة والنشر', num: 4, state: tabState('review') },
 485:   ];
 486: 
 487:   return (
 488:     <div className="space-y-5">
 489:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'المنتجات', href: '#/products' }, { label: isNew && !p.code ? 'منتج جديد' : (B.ar || p.code) }]}
 490:         title={isNew && !p.code ? 'منتج جديد' : B.ar || 'بدون اسم'}
 491:         badge={<>{p.status ? <StatusBadge s={p.status} /> : <Badge>لم يُحفظ بعد</Badge>}{p.code && <span className="ltr text-[12px] font-semibold px-2.5 py-1 rounded-full v-pill t-2">{p.code}</span>}</>}
 492:         actions={<button className="btn btn-soft" onClick={() => dirty ? setLeave(true) : nav('/products')}><Icon name="arrowRight" size={14} />المنتجات</button>} />
 493: 
 494:       <div className="flex flex-wrap items-center justify-between gap-3 stagger s2">
 495:         <Tabs value={tab.tab} onChange={(t) => setTabQ({ tab: t })} tabs={tabs} />
 496:         <div className="flex items-center gap-3 v-pill rounded-full ps-4 pe-1.5 h-11">
 497:           <span className="text-[12px] t-2">الجاهزية للنشر</span>
 498:           <div className="w-24 h-2 rounded-full hatched-track overflow-hidden"><div className="h-full rounded-full hatched-acc transition-all" style={{ width: `${(readyCount / ready.length) * 100}%` }} /></div>
 499:           <span className={cx('h-8 px-3 rounded-full text-[12px] font-bold num flex items-center', readyCount === ready.length ? 'b-green' : 'v-well t-1')}>{readyCount}/{ready.length}</span>
 500:         </div>
 501:       </div>
 502: 
 503:       {summary && <ErrorSummary title={summary.title} subtitle={summary.subtitle} items={summary.items} onClose={() => setSummary(null)} onJump={(it) => setTabQ({ tab: it.go })} />}
 504: 
 505:       <div className="stagger s3">
 506:         {tab.tab === 'basic' && <BasicTab B={B} set={setBasic} errs={errs.basic} code={p.code} flat={flat} />}
 507:         {tab.tab === 'variants' && (
 508:           <VariantsTab channel={B.channel} canCost={canCost} mode={p.mode}
 509:             setMode={(m) => setP({ ...p, mode: m, rows: m === 'single' ? [p.rows[0] || emptyVariant(null, '', '', 0)].map((r) => ({ ...r, color: null, size: '', capacity: '' })) : p.rows })}
 510:             axes={p.axes} setAxes={(a) => setP({ ...p, axes: a })} rows={p.rows}
 511:             setRows={(rows) => {
 512:               const nowActive = rows.filter((r) => r.status === 'active' && r.available).length;
 513:               if (p.status === 'published' && nowActive === 0) { setBlockModal('last'); return; }
 514:               const removedPrice = p.status === 'published' && rows.some((r) => r.status === 'active' && r.available && ((needRetail && !r.retail) || (needWh && !r.wholesale))) && missingPrice.length === 0;
 515:               if (removedPrice) { setBlockModal('price'); return; }
 516:               setP({ ...p, rows });
 517:             }}
 518:             errs={errs.variantsShown ? vErrs : {}} />
 519:         )}
 520:         {tab.tab === 'media' && <MediaTab media={p.media} setMedia={(m) => setP({ ...p, media: m })} axes={p.axes} mode={p.mode} saved={!!p.status} />}
 521:         {tab.tab === 'review' && <ReviewTab p={p} ready={ready} canCost={canCost} canPublish={canPublish} goto={(t) => setTabQ({ tab: t })} catNode={catNode} />}
 522:       </div>
 523: 
 524:       <StickyBar dirty={dirty} note={p.status ? null : 'الصور هتترفع بعد حفظ المسودة'}>
 525:         {tab.tab !== 'review' && <button className="btn btn-ghost" onClick={() => setTabQ({ tab: tabs[Math.min(3, tabs.findIndex((t) => t.value === tab.tab) + 1)].value })}>التالي<Icon name="chevLeft" size={14} /></button>}
 526:         <button className="btn btn-outline" onClick={() => run(false)} disabled={!!flow && !flow.done}><Icon name="edit" size={14} />{p.status === 'published' ? 'حفظ التعديلات' : 'حفظ كمسودة'}</button>
 527:         {canPublish ? (
 528:           p.status !== 'published' && <button className="btn btn-acc" onClick={() => {
 529:             if (readyCount < ready.length) { setSummary({ title: 'المنتج غير جاهز للنشر', subtitle: 'أكمل البنود التالية، أو احفظه كمسودة لحين الانتهاء.', items: ready.filter((r) => !r.ok && r.tab).map((r) => ({ text: `${r.label} — ${r.detail}`, tab: tabs.find((t) => t.value === r.tab).label, go: r.tab })) }); return; }
 530:             run(true);
 531:           }} disabled={!!flow && !flow.done}><Icon name="send" size={14} />نشر</button>
 532:         ) : <span className="h-10 px-4 rounded-full v-well text-[12px] font-medium flex items-center gap-1.5" title="يتطلب products.publish"><Icon name="lock" size={13} />النشر يتطلب صلاحية</span>}
 533:       </StickyBar>
 534: 
 535:       <PublishFlow flow={flow} onClose={() => setFlow(null)} onRetryUpload={() => { setP({ ...p, media: { ...p.media, general: p.media.general.map((f) => f.status === 'failed' ? { ...f, status: 'queued', progress: 0, error: null } : f) } }); setFlow(null); setTabQ({ tab: 'media' }); }}
 536:         onGoto={(t) => { setFlow(null); setTabQ({ tab: t }); }} />
 537:       <Modal open={!!blockModal} onClose={() => setBlockModal(null)} icon="ban" iconTone="red"
 538:         title={blockModal === 'last' ? 'لا يمكن تعطيل آخر متغير نشط' : 'لا يمكن إزالة سعر مطلوب'}
 539:         subtitle={blockModal === 'last' ? 'المنتج منشور حاليًا، والمنتج المنشور لازم يكون فيه متغير نشط واحد على الأقل.' : `المنتج منشور على قناة «${CHANNEL_LABEL[B.channel]}»، والسعر ده مطلوب لكل متغير نشط. الخادم هيرفض الحفظ.`}>
 540:         <div className="v-subcard p-4 text-[12.5px] t-2 leading-relaxed">
 541:           {canPublish ? 'لو محتاج توقف بيع المنتج مؤقتًا، حوّله لمسودة الأول — هيختفي من المتجر ونقاط البيع، وبعدها تقدر تعدل بحرية.' : 'تحويل المنتج لمسودة يتطلب صلاحية النشر. تواصل مع مسؤول الكتالوج.'}
 542:         </div>
 543:         <div className="flex justify-end gap-2 mt-5">
 544:           <button className="btn btn-soft" onClick={() => setBlockModal(null)}>تراجع عن التغيير</button>
 545:           {canPublish && <button className="btn btn-ink" onClick={() => { setP({ ...p, status: 'draft' }); setBlockModal(null); vtoast('تم تحويل المنتج لمسودة'); }}>تحويل لمسودة</button>}
 546:         </div>
 547:       </Modal>
 548:       <LeaveDialog open={leave} onStay={() => setLeave(false)} onLeave={() => { setLeave(false); nav('/products'); }} />
 549:     </div>
 550:   );
 551: }
