 553: /* ---------- Tab A: Basic ---------- */
 554: function BasicTab({ B, set, errs, code, flat }) {
 555:   const [descLang, setDescLang] = useState('ar');
 556:   return (
 557:     <div className="grid lg:grid-cols-[1fr_340px] gap-5 items-start">
 558:       <div className="space-y-5">
 559:         <SectionCard title="الاسم والتصنيف">
 560:           <div className="grid md:grid-cols-2 gap-4">
 561:             <Field label="اسم المنتج (عربي)" required error={errs.ar} id="ar"><Input value={B.ar} onChange={(e) => set('ar', e.target.value)} error={errs.ar} placeholder="مثال: كنبة زاوية «ميلانو»" /></Field>
 562:             <Field label="اسم المنتج (إنجليزي)" required error={errs.en} id="en"><Input ltr value={B.en} onChange={(e) => set('en', e.target.value)} error={errs.en} placeholder="Milano Corner Sofa" /></Field>
 563:             <Field label="القسم" required error={errs.category}>
 564:               <SearchSelect value={B.category} onChange={(v) => set('category', v)} error={errs.category} placeholder="اختر القسم" emptyText="لا يوجد قسم بهذا الاسم"
 565:                 options={flat.map((f) => ({ value: f.id, label: f.ar, depth: f.depth, sub: f.depth ? null : f.en, note: f.status !== 'active' ? 'غير نشط' : null }))} />
 566:             </Field>
 567:             <Field label="البراند"><SearchSelect value={B.brand} onChange={(v) => set('brand', v)} placeholder="بدون براند" options={BRANDS.map((b) => ({ value: b.id, label: b.ar, sub: b.en, disabled: b.status !== 'active', note: b.status !== 'active' ? 'غير نشط' : null }))} /></Field>
 568:           </div>
 569:           <div className="mt-5">
 570:             <Field label="قناة البيع" required error={errs.channel} hint="بتحدد الأسعار المطلوبة لكل متغير قبل النشر.">
 571:               <div className="grid grid-cols-3 gap-2.5">
 572:                 {[['retail', 'تجزئة', 'سعر التجزئة مطلوب', 'cart'], ['wholesale', 'جملة', 'سعر الجملة مطلوب', 'warehouse'], ['both', 'الاتنين', 'السعرين مطلوبين', 'layers']].map(([k, l, s, ic]) => (
 573:                   <button key={k} type="button" onClick={() => set('channel', k)} className={cx('rounded-[16px] p-3.5 text-start border transition', B.channel === k ? 'border-[var(--accent)] bg-[var(--accent-soft)]' : 'border-[var(--border-field)] hover:bg-[var(--bg-subcard)]')}>
 574:                     <span className={cx('w-8 h-8 rounded-full flex items-center justify-center mb-2', B.channel === k ? 'bg-acc' : 'v-well')}><Icon name={ic} size={15} /></span>
 575:                     <span className="block text-[13px] font-semibold t-1">{l}</span><span className="block text-[11px] t-3">{s}</span>
 576:                   </button>
 577:                 ))}
 578:               </div>
 579:             </Field>
 580:           </div>
 581:         </SectionCard>
 582: 
 583:         <SectionCard title="الوصف والخامة" aside={<Seg value={descLang} onChange={setDescLang} options={[{ value: 'ar', label: 'عربي' }, { value: 'en', label: 'English' }]} />}>
 584:           <div className="space-y-4">
 585:             {descLang === 'ar' ? <>
 586:               <Field label="الوصف"><Textarea rows={4} value={B.desc_ar} onChange={(e) => set('desc_ar', e.target.value)} /></Field>
 587:               <Field label="الخامة"><Input value={B.mat_ar} onChange={(e) => set('mat_ar', e.target.value)} placeholder="مثال: قماش شانيل، خشب زان" /></Field>
 588:             </> : <>
 589:               <Field label="Description"><Textarea rows={4} dir="ltr" className="ltr" value={B.desc_en} onChange={(e) => set('desc_en', e.target.value)} /></Field>
 590:               <Field label="Material"><Input ltr value={B.mat_en} onChange={(e) => set('mat_en', e.target.value)} /></Field>
 591:             </>}
 592:           </div>
 593:         </SectionCard>
 594: 
 595:         <SectionCard title="الأبعاد والضمان">
 596:           <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
 597:             <Field label="الطول"><Input ltr suffix="سم" value={B.l} onChange={(e) => set('l', e.target.value)} /></Field>
 598:             <Field label="العرض"><Input ltr suffix="سم" value={B.w} onChange={(e) => set('w', e.target.value)} /></Field>
 599:             <Field label="الارتفاع"><Input ltr suffix="سم" value={B.h} onChange={(e) => set('h', e.target.value)} /></Field>
 600:             <Field label="الوزن"><Input ltr suffix="كجم" value={B.kg} onChange={(e) => set('kg', e.target.value)} /></Field>
 601:           </div>
 602:           <div className="grid md:grid-cols-[160px_1fr_200px] gap-3 mt-4">
 603:             <Field label="مدة الضمان"><Input ltr suffix="شهر" value={B.warranty} onChange={(e) => set('warranty', e.target.value)} /></Field>
 604:             <Field label="تفاصيل الضمان"><Input value={B.warranty_details} onChange={(e) => set('warranty_details', e.target.value)} /></Field>
 605:             <Field label="بلد المنشأ"><Input value={B.origin} onChange={(e) => set('origin', e.target.value)} /></Field>
 606:           </div>
 607:         </SectionCard>
 608:       </div>
 609: 
 610:       <div className="space-y-5 lg:sticky lg:top-5">
 611:         <div className="v-card p-5">
 612:           <Field label="كود المنتج" hint="بيتولد من الخادم بعد أول حفظ ولا يمكن تعديله.">
 613:             <div className="v-input is-readonly ltr flex items-center justify-between">{code || <span className="t-3">PRD-••••••</span>}<Icon name="lock" size={14} className="t-3" /></div>
 614:           </Field>
 615:           <div className="mt-4"><Field label="الرابط (slug)" hint="اختياري — بيتولد من الاسم الإنجليزي">
 616:             <Input ltr value={B.slug} placeholder={(B.en || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-') || 'auto'} onChange={(e) => set('slug', e.target.value)} />
 617:           </Field></div>
 618:         </div>
 619:         <div className={cx('rounded-[22px] p-5 transition cursor-pointer', B.featured ? 'v-orange' : 'v-card')} onClick={() => set('featured', !B.featured)}>
 620:           <div className="flex items-center justify-between">
 621:             <span className={cx('w-10 h-10 rounded-full flex items-center justify-center', B.featured ? 'bg-white/15' : 'v-well')}><Icon name="star" size={18} /></span>
 622:             <Toggle on={B.featured} onChange={(x) => set('featured', x)} />
 623:           </div>
 624:           <div className={cx('text-[14px] font-semibold mt-3', !B.featured && 't-1')}>منتج مميز</div>
 625:           <div className={cx('text-[12px] mt-0.5', B.featured ? 'text-white/80' : 't-3')}>يظهر في الواجهة الرئيسية للمتجر وأقسام «المختارات».</div>
 626:         </div>
 627:         <div className="v-card p-5">
 628:           <Field label="المورد" hint={null}><SearchSelect value={B.supplier} onChange={(v) => set('supplier', v)} placeholder="اختر المورد" disabled options={[]} /></Field>
 629:           <Banner tone="amber" icon="info" className="mt-3 !p-3">ربط المورد معلّق — الـ API بيقبل <span className="ltr inline-block font-semibold">supplier_id</span> حاليًا بدون التحقق من جدول الموردين.</Banner>
 630:         </div>
 631:       </div>
 632:     </div>
 633:   );
 634: }
