 636: /* ---------- Tab C: Media ---------- */
 637: function MediaTab({ media, setMedia, axes, mode, saved }) {
 638:   const [dragIdx, setDragIdx] = useState(null);
 639:   const [scope, setScope] = useState('general');
 640:   const [sizeErr, setSizeErr] = useState(null);
 641:   const addFiles = (n = 3, target = 'general') => {
 642:     const names = ['living-room-01.jpg', 'angle-left.png', 'fabric-closeup.webp', 'lifestyle.jpg', 'top-view.jpg'];
 643:     const fresh = Array.from({ length: n }).map((_, i) => ({ id: Math.random().toString(36).slice(2), name: names[(media.general.length + i) % names.length], size: (1 + Math.random() * 3).toFixed(1) + 'MB', status: saved ? 'uploading' : 'queued', progress: 0, bg: IMG[(media.general.length + i + 2) % IMG.length] }));
 644:     if (target === 'general') {
 645:       if (media.general.length + n > 10) { setSizeErr('الحد الأقصى ١٠ صور في طلب الرفع الواحد'); return; }
 646:       const next = { ...media, general: [...media.general, ...fresh] };
 647:       setMedia(next);
 648:       if (saved) simulateUpload(next, fresh.map((f) => f.id));
 649:     } else {
 650:       setMedia({ ...media, byVariant: { ...media.byVariant, [target]: [...(media.byVariant[target] || []), ...fresh.slice(0, 1).map((f) => ({ ...f, status: saved ? 'done' : 'queued' }))] } });
 651:     }
 652:   };
 653:   const simulateUpload = (start, ids) => {
 654:     let pct = 0; let cur = start;
 655:     const t = setInterval(() => {
 656:       pct += 20;
 657:       cur = { ...cur, general: cur.general.map((f) => ids.includes(f.id) ? { ...f, progress: pct, status: pct >= 100 ? (f.name.includes('webp') ? 'failed' : 'done') : 'uploading', error: f.name.includes('webp') && pct >= 100 ? 'الأبعاد تتجاوز 6000×6000' : null } : f) };
 658:       setMedia(cur);
 659:       if (pct >= 100) clearInterval(t);
 660:     }, 220);
 661:   };
 662:   const reorder = (to) => {
 663:     if (dragIdx == null || dragIdx === to) return;
 664:     const g = [...media.general]; const [m] = g.splice(dragIdx, 1); g.splice(to, 0, m);
 665:     setMedia({ ...media, general: g }); setDragIdx(to);
 666:   };
 667:   const retry = (id) => {
 668:     const next = { ...media, general: media.general.map((f) => f.id === id ? { ...f, status: 'uploading', progress: 0, error: null, name: f.name.replace('webp', 'jpg') } : f) };
 669:     setMedia(next); simulateUpload(next, [id]);
 670:   };
 671:   const failed = media.general.filter((f) => f.status === 'failed').length;
 672:   const queued = media.general.filter((f) => f.status === 'queued').length;
 673:   return (
 674:     <div className="grid lg:grid-cols-[1fr_340px] gap-5 items-start">
 675:       <div className="space-y-5">
 676:         {!saved && <Banner tone="blue" icon="info" title="الصور هتترفع بعد حفظ المسودة">تقدر تختار الملفات دلوقتي. الرفع الفعلي بيبدأ تلقائيًا بعد ما المنتج والمتغيرات يتحفظوا.</Banner>}
 677:         {failed > 0 && <Banner tone="red" icon="alertCircle" title={`${failed} صورة فشل رفعها`} action={<button className="btn btn-sm btn-ink" onClick={() => media.general.filter((f) => f.status === 'failed').forEach((f) => retry(f.id))}><Icon name="refresh" size={13} />إعادة رفع الكل</button>}>المسودة محفوظة. أعد رفع الصور الفاشلة بدون إنشاء منتج جديد.</Banner>}
 678:         <SectionCard title="صور المنتج" subtitle="اسحب لتغيير الترتيب. الصورة الأولى هي الرئيسية في المتجر." aside={<span className="text-[12px] t-3 num">{media.general.length} / 10</span>}>
 679:           {sizeErr && <Banner tone="red" icon="alertCircle" className="mb-4 pop" onClose={() => setSizeErr(null)}>{sizeErr}</Banner>}
 680:           <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-3">
 681:             {media.general.map((f, i) => (
 682:               <FileTile key={f.id} file={f} index={i + 1} primary={i === 0 && f.status !== 'failed'} draggable
 683:                 onDragStart={() => setDragIdx(i)} onDragOver={(e) => { e.preventDefault(); reorder(i); }} onDrop={() => setDragIdx(null)}
 684:                 onRemove={() => setMedia({ ...media, general: media.general.filter((x) => x.id !== f.id) })} onRetry={() => retry(f.id)} />
 685:             ))}
 686:             {media.general.length < 10 && (
 687:               <button onClick={() => addFiles(2)} className="dropzone aspect-[4/3] sm:aspect-auto min-h-[150px] flex flex-col items-center justify-center gap-2 t-2">
 688:                 <span className="w-10 h-10 rounded-full b-acc flex items-center justify-center"><Icon name="plus" size={18} /></span>
 689:                 <span className="text-[12.5px] font-semibold t-1">إضافة صور</span>
 690:               </button>
 691:             )}
 692:           </div>
 693:           {media.general.length === 0 && <div className="mt-3"><DropZone title="اسحب صور المنتج هنا" rules={['JPG · PNG · WebP', 'حتى 5MB للصورة', 'حتى 6000×6000', 'حتى ١٠ صور في المرة']} onPick={() => addFiles(3)} /></div>}
 694:           {media.general.length > 0 && <div className="flex flex-wrap gap-1.5 mt-4">{['JPG · PNG · WebP', 'حتى 5MB للصورة', 'حتى 6000×6000', 'حتى ١٠ صور في الطلب'].map((r) => <span key={r} className="text-[10.5px] font-medium px-2 py-0.5 rounded-full v-well">{r}</span>)}{queued > 0 && <Badge tone="amber" className="ms-auto">{queued} بانتظار الحفظ</Badge>}</div>}
 695:         </SectionCard>
 696: 
 697:         {mode === 'matrix' && axes.colors.length > 0 && (
 698:           <SectionCard title="صور حسب اللون" subtitle="بتظهر لما العميل يختار اللون ده. اختيارية.">
 699:             <div className="space-y-3">
 700:               {axes.colors.map((c) => {
 701:                 const list = media.byVariant[c.en] || [];
 702:                 return (
 703:                   <div key={c.en} className="v-subcard p-3.5 flex items-center gap-4">
 704:                     <div className="flex items-center gap-2.5 w-[150px] shrink-0"><Swatch c={c.hex} size={28} /><div><div className="text-[12.5px] font-semibold t-1">{c.ar}</div><div className="text-[10.5px] t-3 ltr">{c.en}</div></div></div>
 705:                     <div className="flex-1 flex items-center gap-2 overflow-x-auto">
 706:                       {list.map((f) => <div key={f.id} className="w-16 shrink-0"><FileTile compact file={f} onRemove={() => setMedia({ ...media, byVariant: { ...media.byVariant, [c.en]: list.filter((x) => x.id !== f.id) } })} /></div>)}
 707:                       <button onClick={() => addFiles(1, c.en)} className="dropzone w-16 h-16 shrink-0 flex items-center justify-center t-3"><Icon name="plus" size={16} /></button>
 708:                     </div>
 709:                   </div>
 710:                 );
 711:               })}
 712:             </div>
 713:           </SectionCard>
 714:         )}
 715: 
 716:         <SectionCard title="فيديو المنتج" subtitle="فيديو واحد للمنتج كله — مش مرتبط بمتغير.">
 717:           {media.video ? (
 718:             <div className="flex items-center gap-4 v-subcard p-3.5">
 719:               <div className="w-28 aspect-video rounded-[12px] flex items-center justify-center" style={{ background: IMG[6], color: 'rgba(255,255,255,.7)' }}><Icon name="video" size={22} /></div>
 720:               <div className="flex-1"><div className="text-[12.5px] font-semibold t-1 ltr text-end">{media.video.name}</div><div className="text-[11px] t-3 num">{media.video.size}</div>
 721:                 {media.video.status === 'queued' && <Badge tone="amber" className="mt-1.5">بانتظار الحفظ</Badge>}</div>
 722:               <button className="icon-btn" onClick={() => setMedia({ ...media, video: null })}><Icon name="trash" size={15} /></button>
 723:             </div>
