 806:     : s === 'fail' ? <span className="w-8 h-8 rounded-full b-red flex items-center justify-center"><Icon name="x" size={15} sw={2.6} /></span>
 807:     : s === 'skip' ? <span className="w-8 h-8 rounded-full v-well flex items-center justify-center"><Icon name="minus" size={15} /></span>
 808:     : <span className="w-8 h-8 rounded-full v-well flex items-center justify-center"><span className="w-2 h-2 rounded-full bg-current opacity-40" /></span>;
 809:   const d = flow.done;
 810:   return (
 811:     <Modal open onClose={d ? onClose : null} width={500}
 812:       title={!d ? (flow.publish ? 'جارٍ النشر…' : 'جارٍ الحفظ…') : d === 'ok' ? (flow.publish ? 'تم نشر المنتج' : 'تم حفظ المسودة') : d === 'upload_fail' ? 'المسودة اتحفظت، لكن بعض الصور فشلت' : 'المسودة اتحفظت، لكن النشر اترفض'}
 813:       subtitle={d === 'ok' ? <>كود المنتج <span className="ltr inline-block font-semibold t-1">{flow.code}</span></> : d === 'upload_fail' ? 'ما اتعملش منتج جديد. أعد رفع الصور الفاشلة من تبويب الصور.' : d === 'blocked' ? 'الخادم رفض تحديث الحالة. صلّح البنود دي وجرّب تاني.' : 'ما تقفلش الصفحة لحد ما تخلص الخطوات.'}
 814:       icon={!d ? 'send' : d === 'ok' ? 'checkCircle' : 'alert'} iconTone={!d ? 'acc' : d === 'ok' ? 'green' : 'amber'}>
 815:       <div className="v-subcard p-2">
 816:         {flow.steps.map((s, i) => (
 817:           <div key={s.k} className="flex items-center gap-3 p-2.5">
 818:             {icon(s.state)}
 819:             <div className="flex-1"><div className={cx('text-[13px] font-medium', s.state === 'wait' || s.state === 'skip' ? 't-3' : 't-1')}>{s.label}</div>{s.note && <div className="text-[11.5px] mt-0.5" style={{ color: s.state === 'fail' ? 'var(--badge-red-text)' : undefined }}>{s.note}</div>}</div>
 820:             <span className="text-[10.5px] t-3 num">{i + 1}/{flow.steps.length}</span>
 821:           </div>
 822:         ))}
 823:       </div>
 824:       {d === 'blocked' && (
 825:         <div className="mt-4 pop">
 826:           <div className="text-[11.5px] t-3 mb-2 ltr text-end">422 · errors.status</div>
 827:           <div className="space-y-1.5">
 828:             {[{ t: 'القسم الأب «غرف المعيشة» أصبح غير نشط', tab: 'basic', tl: 'البيانات الأساسية' }, { t: 'المتغير «بيج · 280×180» بدون سعر جملة', tab: 'variants', tl: 'المتغيرات' }].map((x) => (
 829:               <button key={x.t} onClick={() => onGoto(x.tab)} className="w-full flex items-center gap-3 p-3 rounded-[14px] b-red text-start hover:opacity-90"><Icon name="alertCircle" size={15} /><span className="flex-1 text-[12.5px] font-medium">{x.t}</span><span className="text-[11px] opacity-80 flex items-center gap-1">{x.tl}<Icon name="chevLeft" size={12} /></span></button>
 830:             ))}
 831:           </div>
 832:         </div>
 833:       )}
 834:       {d && (
 835:         <div className="flex justify-end gap-2 mt-5">
 836:           {d === 'ok' ? <><button className="btn btn-soft" onClick={() => { onClose(); nav('/products'); }}>كل المنتجات</button><button className="btn btn-ink" onClick={onClose}>متابعة التعديل</button></>
 837:             : d === 'upload_fail' ? <><button className="btn btn-soft" onClick={onClose}>لاحقًا</button><button className="btn btn-ink" onClick={onRetryUpload}><Icon name="refresh" size={14} />إعادة رفع الصور الفاشلة</button></>
 838:             : <button className="btn btn-ink" onClick={onClose}>فهمت</button>}
 839:         </div>
 840:       )}
 841:     </Modal>
 842:   );
 843: }
