 849: /* ---------- Hash router with query (URL-persisted page/search/filters) ---------- */
 850: function parseHash() {
 851:   const h = location.hash.replace(/^#/, '') || (/^\/(products|brands)(\/|$)/.test(location.pathname) ? location.pathname : '/products');
 852:   const [path, qs] = h.split('?');
 853:   const q = Object.fromEntries(new URLSearchParams(qs || ''));
 854:   return { path, q, parts: path.split('/').filter(Boolean) };
 855: }
 856: function useRoute() {
 857:   const [r, setR] = useState(parseHash());
 858:   useEffect(() => { const h = () => setR(parseHash()); window.addEventListener('hashchange', h); return () => window.removeEventListener('hashchange', h); }, []);
 859:   return r;
 860: }
 861: function nav(path, q) {
 862:   const qs = q ? new URLSearchParams(Object.entries(q).filter(([, v]) => v !== null && v !== undefined && v !== '' && v !== false)).toString() : '';
 863:   location.hash = path + (qs ? '?' + qs : '');
 864: }
 865: // Update query in place (replace), keeps URL as source of truth for list state
 866: function useQueryState(defaults) {
 867:   const r = useRoute();
 868:   const state = { ...defaults, ...r.q };
 869:   const set = (patch) => {
 870:     const next = { ...state, ...patch };
 871:     Object.keys(defaults).forEach((k) => { if (String(next[k]) === String(defaults[k])) delete next[k]; });
 872:     const qs = new URLSearchParams(Object.entries(next).filter(([, v]) => v !== null && v !== undefined && v !== '')).toString();
 873:     history.replaceState(null, '', '#' + r.path + (qs ? '?' + qs : ''));
 874:     window.dispatchEvent(new HashChangeEvent('hashchange'));
 875:   };
 876:   return [state, set];
 877: }
