 879: /* ---------- Simulated latency hook, honouring the global "screen state" tweak ---------- */
 880: function useLoad(deps = [], ms = 650) {
 881:   const { screenState } = useApp();
 882:   const [phase, setPhase] = useState('loading');
 883:   const [nonce, setNonce] = useState(0);
 884:   useEffect(() => {
 885:     setPhase('loading');
 886:     if (screenState === 'loading') return;
 887:     const t = setTimeout(() => setPhase(screenState === 'error' ? 'error' : screenState === 'empty' ? 'empty' : 'ready'), ms);
 888:     return () => clearTimeout(t);
 889:   }, [...deps, nonce, screenState]);
 890:   return [phase, () => setNonce((n) => n + 1)];
 891: }
