 893: function useUnsavedGuard(dirty) {
 894:   useEffect(() => {
 895:     const h = (e) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } };
 896:     window.addEventListener('beforeunload', h);
 897:     return () => window.removeEventListener('beforeunload', h);
 898:   }, [dirty]);
 899: }
