1028: function SearchSelect({ value, onChange, options = [], placeholder = 'اختر…', error, disabled, loading: forceLoading, emptyText, multi, clearable = true, renderOption, asyncSim = true, searchPlaceholder = 'ابحث…' }) {
1029:   const [open, setOpen] = useState(false);
