1040:   }, [q, open]);
1041:   const isLoading = forceLoading || loading;
1042:   const list = options.filter((o) => !q || (o.label + ' ' + (o.sub || '')).toLowerCase().includes(q.toLowerCase()));
1043:   const selected = multi ? options.filter((o) => (value || []).includes(o.value)) : options.find((o) => o.value === value);
1044:   const pick = (o) => {
1045:     if (multi) {
1046:       const cur = value || [];
1047:       onChange(cur.includes(o.value) ? cur.filter((v) => v !== o.value) : [...cur, o.value]);
1048:     } else { onChange(o.value); setOpen(false); setQ(''); }
1049:   };
1050:   const onKey = (e) => {
1051:     if (e.key === 'ArrowDown') { e.preventDefault(); setHi((h) => Math.min(h + 1, list.length - 1)); }
1052:     if (e.key === 'ArrowUp') { e.preventDefault(); setHi((h) => Math.max(h - 1, 0)); }
1053:     if (e.key === 'Enter' && list[hi]) { e.preventDefault(); pick(list[hi]); }
1054:     if (e.key === 'Escape') setOpen(false);
1055:   };
1056:   return (
1057:     <div className="relative" ref={ref}>
1058:       <button type="button" disabled={disabled} onClick={() => setOpen(!open)}
1059:         className={cx('v-input flex items-center justify-between gap-2 text-start', open && 'is-focus', error && 'is-error', disabled && 'is-disabled', multi && selected.length && '!h-auto min-h-[42px] py-1.5')}>
1060:         <span className="flex-1 min-w-0 flex items-center gap-1.5 flex-wrap">
1061:           {multi ? (selected.length ? selected.map((s) => (
1062:             <span key={s.value} className="inline-flex items-center gap-1 ps-2.5 pe-1 h-7 rounded-full text-[12px] font-medium" style={{ background: 'var(--bg-card)', border: '1px solid var(--border-field)' }}>
1063:               {s.label}
1064:               <span role="button" onClick={(e) => { e.stopPropagation(); pick(s); }} className="w-5 h-5 rounded-full inline-flex items-center justify-center hover:bg-[var(--bg-subcard-hover)] t-3"><Icon name="x" size={11} /></span>
1065:             </span>
1066:           )) : <span className="t-3">{placeholder}</span>)
1067:             : selected ? <span className="truncate flex items-center gap-2">{selected.icon}{selected.label}{selected.sub && <span className="t-3 text-[11.5px]">· {selected.sub}</span>}</span>
1068:             : <span className="t-3">{placeholder}</span>}
1069:         </span>
1070:         {!multi && clearable && selected && !disabled && (
1071:           <span role="button" onClick={(e) => { e.stopPropagation(); onChange(null); }} className="w-6 h-6 rounded-full inline-flex items-center justify-center t-3 hover:bg-[var(--bg-subcard-hover)]"><Icon name="x" size={12} /></span>
1072:         )}
1073:         <Icon name="chevDown" size={14} className={cx('t-3 transition-transform', open && 'rotate-180')} />
1074:       </button>
1075:       {open && (
1076:         <div className="pop absolute z-40 mt-2 w-full min-w-[260px] v-card p-2" style={{ boxShadow: 'var(--shadow-pop)', borderRadius: 18 }}>
1077:           <div className="relative mb-1.5">
1078:             <Icon name="search" size={14} className="absolute top-1/2 -translate-y-1/2 start-3 t-3" />
1079:             <input autoFocus value={q} onChange={(e) => { setQ(e.target.value); setHi(0); }} onKeyDown={onKey} placeholder={searchPlaceholder}
1080:               className="w-full h-9 rounded-xl ps-9 pe-8 text-[12.5px] outline-none" style={{ background: 'var(--bg-subcard)', color: 'var(--text-primary)' }} />
1081:             {isLoading && <Spinner size={14} className="absolute top-1/2 -translate-y-1/2 end-3 t-acc" />}
1082:           </div>
1083:           <div className="max-h-[248px] overflow-y-auto">
1084:             {isLoading ? (
1085:               <div className="p-2 space-y-3">{[0, 1, 2].map((i) => <div key={i} className="flex items-center gap-2.5"><Skel w={22} h={22} r={8} /><Skel w={`${70 - i * 15}%`} h={10} /></div>)}</div>
1086:             ) : list.length === 0 ? (
1087:               <div className="py-6 px-3 text-center">
1088:                 <div className="w-10 h-10 rounded-full v-well mx-auto flex items-center justify-center mb-2"><Icon name="search" size={16} /></div>
1089:                 <div className="text-[12.5px] font-semibold t-1">{emptyText || 'لا توجد نتائج'}</div>
1090:                 {q && <div className="text-[11.5px] t-3 mt-0.5">لا شيء يطابق «{q}»</div>}
1091:               </div>
1092:             ) : list.map((o, i) => {
1093:               const sel = multi ? (value || []).includes(o.value) : o.value === value;
1094:               return (
1095:                 <button type="button" key={o.value} onMouseEnter={() => setHi(i)} onClick={() => !o.disabled && pick(o)} disabled={o.disabled}
1096:                   className={cx('w-full flex items-center gap-2.5 px-2.5 py-2 rounded-xl text-start text-[12.5px] transition', hi === i && 'bg-[var(--bg-subcard)]', o.disabled && 'opacity-40 cursor-not-allowed')}
1097:                   style={{ paddingInlineStart: o.depth ? 10 + o.depth * 16 : undefined }}>
1098:                   {multi && <Check on={sel} />}
1099:                   {o.icon}
1100:                   <span className="flex-1 min-w-0">
1101:                     <span className={cx('block truncate', sel ? 'font-semibold t-1' : 't-1')}>{o.label}</span>
1102:                     {o.sub && <span className="block text-[11px] t-3 truncate">{o.sub}</span>}
1103:                   </span>
1104:                   {o.note && <span className="text-[10.5px] t-3">{o.note}</span>}
1105:                   {!multi && sel && <Icon name="check" size={14} className="t-acc" sw={2.4} />}
1106:                 </button>
1107:               );
1108:             })}
1109:           </div>
1110:         </div>
1111:       )}
1112:     </div>
1113:   );
1114: }
