1116: /* ---------------- Modal / Confirm ---------------- */
1117: function Modal({ open, onClose, children, width = 460, title, subtitle, icon, iconTone = 'acc', footer }) {
1118:   useEffect(() => {
1119:     if (!open) return;
1120:     const h = (e) => e.key === 'Escape' && onClose && onClose();
1121:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
1122:   }, [open]);
1123:   if (!open) return null;
1124:   return (
1125:     <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 fade" style={{ background: 'var(--overlay)', backdropFilter: 'blur(3px)' }} onMouseDown={(e) => e.target === e.currentTarget && onClose && onClose()}>
1126:       <div className="pop v-card w-full overflow-hidden" style={{ maxWidth: width, boxShadow: 'var(--shadow-pop)', borderRadius: 26 }}>
1127:         {(title || icon) && (
1128:           <div className="p-6 pb-0 flex items-start gap-3.5">
1129:             {icon && <span className={cx('w-11 h-11 rounded-full flex items-center justify-center shrink-0', 'b-' + iconTone)}><Icon name={icon} size={19} /></span>}
1130:             <div className="flex-1 min-w-0 pt-0.5">
1131:               <h3 className="font-display text-[17px] font-semibold t-1">{title}</h3>
1132:               {subtitle && <p className="text-[13px] t-2 mt-1 leading-relaxed text-pretty">{subtitle}</p>}
1133:             </div>
1134:             {onClose && <button className="icon-btn -mt-1 -me-1" onClick={onClose}><Icon name="x" size={16} /></button>}
1135:           </div>
1136:         )}
1137:         <div className="p-6">{children}</div>
1138:         {footer && <div className="px-6 pb-6 -mt-2 flex items-center justify-end gap-2">{footer}</div>}
1139:       </div>
1140:     </div>
1141:   );
1142: }
