1144: // Confirm with server-rejection state
1145: function ConfirmDialog({ open, onClose, title, message, confirmLabel = 'تأكيد', danger, onConfirm, serverError, icon }) {
1146:   const [busy, setBusy] = useState(false);
1147:   const [err, setErr] = useState(null);
1148:   useEffect(() => { if (open) { setErr(null); setBusy(false); } }, [open]);
1149:   const go = async () => {
1150:     setBusy(true); setErr(null);
1151:     await new Promise((r) => setTimeout(r, 700));
1152:     if (serverError) { setErr(serverError); setBusy(false); return; }
1153:     setBusy(false); onConfirm && onConfirm(); onClose();
1154:   };
1155:   return (
1156:     <Modal open={open} onClose={busy ? null : onClose} title={title} subtitle={message} icon={icon || (danger ? 'trash' : 'alert')} iconTone={danger ? 'red' : 'amber'}>
1157:       {err && (
1158:         <div className="pop rounded-2xl p-3.5 mb-1 flex gap-3 b-red">
1159:           <Icon name="ban" size={17} className="mt-0.5" />
1160:           <div className="text-[12.5px] leading-relaxed">
1161:             <div className="font-semibold">{err.title}</div>
1162:             <div className="opacity-90 mt-0.5">{err.body}</div>
1163:             {err.items && <ul className="mt-2 space-y-1">{err.items.map((i) => <li key={i} className="flex items-center gap-1.5"><span className="w-1 h-1 rounded-full bg-current" />{i}</li>)}</ul>}
1164:           </div>
1165:         </div>
1166:       )}
1167:       <div className="flex items-center justify-end gap-2 mt-3">
1168:         <button className="btn btn-soft" onClick={onClose} disabled={busy}>{err ? 'إغلاق' : 'إلغاء'}</button>
1169:         {!err && <button className={cx('btn', danger ? 'btn-acc' : 'btn-ink')} style={danger ? { background: 'var(--badge-red-text)', boxShadow: 'none' } : null} onClick={go} disabled={busy}>
1170:           {busy && <Spinner size={14} />}{confirmLabel}
1171:         </button>}
1172:       </div>
1173:     </Modal>
1174:   );
1175: }
