1247: /* ---------------- Pagination (server meta) ---------------- */
1248: function Pagination({ meta, onPage, onPerPage }) {
1249:   const { current_page: p, last_page: last, per_page, total, from, to } = meta;
1250:   const pages = [];
1251:   for (let i = 1; i <= last; i++) if (i === 1 || i === last || Math.abs(i - p) <= 1) pages.push(i); else if (pages[pages.length - 1] !== '…') pages.push('…');
1252:   return (
1253:     <div className="flex flex-wrap items-center justify-between gap-3 px-5 py-3.5 v-border-t">
1254:       <div className="flex items-center gap-3 text-[12px] t-2">
1255:         <span>عرض <b className="t-1 num">{from}–{to}</b> من <b className="t-1 num">{total}</b></span>
1256:         <span className="w-px h-4" style={{ background: 'var(--divider-color)' }} />
1257:         <span className="flex items-center gap-1.5">لكل صفحة
1258:           <select value={per_page} onChange={(e) => onPerPage(+e.target.value)} className="h-8 rounded-full px-2.5 text-[12px] font-semibold outline-none" style={{ background: 'var(--bg-subcard)', color: 'var(--text-primary)' }}>
1259:             {[10, 15, 25, 50].map((n) => <option key={n} value={n}>{n}</option>)}
1260:           </select>
1261:         </span>
1262:       </div>
1263:       <div className="flex items-center gap-1">
1264:         <button className="icon-btn" disabled={p <= 1} onClick={() => onPage(p - 1)} style={{ opacity: p <= 1 ? .35 : 1 }}><Icon name="chevRight" size={15} /></button>
1265:         {pages.map((n, i) => n === '…' ? <span key={i} className="w-8 text-center t-3 text-[12px]">…</span> : (
1266:           <button key={i} onClick={() => onPage(n)} className={cx('min-w-[32px] h-8 px-2 rounded-full text-[12px] font-semibold num transition', n === p ? 'bg-ink' : 't-2 hover:bg-[var(--bg-subcard)]')}>{n}</button>
1267:         ))}
1268:         <button className="icon-btn" disabled={p >= last} onClick={() => onPage(p + 1)} style={{ opacity: p >= last ? .35 : 1 }}><Icon name="chevLeft" size={15} /></button>
1269:       </div>
1270:     </div>
1271:   );
1272: }
