1274: /* ---------------- DataTable ---------------- */
1275: function DataTable({ columns, rows, state = 'ready', meta, onPage, onPerPage, onRetry, empty, toolbar, rowKey = 'id', onRowClick, skeletonRows = 6, filtered }) {
1276:   return (
1277:     <div className="v-card overflow-hidden">
1278:       {toolbar && <div className="p-4 v-border-b">{toolbar}</div>}
1279:       {state === 'error' ? <ErrorState onRetry={onRetry} code="GET /api/admin/… → 500" /> :
1280:        state === 'empty' || (state === 'ready' && rows.length === 0) ? (empty || <EmptyState title={filtered ? 'لا نتائج مطابقة للفلاتر' : 'لا توجد بيانات بعد'} body={filtered ? 'جرّب تعديل البحث أو إزالة بعض الفلاتر.' : null} />) : (
1281:         <div className="overflow-x-auto">
1282:           <table className="v-table">
1283:             <thead><tr>{columns.map((c) => <th key={c.key} style={{ width: c.width, textAlign: c.align }}>{c.label}</th>)}</tr></thead>
1284:             <tbody>
1285:               {state === 'loading' ? Array.from({ length: skeletonRows }).map((_, i) => (
1286:                 <tr key={i}>{columns.map((c, j) => <td key={c.key}>{c.skel ? c.skel(i) : <Skel w={j === 0 ? '70%' : `${40 + ((i * 7 + j * 13) % 40)}%`} h={10} />}</td>)}</tr>
1287:               )) : rows.map((r, i) => (
1288:                 <tr key={r[rowKey]} onClick={() => onRowClick && onRowClick(r)} className={cx(onRowClick && 'cursor-pointer')}>
1289:                   {columns.map((c) => <td key={c.key} style={{ textAlign: c.align }}>{c.render ? c.render(r, i) : r[c.key]}</td>)}
1290:                 </tr>
1291:               ))}
1292:             </tbody>
1293:           </table>
1294:         </div>
1295:       )}
1296:       {meta && state !== 'error' && state !== 'empty' && rows.length > 0 && <Pagination meta={meta} onPage={onPage} onPerPage={onPerPage} />}
1297:       {meta && state === 'loading' && (
1298:         <div className="flex items-center justify-between px-5 py-3.5 v-border-t"><Skel w={140} h={10} /><Skel w={160} h={26} r={999} /></div>
1299:       )}
1300:     </div>
1301:   );
1302: }
