1346: /* ---------------- Tabs ---------------- */
1347: function Tabs({ value, onChange, tabs }) {
1348:   return (
1349:     <div className="seg !p-1.5">
1350:       {tabs.map((t) => (
1351:         <button key={t.value} type="button" onClick={() => onChange(t.value)} className={cx('!px-4 !py-2 !text-[12.5px] flex items-center gap-2', value === t.value && 'on')}>
