1512: // Product form — Variants & pricing tab
1513: const PRESET_COLORS = [
1514:   { ar: 'رمادي فحمي', en: 'Charcoal', hex: '#3d3a40' }, { ar: 'بيج', en: 'Beige', hex: '#d8c6a8' },
1515:   { ar: 'أزرق نيلي', en: 'Navy', hex: '#24324f' }, { ar: 'أخضر زيتي', en: 'Olive', hex: '#6b6b3f' },
1516:   { ar: 'تيراكوتا', en: 'Terracotta', hex: '#c65f3c' }, { ar: 'أبيض عاجي', en: 'Ivory', hex: '#f3ede2' },
1517: ];
1518: const vKey = (c, s, cap) => [(c && c.en || '').trim().toLowerCase(), (s || '').trim().toLowerCase(), (cap || '').trim().toLowerCase()].join('|');
1519: const priceOk = (x) => x === '' || x == null || /^\d+(\.\d{1,2})?$/.test(String(x));
1520: 
1521: function emptyVariant(c, s, cap, i) {
1522:   return { _id: Math.random().toString(36).slice(2), color: c || null, size: s || '', capacity: cap || '', sku: '', barcode: '', retail: '', wholesale: '', cost: '', compare: '', weight: '', reorder: '', order: i + 1, status: 'active', available: true };
1523: }
1524: 
1525: function validateVariants(rows, channel, mode) {
1526:   const errs = {}; const seen = {};
1527:   rows.forEach((r, i) => {
1528:     const e = {};
1529:     if (r.color && (r.color.ar || r.color.hex) && !r.color.en) e.color_en = 'الاسم الإنجليزي للون مطلوب';
1530:     ['retail', 'wholesale', 'cost', 'compare'].forEach((k) => { if (!priceOk(r[k])) e[k] = 'منزلتين عشريتين بحد أقصى'; });
1531:     if (r.status === 'active') {
1532:       if ((channel === 'retail' || channel === 'both') && !r.retail) e.retail = 'سعر التجزئة مطلوب';
1533:       if ((channel === 'wholesale' || channel === 'both') && !r.wholesale) e.wholesale = 'سعر الجملة مطلوب';
1534:     }
1535:     if (r.compare && r.retail && +r.compare <= +r.retail) e.compare = 'لازم يكون أعلى من سعر التجزئة';
1536:     const k = vKey(r.color, r.size, r.capacity);
1537:     if (mode === 'matrix') { if (seen[k] != null) { e.dup = `نفس تركيبة الصف ${seen[k] + 1}`; } else seen[k] = i; }
1538:     if (Object.keys(e).length) errs[r._id] = e;
1539:   });
1540:   return errs;
1541: }
