1555:         <input value={t} onChange={(e) => setT(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); add(t); } if (e.key === 'Backspace' && !t && values.length) onChange(values.slice(0, -1)); }}
1556:           placeholder={values.length ? '' : placeholder} className={cx('flex-1 min-w-[90px] h-7 bg-transparent outline-none text-[12.5px] px-1.5', ltr && 'ltr')} style={{ color: 'var(--text-primary)' }} />
1557:       </div>
