1599: function VariantsTab({ channel, mode, setMode, axes, setAxes, rows, setRows, errs, canCost }) {
1600:   const [sel, setSel] = useState([]);
1601:   const [open, setOpen] = useState({});
1602:   const [bulk, setBulk] = useState({ field: 'retail', value: '' });
1603:   const [genNote, setGenNote] = useState(null);
1604:   const gridRef = useRef(null);
1605:   const priceCols = [
1606:     { k: 'retail', l: 'سعر التجزئة', req: channel !== 'wholesale' },
1607:     { k: 'wholesale', l: 'سعر الجملة', req: channel !== 'retail' },
1608:     ...(canCost ? [{ k: 'cost', l: 'التكلفة', req: false }] : []),
1609:     { k: 'compare', l: 'سعر المقارنة', req: false },
1610:   ];
1611:   const combos = (axes.colors.length || 1) * (axes.sizes.length || 1) * (axes.capacities.length || 1);
1612:   const anyAxis = axes.colors.length + axes.sizes.length + axes.capacities.length > 0;
1613: 
1614:   const generate = () => {
1615:     const cs = axes.colors.length ? axes.colors : [null];
1616:     const ss = axes.sizes.length ? axes.sizes : [''];
1617:     const ps = axes.capacities.length ? axes.capacities : [''];
1618:     const existing = Object.fromEntries(rows.map((r) => [vKey(r.color, r.size, r.capacity), r]));
1619:     const next = []; let kept = 0, added = 0;
1620:     cs.forEach((c) => ss.forEach((s) => ps.forEach((p) => {
1621:       const k = vKey(c, s, p);
1622:       if (existing[k]) { next.push({ ...existing[k], color: c }); kept++; } else { next.push(emptyVariant(c, s, p, next.length)); added++; }
1623:     })));
1624:     const removed = rows.length - kept;
1625:     setRows(next.slice(0, 100)); setSel([]);
1626:     setGenNote({ kept, added, removed, capped: next.length > 100 });
1627:   };
1628:   const upd = (id, patch) => setRows(rows.map((r) => r._id === id ? { ...r, ...patch } : r));
1629:   const copyDown = (k) => {
1630:     const src = rows.find((r) => (sel.length ? sel.includes(r._id) : true) && r[k] !== '');
1631:     if (!src) return;
1632:     setRows(rows.map((r) => (!sel.length || sel.includes(r._id)) ? { ...r, [k]: src[k] } : r));
1633:     vtoast(`تم نسخ ${src[k]} ${sel.length ? 'للصفوف المحددة' : 'لكل الصفوف'}`);
1634:   };
1635:   const applyBulk = () => {
1636:     if (!bulk.value || !priceOk(bulk.value)) { vtoast('أدخل سعر صالح (منزلتين عشريتين)', 'error'); return; }
1637:     setRows(rows.map((r) => sel.includes(r._id) ? { ...r, [bulk.field]: bulk.value } : r));
1638:     vtoast(`تم تطبيق السعر على ${sel.length} صف`);
1639:   };
1640:   const onKey = (e, ri, ci) => {
