 361:     .sidebar.expanded-subcats .subcat-item {
 362:       max-height: 30px;
 363:       opacity: 1;
 364:     }
 365: 
 366:     .subcat-item.active {
 367:       color: var(--text);
 368:       font-weight: 600;
