 370: 
 371:     /* ================= CAROUSEL VIEW ================= */
 372:     .carousel-view {
 373:       position: relative;
 374:       width: 100%;
 375:       height: 100vh;
 376:       display: flex;
 377:       flex-direction: column;
 378:       align-items: center;
 379:       justify-content: center;
 380:       overflow: hidden;
 381:       transition: opacity 0.5s ease, transform 0.6s ease;
 382:       background: radial-gradient(circle at 50% 45%, #f9fbfd 0%, #ffffff 70%);
 383:     }
 384: 
 385:     .carousel-view.hidden {
 386:       opacity: 0;
 387:       pointer-events: none;
 388:       position: absolute;
 389:       top: 0;
 390:       left: 0;
 391:     }
 392: 
 393:     /* Scroll Hint Pill */
 394:     .scroll-hint {
 395:       position: absolute;
 396:       bottom: 26px;
 397:       display: flex;
 398:       align-items: center;
 399:       gap: 8px;
 400:       font-family: 'Oswald', sans-serif;
 401:       font-size: 11px;
 402:       font-weight: 400;
 403:       letter-spacing: 0.8px;
 404:       text-transform: uppercase;
 405:       color: #999;
 406:       opacity: 0.8;
 407:       animation: bounceHint 2s infinite ease-in-out;
 408:     }
 409: 
 410:     @keyframes bounceHint {
 411:       0%, 100% { transform: translateY(0); }
 412:       50% { transform: translateY(-5px); }
 413:     }
 414: 
 415:     .stage {
 416:       position: relative;
 417:       width: 100%;
 418:       max-width: 1200px;
 419:       height: 420px;
 420:       display: flex;
 421:       align-items: center;
 422:       justify-content: center;
 423:       margin-top: -20px;
 424:     }
 425: 
 426:     .bag-slot {
 427:       position: absolute;
 428:       transition: all 0.85s cubic-bezier(0.22, 1, 0.36, 1);
 429:       cursor: pointer;
 430:       display: flex;
 431:       flex-direction: column;
 432:       align-items: center;
 433:     }
 434: 
 435:     .bag-slot img {
 436:       width: 420px;
 437:       height: 320px;
 438:       object-fit: contain;
 439:       mix-blend-mode: multiply;
 440:       transition: transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
 441:       pointer-events: none;
 442:     }
 443: 
 444:     /* Realistic drop shadow underneath bag */
 445:     .bag-shadow {
 446:       width: 250px;
 447:       height: 24px;
 448:       background: radial-gradient(ellipse at center, rgba(0,0,0,0.22) 0%, rgba(0,0,0,0) 72%);
 449:       border-radius: 50%;
 450:       margin-top: 6px;
 451:       transition: all 0.85s cubic-bezier(0.22, 1, 0.36, 1);
 452:     }
 453: 
 454:     /* Slot 3D Positions */
 455:     .bag-slot.center {
