 457:       z-index: 30;
 458:       filter: blur(0px);
 459:       opacity: 1;
 460:     }
 461:     .bag-slot.center img {
 462:       transform: rotate(-6deg);
 463:     }
 464: 
 465:     .bag-slot.left {
 466:       transform: translate3d(-390px, 15px, -100px) scale(0.62);
 467:       z-index: 10;
 468:       filter: blur(6px);
 469:       opacity: 0.75;
 470:     }
 471:     .bag-slot.left img {
 472:       transform: rotate(-10deg);
 473:     }
 474: 
 475:     .bag-slot.right {
 476:       transform: translate3d(390px, 15px, -100px) scale(0.62);
 477:       z-index: 10;
 478:       filter: blur(6px);
 479:       opacity: 0.75;
 480:     }
 481:     .bag-slot.right img {
 482:       transform: rotate(-3deg);
 483:     }
