1357:     // Update 3D Stage Carousel
1358:     function updateCarousel() {
1359:       const total = products.length;
1360:       const leftIdx = (activeIndex - 1 + total) % total;
1361:       const rightIdx = (activeIndex + 1) % total;
1362: 
1363:       const slots = [
1364:         document.getElementById('slot-0'),
1365:         document.getElementById('slot-1'),
1366:         document.getElementById('slot-2')
1367:       ];
1368: 
1369:       // Update positions and classes
1370:       slots.forEach((slot, idx) => {
1371:         const img = slot.querySelector('img');
1372:         img.src = products[idx].img;
1373:         img.className = products[idx].tint;
1374: 
1375:         slot.className = 'bag-slot';
1376:         if (idx === activeIndex) {
1377:           slot.classList.add('center');
1378:         } else if (idx === leftIdx) {
1379:           slot.classList.add('left');
1380:         } else if (idx === rightIdx) {
1381:           slot.classList.add('right');
1382:         }
1383:       });
1384: 
1385:       // Update Text with smooth fade-and-slide
1386:       const info = document.getElementById('carouselInfo');
1387:       info.classList.add('fade-out');
1388:       setTimeout(() => {
1389:         const current = products[activeIndex];
1390:         document.getElementById('brandTitle').textContent = current.brand;
1391:         document.getElementById('bagSubtitle').innerHTML = `${current.subtitle} &nbsp;|&nbsp; ${current.price}`;
1392:         info.classList.remove('fade-out');
1393:       }, 220);
1394: 
1395:       // Update Sidebar active state
1396:       document.querySelectorAll('.cat-item').forEach((item, idx) => {
1397:         if (idx === activeIndex) item.classList.add('active');
1398:         else item.classList.remove('active');
1399:       });
1400:     }
1401: 
1402:     function selectSlide(index) {
1403:       if (index === activeIndex) {
1404:         openDetails();
1405:         return;
1406:       }
1407:       activeIndex = index;
1408:       updateCarousel();
1409:     }
1410: 
1411:     function navigateCarousel(direction) {
1412:       const total = products.length;
1413:       activeIndex = (activeIndex + direction + total) % total;
1414:       updateCarousel();
1415:     }
1416: 
1417:     // Filter by Sidebar Item
