1427:     // ================= MOUSE WHEEL SCROLL LOGIC =================
1428:     // Seamlessly transitions 3D carousel on wheel scroll
1429:     window.addEventListener('wheel', (e) => {
1430:       // Only handle wheel when in carousel view
1431:       if (currentMode !== 'carousel') return;
1432:       if (document.getElementById('detailsView').classList.contains('active')) return;
1433: 
1434:       if (isScrollLocked) return;
1435: 
1436:       if (Math.abs(e.deltaY) > 25) {
1437:         isScrollLocked = true;
1438:         if (e.deltaY > 0) {
1439:           navigateCarousel(1); // Scroll down -> next bag
1440:         } else {
1441:           navigateCarousel(-1); // Scroll up -> prev bag
1442:         }
1443: 
1444:         setTimeout(() => {
1445:           isScrollLocked = false;
1446:         }, 550);
1447:       }
1448:     }, { passive: true });
1449: 
1450:     // Keyboard Navigation
1451:     window.addEventListener('keydown', (e) => {
1452:       if (currentMode !== 'carousel' || document.getElementById('detailsView').classList.contains('active')) return;
1453:       if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
1454:         navigateCarousel(1);
1455:       } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
1456:         navigateCarousel(-1);
1457:       }
1458:     });
1459: 
1460:     // Touch Swipe Navigation for Mobile / Tablets
1461:     let touchStartX = 0;
1462:     let touchStartY = 0;
1463:     window.addEventListener('touchstart', (e) => {
1464:       touchStartX = e.touches[0].clientX;
1465:       touchStartY = e.touches[0].clientY;
1466:     }, { passive: true });
1467: 
1468:     window.addEventListener('touchend', (e) => {
1469:       if (currentMode !== 'carousel' || document.getElementById('detailsView').classList.contains('active')) return;
1470:       const touchEndX = e.changedTouches[0].clientX;
1471:       const touchEndY = e.changedTouches[0].clientY;
1472:       const diffX = touchStartX - touchEndX;
1473:       const diffY = touchStartY - touchEndY;
1474: 
1475:       if (Math.abs(diffX) > 40 && Math.abs(diffX) > Math.abs(diffY)) {
1476:         if (diffX > 0) navigateCarousel(1);
1477:         else navigateCarousel(-1);
1478:       }
1479:     }, { passive: true });
