 5: namespace App\Models;
 6: 
 7: use App\Enums\ProductStatus;
 8: use App\Enums\SalesChannel;
 9: use Database\Factories\ProductFactory;
10: use Illuminate\Database\Eloquent\Factories\HasFactory;
11: use Illuminate\Database\Eloquent\Model;
12: use Illuminate\Database\Eloquent\Relations\BelongsTo;
13: use Illuminate\Database\Eloquent\Relations\HasMany;
14: use Illuminate\Database\Eloquent\SoftDeletes;
15: use Spatie\Image\Enums\Fit;
16: use Spatie\MediaLibrary\HasMedia;
17: use Spatie\MediaLibrary\InteractsWithMedia;
18: use Spatie\MediaLibrary\MediaCollections\Models\Media;
19: 
20: class Product extends Model implements HasMedia
21: {
22:     /** @use HasFactory<ProductFactory> */
23:     use HasFactory, InteractsWithMedia, SoftDeletes;
24: 
25:     protected $fillable = [
26:         'code', 'category_id', 'brand_id', 'supplier_id', 'name_ar', 'name_en', 'slug',
27:         'description_ar', 'description_en', 'material_ar', 'material_en',
28:         'length_cm', 'width_cm', 'height_cm', 'weight_kg', 'warranty_months', 'warranty_details',
29:         'country_of_origin', 'status', 'sales_channel', 'is_featured', 'sales_count', 'published_at', 'created_by',
30:     ];
31: 
32:     protected $casts = [
33:         'status' => ProductStatus::class,
34:         'sales_channel' => SalesChannel::class,
35:         'is_featured' => 'boolean',
36:         'is_active' => 'boolean',
37:         'sales_count' => 'integer',
38:         'published_at' => 'datetime',
39:         'length_cm' => 'decimal:2', 'width_cm' => 'decimal:2', 'height_cm' => 'decimal:2',
40:         'weight_kg' => 'decimal:3',
41:     ];
42: 
43:     public function category(): BelongsTo
44:     {
45:         return $this->belongsTo(Category::class);
46:     }
47: 
48:     public function brand(): BelongsTo
49:     {
50:         return $this->belongsTo(Brand::class);
51:     }
52: 
53:     public function variants(): HasMany
54:     {
55:         // chaperone: كل variant متحمل من العلاقة دي بيبقى عارف منتجه من غير lazy load (N+1)
56:         return $this->hasMany(ProductVariant::class)->orderBy('sort_order')->chaperone();
57:     }
58: 
59:     public function registerMediaCollections(): void
60:     {
61:         $this->addMediaCollection('images')
62:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
63:         $this->addMediaCollection('video')->singleFile()
64:             ->acceptsMimeTypes(['video/mp4', 'video/webm', 'video/quicktime']);
65:     }
66: 
67:     public function registerMediaConversions(?Media $media = null): void
68:     {
69:         $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
70:             ->performOnCollections('images')->nonQueued();
71:         $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')
72:             ->performOnCollections('images')->nonQueued();
73:     }
