140:     public function test_card_price_is_personalized_when_a_customer_token_is_sent(): void
141:     {
142:         $group = CustomerGroup::create(['name' => 'VIP', 'code' => 'vip', 'discount_percentage' => 10]);
143:         $product = $this->product([], ['retail_price' => 1000]);
144: 
145:         // زائر: السعر الأساسي للقناة
146:         $guest = $this->getJson('/api/v1/store/products')->assertOk();
147:         $this->assertSame(1000.0, (float) collect($guest->json('data'))->firstWhere('id', $product->id)['price']);
148: 
149:         // عميل بمجموعة خصم 10%: خصم المجموعة فوق سعر القناة
150:         $customer = Customer::factory()->create(['customer_group_id' => $group->id]);
151:         $token = $customer->createToken('store-token')->plainTextToken;
152:         Auth::forgetGuards();
153:         $mine = $this->withToken($token)->getJson('/api/v1/store/products')->assertOk();
154:         $card = collect($mine->json('data'))->firstWhere('id', $product->id);
155:         $this->assertSame(900.0, (float) $card['price']);
156:         $this->assertSame(10, $card['discount_percentage']);
157:     }
