159:     public function test_show_by_slug_with_variant_prices_and_availability_and_draft_404(): void
160:     {
161:         $product = $this->product();
162:         $variant = $product->variants->first();
163:         $second = ProductVariant::factory()->create(['product_id' => $product->id, 'retail_price' => 2000, 'compare_at_price' => 2500]);
164:         $inactive = ProductVariant::factory()->create(['product_id' => $product->id, 'is_active' => false]);
165:         $this->stock($variant, 5);
166:         $this->stock($second, 0);
167: 
168:         $response = $this->getJson("/api/v1/store/products/{$product->slug}")->assertOk();
169:         $variants = collect($response->json('data.variants'));
170:         $this->assertCount(2, $variants); // المعطّل مستبعد
171:         $first = $variants->firstWhere('id', $variant->id);
172:         $this->assertSame(1000.0, (float) $first['price']);
173:         $this->assertArrayNotHasKey('available', $first);
174:         $this->assertTrue($first['in_stock']);
175:         $secondData = $variants->firstWhere('id', $second->id);
176:         $this->assertSame(2500.0, (float) $secondData['old_price']);
177:         $this->assertFalse($secondData['in_stock']);
178: 
179:         $draft = Product::factory()->create(['status' => ProductStatus::Draft]);
180:         $this->getJson("/api/v1/store/products/{$draft->slug}")->assertNotFound();
181:         $this->getJson('/api/v1/store/products/no-such-slug')->assertNotFound();
182:     }
