 738: // ---------------- Media ----------------
 739: function MediaTab({ media, setMedia, variants, isNew, savedOnce }) {
 740:   const [dragI, setDragI] = useState(null); const [overI, setOverI] = useState(null);
 741:   const pendingNote = isNew && !savedOnce;
 742:   const addFiles = (target) => {
 743:     const pool = [IMG.bag1, IMG.bag2, IMG.bag3, IMG.shoulder];
 744:     const n = Math.min(3, 10 - media.general.length);
 745:     const files = Array.from({ length: n }).map((_, k) => ({ id: Math.random().toString(36).slice(2), src: pool[(media.general.length + k) % pool.length], name: `laila-${media.general.length + k + 1}.jpg`, size: (1.2 + k * .7).toFixed(1) + 'MB', state: pendingNote ? 'pending' : 'uploading', p: 0, variant: target || null }));
 746:     setMedia(m => ({ ...m, general: [...m.general, ...files] }));
 747:     if (!pendingNote) files.forEach(f => simulate(f.id));
 748:   };
 749:   const simulate = id => { let v = 0; const t = setInterval(() => { v += 12 + Math.random() * 18; setMedia(m => ({ ...m, general: m.general.map(f => f.id === id ? { ...f, p: Math.min(v, 100), state: v >= 100 ? 'done' : 'uploading' } : f) })); if (v >= 100) clearInterval(t); }, 220); };
 750:   const reorder = (from, to) => setMedia(m => { const g = [...m.general]; const [x] = g.splice(from, 1); g.splice(to, 0, x); return { ...m, general: g }; });
 751:   const generalOnly = media.general.filter(f => !f.variant);
 752:   const colorGroups = [...new Set(variants.map(v => v.color_en).filter(Boolean))];
 753:   const Tile = ({ f, idx }) => {
 754:     const gi = media.general.indexOf(f);
 755:     return <div className={'img-tile ' + (dragI === gi ? 'dragging ' : '') + (overI === gi ? 'over ' : '') + (f.state === 'failed' ? 'failed' : '')} draggable
 756:       onDragStart={() => setDragI(gi)} onDragOver={e => { e.preventDefault(); setOverI(gi); }} onDragLeave={() => setOverI(null)} onDrop={() => { reorder(dragI, gi); setDragI(null); setOverI(null); }} onDragEnd={() => { setDragI(null); setOverI(null); }}>
 757:       <img src={f.src} alt="" />
 758:       <span className="ord">{idx + 1}</span>
 759:       {idx === 0 && !f.variant && <span className="cover"><Badge tone="ink" nodot>الغلاف</Badge></span>}
 760:       {f.state === 'uploading' && <div className="veil"><div style={{ width: '70%' }}><div className="prog"><i style={{ width: f.p + '%' }}></i></div><div style={{ fontSize: 11, textAlign: 'center', marginTop: 4 }}>{Math.round(f.p)}%</div></div></div>}
