 965: // ---- Confirm modal; supports server rejection state
 966: function ConfirmModal({ open, tone = 'danger', icon, title, text, confirmLabel = 'تأكيد', onConfirm, onClose, rejectWith }) {
 967:   const [state, setState] = useState('idle'); const [err, setErr] = useState(null);
 968:   useEffect(() => { if (open) { setState('idle'); setErr(null); } }, [open]);
 969:   if (!open) return null;
 970:   const go = async () => {
 971:     setState('loading'); await sleep(700);
 972:     if (rejectWith) { setErr(rejectWith); setState('rejected'); return; }
 973:     onConfirm && onConfirm(); onClose();
 974:   };
 975:   return (
 976:     <div className="scrim" onMouseDown={e => e.target === e.currentTarget && onClose()}>
 977:       <div className="modal" role="dialog" aria-modal="true">
 978:         <div className="modal-b">
 979:           <div className={'mi ' + tone}><i className={icon || 'fa-regular fa-trash-can'}></i></div>
 980:           <div style={{ flex: 1 }}>
 981:             <h4>{title}</h4><p>{text}</p>
 982:             {state === 'rejected' && <div style={{ marginTop: 14 }}><Alert tone="danger" title="رفض الخادم العملية">{err}</Alert></div>}
 983:           </div>
 984:         </div>
 985:         <div className="modal-f">
 986:           <Btn kind="ghost" onClick={onClose}>{state === 'rejected' ? 'إغلاق' : 'إلغاء'}</Btn>
 987:           {state !== 'rejected' && <Btn kind={tone === 'danger' ? 'danger' : ''} loading={state === 'loading'} onClick={go}>{confirmLabel}</Btn>}
 988:         </div>
 989:       </div>
 990:     </div>
 991:   );
 992: }
