1000:       <div className="drawer" role="dialog" aria-modal="true">
1001:         <div className="drawer-h">
1002:           <div style={{ flex: 1 }}>{crumbs && <div className="crumbs">{crumbs}</div>}<h3>{title}</h3></div>
1003:           <button className="icon-btn" onClick={tryClose} aria-label="إغلاق"><i className="fa-solid fa-xmark"></i></button>
1004:         </div>
1005:         <div className="drawer-b">{children}</div>
1006:         {footer && <div className="drawer-f">{footer}</div>}
1007:       </div>
1008:       <ConfirmModal open={ask} tone="warn" icon="fa-solid fa-pen-to-square" title="تغييرات غير محفوظة"
1009:         text="لديك تعديلات لم تُحفظ بعد. إذا أغلقت الآن ستفقد هذه التعديلات." confirmLabel="تجاهل التغييرات"
1010:         onConfirm={onClose} onClose={() => setAsk(false)} />
1011:     </div>
1012:   );
1013: }
