1038: // ---- DataTable with server pagination, page size, loading/empty/error
1039: function DataTable({ columns, rows, query, setQuery, searchPh = 'بحث…', filters, activeFilters, onClearFilters, rowKey = 'id', empty, onRowClick, forceState }) {
1040:   const page = +query.page || 1, per = +query.per_page || 10;
1041:   const [res, setRes] = useState(null); const [state, setState] = useState('loading'); const [nonce, setNonce] = useState(0);
1042:   const [qLocal, setQLocal] = useState(query.q || '');
1043:   useEffect(() => { const t = setTimeout(() => { if ((query.q || '') !== qLocal) setQuery({ q: qLocal, page: 1 }); }, 350); return () => clearTimeout(t); }, [qLocal]);
1044:   useEffect(() => {
1045:     let live = true; setState('loading');
1046:     apiClient.list(rows, { page, per_page: per, fail: forceState === 'error' }).then(r => { if (live) { setRes(r); setState('ok'); } }).catch(() => live && setState('error'));
1047:     return () => { live = false; };
1048:   }, [rows, page, per, nonce, forceState]);
1049:   const st = forceState && forceState !== 'error' ? forceState : state;
1050:   const meta = res && res.meta;
1051:   return (
1052:     <div className="dt">
1053:       <div className="dt-toolbar">
1054:         <div className="dt-search"><i className="fa-solid fa-magnifying-glass"></i><input className="inp" value={qLocal} placeholder={searchPh} onChange={e => setQLocal(e.target.value)} /></div>
1055:         {filters && <div className="dt-filters">{filters}</div>}
1056:       </div>
1057:       {activeFilters && activeFilters.length > 0 && (
1058:         <div className="active-filters"><span className="lbl">الفلاتر النشطة:</span>
1059:           {activeFilters.map(f => <span key={f.k} className="tag">{f.label}<button onClick={f.clear} aria-label="إزالة"><i className="fa-solid fa-xmark"></i></button></span>)}
1060:           <button className="btn text sm" onClick={onClearFilters}>مسح الكل</button>
1061:         </div>
1062:       )}
1063:       {st === 'error' ? <ErrorState onRetry={() => setNonce(n => n + 1)} /> :
1064:         st === 'empty' || (st === 'ok' && meta.total === 0) ? (empty || <EmptyState title="لا توجد نتائج" text="جرّب تعديل البحث أو الفلاتر." />) : (
1065:           <div style={{ overflowX: 'auto' }}>
1066:             <table className="tbl">
1067:               <thead><tr>{columns.map(c => <th key={c.k} style={c.w ? { width: c.w } : null} className={c.cls}>{c.label}</th>)}</tr></thead>
1068:               <tbody>
1069:                 {st === 'loading' ? Array.from({ length: Math.min(per, 6) }).map((_, i) => (
1070:                   <tr key={i}>{columns.map((c, j) => <td key={c.k}>{j === 0 ? <div className="cell-main"><div className="thumb sk" style={{ height: 44 }}></div><div style={{ flex: 1 }}><div className="sk" style={{ width: 140, marginBottom: 6 }}></div><div className="sk" style={{ width: 80, height: 9 }}></div></div></div> : <div className="sk" style={{ width: 40 + ((i * 7 + j * 13) % 50) }}></div>}</td>)}</tr>
1071:                 )) : res.data.map(r => (
1072:                   <tr key={r[rowKey]} onClick={onRowClick ? () => onRowClick(r) : undefined} style={onRowClick ? { cursor: 'pointer' } : null}>
1073:                     {columns.map(c => <td key={c.k} className={c.cls}>{c.render ? c.render(r) : r[c.k]}</td>)}
1074:                   </tr>
1075:                 ))}
1076:               </tbody>
1077:             </table>
1078:           </div>
1079:         )}
1080:       {st !== 'error' && meta && meta.total > 0 && (
1081:         <div className="dt-foot">
1082:           <span>عرض <b className="num">{meta.from}–{meta.to}</b> من <b className="num">{meta.total}</b></span>
1083:           <span className="muted">|</span>
1084:           <label style={{ display: 'flex', gap: 8, alignItems: 'center' }}>حجم الصفحة
1085:             <select className="mini-sel" value={per} onChange={e => setQuery({ per_page: e.target.value, page: 1 })}>{[5, 10, 25, 50].map(n => <option key={n}>{n}</option>)}</select>
1086:           </label>
1087:           <div className="pager">
1088:             <button disabled={!res.links.prev} onClick={() => setQuery({ page: page - 1 })} aria-label="السابق"><i className="fa-solid fa-chevron-right"></i></button>
1089:             {Array.from({ length: meta.last_page }).map((_, i) => <button key={i} className={i + 1 === page ? 'on' : ''} onClick={() => setQuery({ page: i + 1 })}>{i + 1}</button>)}
1090:             <button disabled={!res.links.next} onClick={() => setQuery({ page: page + 1 })} aria-label="التالي"><i className="fa-solid fa-chevron-left"></i></button>
1091:           </div>
1092:         </div>
1093:       )}
1094:     </div>
1095:   );
1096: }
