1157: // Reusable Tweaks shell + form-control helpers.
1158: //
1159: // Owns the host protocol (listens for __activate_edit_mode / __deactivate_edit_mode,
1160: // posts __edit_mode_available / __edit_mode_set_keys / __edit_mode_dismissed) so
1161: // individual prototypes don't re-roll it. Ships a consistent set of controls so you
1162: // don't hand-draw <input type="range">, segmented radios, steppers, etc.
1163: //
1164: // Usage (in an HTML file that loads React + Babel):
1165: //
1166: //   const TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
1167: //     "primaryColor": "#7A5AE0",
1168: //     "palette": ["#7A5AE0", "#29261b", "#f6f4ef"],
1169: //     "fontSize": 16,
1170: //     "density": "regular",
1171: //     "dark": false
1172: //   }/*EDITMODE-END*/;
1173: //
1174: //   function App() {
1175: //     const [t, setTweak] = useTweaks(TWEAK_DEFAULTS);
1176: //     return (
1177: //       <div style={{ fontSize: t.fontSize, color: t.primaryColor }}>
1178: //         Hello
1179: //         <TweaksPanel>
1180: //           <TweakSection label="Typography" />
1181: //           <TweakSlider label="Font size" value={t.fontSize} min={10} max={32} unit="px"
1182: //                        onChange={(v) => setTweak('fontSize', v)} />
1183: //           <TweakRadio  label="Density" value={t.density}
1184: //                        options={['compact', 'regular', 'comfy']}
1185: //                        onChange={(v) => setTweak('density', v)} />
1186: //           <TweakSection label="Theme" />
1187: //           <TweakColor  label="Primary" value={t.primaryColor}
1188: //                        options={['#0F766E', '#2A6FDB', '#1F8A5B', '#7A5AE0']}
1189: //                        onChange={(v) => setTweak('primaryColor', v)} />
1190: //           <TweakColor  label="Palette" value={t.palette}
1191: //                        options={[['#7A5AE0', '#29261b', '#f6f4ef'],
1192: //                                  ['#475569', '#0f172a', '#f1f5f9']]}
1193: //                        onChange={(v) => setTweak('palette', v)} />
1194: //           <TweakToggle label="Dark mode" value={t.dark}
1195: //                        onChange={(v) => setTweak('dark', v)} />
1196: //         </TweaksPanel>
1197: //       </div>
1198: //     );
1199: //   }
