1753: function __TwkSpark({ size = 12 }) {
1754:   return (
1755:     <svg width={size} height={size} viewBox="0 0 17 18" fill="currentColor"
1756:          style={{ display: 'inline-block', verticalAlign: '-1px' }}>
1757:       <path d={__TWK_SPARK_STAR} />
1758:       <path d={__TWK_SPARK_DOT} />
