2645: function ProductsPage() {
2646:   const { route, setQuery, go, forceState } = useApp();
2647:   const q = route.query;
2648:   const rows = useMemo(() => {
2649:     let r = PRODUCTS.filter(p => {
2650:       if (q.q && !(p.ar + p.en + p.code + 'SKU').toLowerCase().includes(q.q.toLowerCase())) return false;
2651:       if (q.cat) { const cid = +q.cat; if (q.sub === '1') { if (!(p.cat === cid || isDescendant(CATS, cid, p.cat))) return false; } else if (p.cat !== cid) return false; }
2652:       if (q.brand && p.brand !== +q.brand) return false;
2653:       if (q.status && p.status !== q.status) return false;
2654:       if (q.channel && p.channel !== q.channel) return false;
2655:       if (q.featured === '1' && !p.featured) return false;
2656:       return true;
2657:     });
2658:     if (q.sort === 'oldest') r = [...r].sort((a, b) => b.created - a.created);
2659:     else if (q.sort === 'name') r = [...r].sort((a, b) => a.ar.localeCompare(b.ar, 'ar'));
2660:     else r = [...r].sort((a, b) => a.created - b.created);
2661:     return r;
2662:   }, [q.q, q.cat, q.sub, q.brand, q.status, q.channel, q.featured, q.sort]);
2663:   const af = [
2664:     q.cat && { k: 'cat', label: 'القسم: ' + catById(+q.cat).ar + (q.sub === '1' ? ' + الفرعية' : ''), clear: () => setQuery({ cat: '', sub: '', page: 1 }) },
2665:     q.brand && { k: 'brand', label: 'البراند: ' + brandById(+q.brand).en, clear: () => setQuery({ brand: '', page: 1 }) },
2666:     q.status && { k: 'st', label: P_STATUS[q.status][0], clear: () => setQuery({ status: '', page: 1 }) },
2667:     q.channel && { k: 'ch', label: CHANNELS[q.channel], clear: () => setQuery({ channel: '', page: 1 }) },
2668:     q.featured === '1' && { k: 'f', label: 'مميز فقط', clear: () => setQuery({ featured: '', page: 1 }) },
2669:   ].filter(Boolean);
2670:   return <>
2671:     <PageHeader crumbs={[['الرئيسية', '/products'], ['الكتالوج'], ['المنتجات']]} light="كتالوج" bold="المنتجات" sub="الشنط والمحافظ بكل ألوانها ومقاساتها وسعاتها. البحث يشمل الاسم والكود وSKU والباركود."
2672:       decor={IMG.bag1} actions={<Btn icon="fa-solid fa-plus" onClick={() => go('/products/new')}>منتج جديد</Btn>} />
2673:     <div className="content" data-screen-label="Products list">
2674:       <DataTable rows={rows} query={q} setQuery={setQuery} searchPh="الاسم، الكود، SKU أو الباركود" forceState={forceState}
2675:         onRowClick={r => go('/products/' + r.id)}
2676:         filters={<>
2677:           <div style={{ width: 200 }}><SearchSelect value={q.cat ? +q.cat : null} onChange={v => setQuery({ cat: v || '', page: 1 })} placeholder="القسم" clearable
2678:             options={CATS.map(c => ({ value: c.id, label: catPath(c.id).map(x => x.ar).join(' / ') }))} searchPh="ابحث عن قسم…" /></div>
2679:           {q.cat && <label className="fchip" style={{ gap: 8 }}><Check checked={q.sub === '1'} onChange={v => setQuery({ sub: v ? '1' : '', page: 1 })} />تضمين الفرعية</label>}
2680:           <FilterSelect label="البراند" value={q.brand} onChange={v => setQuery({ brand: v, page: 1 })} options={BRANDS.map(b => [b.id, b.en])} />
2681:           <FilterSelect label="الحالة" value={q.status} onChange={v => setQuery({ status: v, page: 1 })} options={Object.entries(P_STATUS).map(([k, v]) => [k, v[0]])} />
2682:           <FilterSelect label="قناة البيع" value={q.channel} onChange={v => setQuery({ channel: v, page: 1 })} options={Object.entries(CHANNELS)} />
2683:           <button className={'fchip ' + (q.featured === '1' ? 'on' : '')} onClick={() => setQuery({ featured: q.featured === '1' ? '' : '1', page: 1 })}><i className="fa-solid fa-star" style={{ fontSize: 11 }}></i>مميز</button>
2684:           <span style={{ width: 1, height: 22, background: 'var(--line-2)', margin: '0 4px' }}></span>
2685:           <label className="fchip"><span className="muted">ترتيب:</span><select value={q.sort || 'newest'} onChange={e => setQuery({ sort: e.target.value === 'newest' ? '' : e.target.value })}><option value="newest">الأحدث</option><option value="oldest">الأقدم</option><option value="name">الاسم</option></select><i className="fa-solid fa-chevron-down car"></i></label>
2686:         </>}
2687:         activeFilters={af} onClearFilters={() => setQuery({ cat: '', sub: '', brand: '', status: '', channel: '', featured: '', page: 1 })}
2688:         empty={af.length || q.q ? <EmptyState icon="fa-solid fa-magnifying-glass" title="لا توجد منتجات مطابقة" text="جرّب كلمة بحث أخرى أو أزل بعض الفلاتر." action={<Btn kind="ghost" onClick={() => setQuery({ q: '', cat: '', sub: '', brand: '', status: '', channel: '', featured: '', page: 1 })}>مسح البحث والفلاتر</Btn>} />
2689:           : <EmptyState icon="fa-solid fa-bag-shopping" title="الكتالوج فارغ" text="أضف أول شنطة أو محفظة. ستُحفظ كمسودة حتى تكتمل الصور والأسعار." action={<Btn icon="fa-solid fa-plus" onClick={() => go('/products/new')}>منتج جديد</Btn>} />}
2690:         columns={[
2691:           { k: 'p', label: 'المنتج', render: r => <div className="cell-main"><div className="thumb">{r.img ? <img src={r.img} alt="" /> : <i className="fa-regular fa-image muted"></i>}</div><div style={{ minWidth: 0 }}><b>{r.ar}</b><small className="mono ltr">{r.code}</small></div></div> },
2692:           { k: 'c', label: 'القسم / البراند', render: r => <div style={{ lineHeight: 1.4 }}><div>{catById(r.cat).ar}</div><small className="muted">{brandById(r.brand).en}</small></div> },
2693:           { k: 's', label: 'الحالة', render: r => <Badge tone={P_STATUS[r.status][1]}>{P_STATUS[r.status][0]}</Badge> },
2694:           { k: 'ch', label: 'قناة البيع', render: r => <span style={{ fontSize: 12.5 }}>{CHANNELS[r.channel]}</span> },
2695:           { k: 'v', label: 'المتغيرات', cls: 'num', render: r => r.variants || <span className="muted">0</span> },
2696:           { k: 'pr', label: 'سعر التجزئة', cls: 'num', render: r => r.price && r.channel !== 'wholesale' ? <span className="ltr" style={{ display: 'inline-block' }}>{r.price[0] === r.price[1] ? fmtMoney(r.price[0]) : fmtMoney(r.price[0]) + ' – ' + fmtMoney(r.price[1])} <small className="muted">EGP</small></span> : <span className="muted">—</span> },
2697:           { k: 'f', label: '', render: r => r.featured ? <i className="fa-solid fa-star star" title="مميز"></i> : null },
2698:           { k: 'a', label: '', cls: 'act', render: r => <span onClick={e => e.stopPropagation()}><button className="icon-btn" onClick={() => go('/products/' + r.id)} title="تعديل"><i className="fa-regular fa-pen-to-square"></i></button><button className="icon-btn" title="المزيد"><i className="fa-solid fa-ellipsis"></i></button></span> },
2699:         ]} />
2700:     </div>
2701:   </>;
2702: }
