2707: function BranchForm({ open, onClose, initial }) {
2708:   const { toast } = useApp();
2709:   const [f, setF] = useState(initial || { name: '', code: '', type: '', phone: '', email: '', city: '', address: '', active: true });
2710:   const [err, setErr] = useState({}); const [saving, setSaving] = useState(false); const [dirty, setDirty] = useState(false);
2711:   useEffect(() => { setF(initial || { name: '', code: '', type: '', phone: '', email: '', city: '', address: '', active: true }); setErr({}); setDirty(false); }, [open]);
2712:   const set = (k, v) => { setF(x => ({ ...x, [k]: v })); setDirty(true); setErr(e => ({ ...e, [k]: null })); };
2713:   const save = async () => {
2714:     const e = {};
2715:     if (!f.name) e.name = 'اسم الفرع مطلوب.';
2716:     if (!f.code) e.code = 'الكود مطلوب.';
2717:     else if (BRANCHES.some(b => b.code === f.code && (!initial || b.id !== initial.id))) e.code = 'هذا الكود مستخدم بالفعل لفرع آخر.';
2718:     if (!f.type) e.type = 'اختر نوع الموقع.';
2719:     if (f.email && !/^\S+@\S+\.\S+$/.test(f.email)) e.email = 'صيغة البريد غير صحيحة.';
2720:     setErr(e); if (Object.keys(e).length) return;
2721:     setSaving(true); await sleep(700); setSaving(false); toast(initial ? 'تم تحديث الفرع' : 'تمت إضافة الفرع'); onClose();
2722:   };
2723:   return (
2724:     <Drawer open={open} onClose={onClose} dirty={dirty} title={initial ? 'تعديل ' + initial.name : 'إضافة فرع أو مخزن'} crumbs={<><span>الفروع</span><span className="sep">/</span><span className="cur">{initial ? 'تعديل' : 'جديد'}</span></>}
2725:       footer={<><Btn loading={saving} onClick={save}>{initial ? 'حفظ التغييرات' : 'إضافة'}</Btn><Btn kind="ghost" onClick={onClose}>إلغاء</Btn><span className="sp" style={{ flex: 1 }}></span>{dirty && <span className="dirty">غير محفوظ</span>}</>}>
2726:       <div className="grid g2">
2727:         <Field label="النوع" req error={err.type} className="spanall">
2728:           <div className="radio-cards g2" style={{ display: 'grid' }}>
2729:             {[['branch', 'فرع', 'نقطة بيع للعملاء ومخزون عرض'], ['warehouse', 'مخزن', 'تخزين وتوزيع بدون بيع مباشر']].map(o => (
2730:               <div key={o[0]} className={'rcard ' + (f.type === o[0] ? 'on' : '')} onClick={() => set('type', o[0])} style={err.type ? { borderColor: 'var(--danger)' } : null}>
2731:                 <span className="dot"></span><div><b>{o[1]}</b><span>{o[2]}</span></div></div>
2732:             ))}
2733:           </div>
2734:         </Field>
2735:         <Field label="الاسم" req error={err.name}><Input value={f.name} error={err.name} onChange={e => set('name', e.target.value)} placeholder="مثال: فرع المعادي" /></Field>
2736:         <Field label="الكود" req error={err.code} help="حروف إنجليزية وأرقام، يظهر في المستندات."><Input ltr className="mono" value={f.code} error={err.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="MAD-04" /></Field>
2737:         <Field label="الهاتف" opt><Input ltr value={f.phone} onChange={e => set('phone', e.target.value)} placeholder="01xxxxxxxxx" /></Field>
2738:         <Field label="البريد الإلكتروني" opt error={err.email}><Input ltr value={f.email} error={err.email} onChange={e => set('email', e.target.value)} placeholder="branch@alfarid.eg" /></Field>
2739:         <Field label="المدينة" opt><Input value={f.city} onChange={e => set('city', e.target.value)} /></Field>
2740:         <Field label="العنوان" opt><Input value={f.address} onChange={e => set('address', e.target.value)} /></Field>
2741:         <div className="spanall"><Toggle checked={f.active} onChange={v => set('active', v)} label={f.active ? 'نشط — يظهر في عمليات البيع والمخزون' : 'غير نشط'} /></div>
2742:       </div>
2743:     </Drawer>
2744:   );
2745: }
