2835: function UsersPage() {
2836:   const { route, setQuery, toast, forceState } = useApp();
2837:   const q = route.query; const [form, setForm] = useState(null);
2838:   const rows = useMemo(() => USERS.filter(u => (!q.q || (u.name + u.email).toLowerCase().includes(q.q.toLowerCase())) && (!q.role || u.roles.includes(+q.role)) && (!q.branch || String(u.branch) === q.branch)), [q.q, q.role, q.branch]);
2839:   return <>
2840:     <PageHeader crumbs={[['الرئيسية', '/products'], ['الإدارة'], ['المستخدمون']]} bold="المستخدمون" sub="ربط كل مستخدم بفرع وأدوار. الوصول لكل الفروع امتياز صريح منفصل."
2841:       actions={<Btn icon="fa-solid fa-user-plus" onClick={() => setForm({})}>إضافة مستخدم</Btn>} />
2842:     <div className="content" data-screen-label="Users">
2843:       <DataTable rows={rows} query={q} setQuery={setQuery} searchPh="ابحث بالاسم أو البريد" forceState={forceState}
2844:         filters={<><FilterSelect label="الدور" value={q.role} onChange={v => setQuery({ role: v, page: 1 })} options={ROLES.map(r => [r.id, r.name])} />
2845:           <FilterSelect label="الفرع" value={q.branch} onChange={v => setQuery({ branch: v, page: 1 })} options={BRANCHES.map(b => [b.id, b.name])} /></>}
2846:         columns={[
2847:           { k: 'n', label: 'المستخدم', render: r => <div className="cell-main"><div className="avatar">{r.name.split(' ').map(s => s[0]).join('')}</div><div><b>{r.name}</b><small className="ltr" style={{ display: 'block', textAlign: 'right' }}>{r.email}</small></div></div> },
2848:           { k: 'b', label: 'الفرع', render: r => r.all ? <Badge tone="accent" nodot>كل الفروع</Badge> : r.branch ? branchById(r.branch).name : <span className="muted">بدون فرع</span> },
2849:           { k: 'r', label: 'الأدوار', render: r => <div className="tags">{r.roles.map(id => <span key={id} className="tag">{ROLES.find(x => x.id === id).name}</span>)}</div> },
2850:           { k: 's', label: 'الحالة', render: r => <StatusBadge active={r.active} /> },
2851:           { k: 'a', label: '', cls: 'act', render: r => <button className="icon-btn" onClick={() => setForm(r)}><i className="fa-regular fa-pen-to-square"></i></button> },
2852:         ]} />
2853:     </div>
2854:     <UserForm open={!!form} initial={form && form.id ? form : null} onClose={() => setForm(null)} />
