2857: function UserForm({ open, initial, onClose }) {
2858:   const { toast } = useApp();
2859:   const blank = { name: '', email: '', password: '', phone: '', branch: null, roles: [], active: true, all: false };
2860:   const [f, setF] = useState(blank); const [err, setErr] = useState({}); const [saving, setSaving] = useState(false);
2861:   useEffect(() => { setF(initial ? { ...blank, ...initial } : blank); setErr({}); }, [open]);
2862:   const set = (k, v) => { setF(x => ({ ...x, [k]: v })); setErr(e => ({ ...e, [k]: null })); };
2863:   const save = async () => {
2864:     const e = {};
2865:     if (!f.name) e.name = 'الاسم مطلوب.';
2866:     if (!f.email) e.email = 'البريد مطلوب.'; else if (USERS.some(u => u.email === f.email && (!initial || u.id !== initial.id))) e.email = 'هذا البريد مسجّل لمستخدم آخر.';
2867:     if (!initial && !f.password) e.password = 'كلمة المرور مطلوبة عند الإنشاء.'; else if (f.password && f.password.length < 8) e.password = 'كلمة المرور يجب ألا تقل عن ٨ أحرف.';
2868:     setErr(e); if (Object.keys(e).length) return;
2869:     setSaving(true); await sleep(700); setSaving(false); toast('تم حفظ المستخدم'); onClose();
2870:   };
2871:   return (
2872:     <Drawer open={open} onClose={onClose} title={initial ? initial.name : 'مستخدم جديد'} crumbs={<><span>المستخدمون</span><span className="sep">/</span><span className="cur">{initial ? 'تعديل' : 'إضافة'}</span></>}
2873:       footer={<><Btn loading={saving} onClick={save}>حفظ</Btn><Btn kind="ghost" onClick={onClose}>إلغاء</Btn></>}>
2874:       <div className="sec-title">بيانات الحساب</div>
2875:       <div className="grid g2" style={{ marginBottom: 26 }}>
2876:         <Field label="الاسم" req error={err.name} className="spanall"><Input value={f.name} error={err.name} onChange={e => set('name', e.target.value)} /></Field>
2877:         <Field label="البريد الإلكتروني" req error={err.email}><Input ltr value={f.email} error={err.email} onChange={e => set('email', e.target.value)} placeholder="user@alfarid.eg" /></Field>
2878:         <Field label="الهاتف" opt><Input ltr value={f.phone} onChange={e => set('phone', e.target.value)} /></Field>
2879:         <Field label={initial ? 'كلمة مرور جديدة' : 'كلمة المرور'} req={!initial} opt={!!initial} error={err.password} help={initial ? 'اتركها فارغة للإبقاء على كلمة المرور الحالية.' : '٨ أحرف على الأقل.'} className="spanall">
2880:           <PasswordInput value={f.password} error={err.password} onChange={e => set('password', e.target.value)} /></Field>
2881:       </div>
2882:       <div className="sec-title">الفرع والأدوار</div>
2883:       <div className="grid" style={{ marginBottom: 20 }}>
2884:         <Field label="الفرع" opt help={f.branch == null && !f.all ? '«بدون فرع» يعني أن المستخدم غير مرتبط بأي فرع — وليس الوصول لكل الفروع.' : null}>
2885:           <SearchSelect value={f.branch} onChange={v => set('branch', v)} placeholder="بدون فرع" clearable
2886:             options={[{ value: null, label: 'بدون فرع', sub: 'غير مرتبط بفرع' }, ...BRANCHES.map(b => ({ value: b.id, label: b.name, sub: b.code, disabled: !b.active, why: !b.active ? 'غير نشط' : null }))]} searchPh="ابحث عن فرع…" />
2887:         </Field>
2888:         <div className="panel" style={{ padding: 14, background: 'var(--soft-2)' }}>
2889:           <Toggle checked={f.all} onChange={v => set('all', v)} label={<span><b style={{ fontWeight: 600 }}>الوصول لكل الفروع</b> <span className="mono muted" style={{ fontSize: 10.5 }}>branches.access_all</span></span>} />
2890:           <div className="field-help" style={{ marginTop: 6, marginInlineStart: 46 }}>امتياز صريح يمنح الاطلاع على بيانات ومخزون جميع الفروع بغض النظر عن الفرع المرتبط.</div>
2891:         </div>
2892:         <Field label="الأدوار" opt><SearchSelect multi value={f.roles} onChange={v => set('roles', v)} placeholder="اختر دورًا أو أكثر" options={ROLES.map(r => ({ value: r.id, label: r.name, sub: r.users + ' مستخدم' }))} /></Field>
2893:         <Toggle checked={f.active} onChange={v => set('active', v)} label="الحساب نشط" />
2894:       </div>
2895:     </Drawer>
2896:   );
2897: }
