2899: // ---------------- Roles ----------------
2900: function RolesPage() {
2901:   const { toast } = useApp();
2902:   const [sel, setSel] = useState(2); const [q, setQ] = useState('');
2903:   const [perms, setPerms] = useState(new Set(['products.view', 'products.create', 'products.update', 'products.publish', 'categories.view', 'categories.manage', 'brands.view', 'brands.manage']));
2904:   const [open, setOpen] = useState({ products: true, categories: true });
2905:   const role = ROLES.find(r => r.id === sel);
2906:   const toggle = k => setPerms(p => { const n = new Set(p); n.has(k) ? n.delete(k) : n.add(k); return n; });
2907:   const toggleGroup = (g, on) => setPerms(p => { const n = new Set(p); g.perms.forEach(([k]) => on ? n.add(k) : n.delete(k)); return n; });
2908:   const ql = q.trim().toLowerCase();
2909:   return <>
2910:     <PageHeader crumbs={[['الرئيسية', '/products'], ['الإدارة'], ['الأدوار والصلاحيات']]} light="الأدوار" bold="والصلاحيات" sub="الصلاحيات معروضة بأسماء مفهومة؛ المفتاح التقني يُرسل كما هو للخادم."
2911:       actions={<Btn icon="fa-solid fa-plus">دور جديد</Btn>} />
2912:     <div className="content" data-screen-label="Roles">
2913:       <div className="split" style={{ gridTemplateColumns: '260px 1fr' }}>
2914:         <div className="panel" style={{ padding: 8 }}>
2915:           {ROLES.map(r => <div key={r.id} className={'role-item ' + (r.id === sel ? 'on' : '')} onClick={() => setSel(r.id)}>
2916:             <div className="avatar" style={{ width: 30, height: 30, fontSize: 11 }}><i className="fa-solid fa-shield-halved"></i></div>
2917:             <div style={{ flex: 1 }}><b>{r.name}</b><small>{r.users} مستخدم{r.system ? ' · دور النظام' : ''}</small></div></div>)}
2918:         </div>
2919:         <div className="panel">
2920:           <div className="panel-h">
2921:             <div style={{ flex: 1 }}><Field label="اسم الدور" req><Input defaultValue={role.name} key={role.id} disabled={role.system} /></Field></div>
2922:           </div>
2923:           <div className="panel-b">
2924:             {role.system ? <Alert tone="info">دور «مدير النظام» يملك كل الصلاحيات ولا يمكن تعديله.</Alert> : <>
2925:               <div style={{ display: 'flex', gap: 12, alignItems: 'center', marginBottom: 16 }}>
2926:                 <div className="dt-search" style={{ width: 320 }}><i className="fa-solid fa-magnifying-glass"></i><input className="inp" placeholder="ابحث في الصلاحيات (عربي أو المفتاح)" value={q} onChange={e => setQ(e.target.value)} /></div>
2927:                 <span className="muted" style={{ fontSize: 12 }}>محدد {perms.size} من {PERM_GROUPS.reduce((a, g) => a + g.perms.length, 0)}</span>
2928:               </div>
2929:               {PERM_GROUPS.map(g => {
2930:                 const list = g.perms.filter(([k, l]) => !ql || k.includes(ql) || l.includes(q));
2931:                 if (!list.length) return null;
2932:                 const n = g.perms.filter(([k]) => perms.has(k)).length;
2933:                 const isOpen = open[g.key] || !!ql;
2934:                 return <div className="perm-grp" key={g.key}>
2935:                   <div className="perm-grp-h" onClick={() => setOpen(o => ({ ...o, [g.key]: !o[g.key] }))}>
2936:                     <Check checked={n === g.perms.length} indeterminate={n > 0 && n < g.perms.length} onChange={v => toggleGroup(g, v)} />
2937:                     <b>{g.label}</b><span className="cnt">{n}/{g.perms.length}</span>
2938:                     <i className={'fa-solid fa-chevron-' + (isOpen ? 'up' : 'down')} style={{ fontSize: 10, color: 'var(--ink-4)' }}></i>
2939:                   </div>
2940:                   {isOpen && <div className="perm-list">{list.map(([k, l]) => <div className="perm" key={k}><Check checked={perms.has(k)} onChange={() => toggle(k)} label={l} /><span className="k">{k}</span></div>)}</div>}
2941:                 </div>;
2942:               })}
2943:             </>}
2944:           </div>
2945:           {!role.system && <div className="drawer-f" style={{ borderTop: '1px solid var(--line)' }}><Btn onClick={() => toast('تم حفظ صلاحيات الدور')}>حفظ الدور</Btn><Btn kind="ghost">إلغاء</Btn><span style={{ flex: 1 }}></span><Btn kind="danger ghost" icon="fa-regular fa-trash-can">حذف الدور</Btn></div>}
2946:         </div>
2947:       </div>
2948:     </div>
2949:   </>;
2950: }
