3220: // ---- simulated API client ----
3221: const sleep = ms => new Promise(r => setTimeout(r, ms));
3222: const apiClient = {
3223:   portal: 'admin', // separate session storage per portal: alfarid.session.admin / .supplier / .pos
3224:   async list(rows, { page = 1, per_page = 10, fail = false } = {}) {
3225:     await sleep(550);
3226:     if (fail) { const e = new Error('Network'); e.status = 500; throw e; }
3227:     const total = rows.length, last = Math.max(1, Math.ceil(total / per_page));
3228:     const data = rows.slice((page - 1) * per_page, page * per_page);
3229:     return {
3230:       data,
3231:       meta: { current_page: page, per_page, total, last_page: last, from: total ? (page - 1) * per_page + 1 : 0, to: Math.min(page * per_page, total) },
3232:       links: { first: '?page=1', last: '?page=' + last, prev: page > 1 ? '?page=' + (page - 1) : null, next: page < last ? '?page=' + (page + 1) : null },
3233:     };
3234:   },
3235:   // Normalizes Laravel-style 422 into { status, message, fields: {'variants.2.retail_price': [..]}, summary: [...] }
3236:   normalize(raw) {
3237:     const fields = {}; const summary = [];
3238:     Object.entries(raw.errors || {}).forEach(([k, v]) => { if (k === 'status') summary.push(...v); else fields[k] = v; });
3239:     return { status: raw.status, message: raw.message, fields, summary };
3240:   },
3241: };
