3243: // URL state: #/route?page=2&q=...
3244: const parseHash = () => {
3245:   const h = location.hash.replace(/^#/, '') || '/login';
3246:   const [path, qs] = h.split('?');
3247:   return { path, query: Object.fromEntries(new URLSearchParams(qs || '')) };
3248: };
3249: const buildHash = (path, query = {}) => {
3250:   const q = new URLSearchParams(Object.entries(query).filter(([, v]) => v !== '' && v != null && v !== false));
3251:   const s = q.toString();
3252:   return '#' + path + (s ? '?' + s : '');
3253: };
