18: class ProductVariant extends Model implements HasMedia
19: {
20:     /** @use HasFactory<ProductVariantFactory> */
21:     use HasFactory, InteractsWithMedia, SoftDeletes;
22: 
23:     protected $fillable = [
24:         'product_id', 'sku', 'barcode', 'color_name_ar', 'color_name_en', 'color_hex', 'size', 'capacity',
25:         'cost_price', 'last_cost_price', 'retail_price', 'wholesale_price', 'compare_at_price', 'reorder_level', 'weight_kg', 'sort_order', 'is_active',
26:     ];
27: 
28:     protected $casts = [
29:         'cost_price' => 'decimal:4', 'last_cost_price' => 'decimal:4', 'retail_price' => 'decimal:2', 'wholesale_price' => 'decimal:2', 'compare_at_price' => 'decimal:2',
30:         'weight_kg' => 'decimal:3', 'is_active' => 'boolean',
31:     ];
32: 
33:     public function stockLevels(): HasMany
34:     {
35:         return $this->hasMany(StockLevel::class);
36:     }
37: 
38:     public function product(): BelongsTo
39:     {
40:         return $this->belongsTo(Product::class);
41:     }
42: 
43:     /** Compatibility with the catalog's existing editable retail price. */
44:     public function getBasePriceAttribute(): string
45:     {
46:         return (string) ($this->retail_price ?? 0);
47:     }
48: 
49:     // صور خاصة باللون ده
50:     public function registerMediaCollections(): void
51:     {
52:         $this->addMediaCollection('images')->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
53:     }
54: 
55:     public function registerMediaConversions(?Media $media = null): void
56:     {
57:         $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')->nonQueued();
58:         $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')->nonQueued();
59:     }
60: }  1: <?php
