 72:     // ------------------------------------------------------------------ أساس
 73: 
 74:     /** استعلام المنتجات المنشورة بعلاقات البطاقة والمتاح المجمّع. */
 75:     public function publishedQuery(): Builder
 76:     {
 77:         $query = Product::query()
 78:             ->where('status', ProductStatus::Published)
 79:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both])
 80:             ->whereHas('category', fn ($q) => $q->where('is_active', true)
 81:                 ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
 82:                     ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
 83:             ->where(fn ($q) => $q->whereNull('brand_id')->orWhereHas('brand', fn ($brand) => $brand->where('is_active', true)))
 84:             ->with([
 85:                 'brand', 'category', 'media',
 86:                 'variants' => fn ($q) => $this->pricing->withStorePrice($q->getQuery(), $this->customer())
 87:                     ->where('is_active', true)->orderBy('sort_order')->orderBy('id'),
 88:             ]);
 89: 
 90:         return $this->withStoreAvailability($query);
 91:     }
 92: 
 93:     // ------------------------------------------------------------------ فلاتر
 94: 
 95:     /**
 96:      * تطبيق فلاتر قائمة المنتجات (ProductFilterRequest) على الاستعلام.
 97:      *
 98:      * @param  array<string, mixed>  $filters
 99:      */
100:     public function applyFilters(Builder $query, array $filters): Builder
101:     {
102:         if (! empty($filters['category'])) {
103:             $category = $this->resolveCategory($filters['category']);
104:             if ($category !== null) {
105:                 $query->whereIn('products.category_id', [$category->id, ...$category->descendantIds()]);
106:             } else {
107:                 $query->whereRaw('1 = 0'); // قسم غير موجود = نتيجة فارغة لا خطأ
108:             }
109:         }
110: 
111:         if (! empty($filters['brand'])) {
112:             $values = (array) $filters['brand'];
113:             $numericIds = array_map('intval', array_filter($values, fn ($v) => ctype_digit((string) $v)));
114:             $brandIds = Brand::query()->where('is_active', true)
115:                 ->where(fn ($q) => $q->whereIn('id', $numericIds)->orWhereIn('slug', $values))
116:                 ->pluck('id')->all();
117:             $query->whereIn('products.brand_id', $brandIds ?: [0]);
118:         }
119: 
120:         if (! empty($filters['color'])) {
121:             $color = $filters['color'];
122:             $query->whereHas('variants', fn ($q) => $q->where('is_active', true)
123:                 ->where(fn ($inner) => $inner
124:                     ->whereRaw('LOWER(color_name_en) = LOWER(?)', [$color])
125:                     ->orWhere('color_name_ar', $color)));
126:         }
127: 
128:         if (isset($filters['price_min']) || isset($filters['price_max']) || in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)) {
129:             $query->leftJoinLateral($this->minimumPriceQuery(), 'catalog_price');
130:             if (isset($filters['price_min'])) {
131:                 $query->where('catalog_price.minimum_price', '>=', $filters['price_min']);
132:             }
133:             if (isset($filters['price_max'])) {
134:                 $query->where('catalog_price.minimum_price', '<=', $filters['price_max']);
135:             }
136:         }
137: 
138:         if (! empty($filters['in_stock'])) {
139:             $query->whereExists(fn ($sub) => $sub
140:                 ->select(DB::raw(1))
141:                 ->from('stock_levels')
142:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
143:                 ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
144:                 ->where('branches.is_active', true)
145:                 ->where('product_variants.is_active', true)
146:                 ->whereNull('product_variants.deleted_at')
147:                 ->whereColumn('product_variants.product_id', 'products.id')
148:                 ->where('stock_levels.available', '>', 0));
149:         }
150: 
151:         return $this->applySort($query, $filters['sort'] ?? 'newest');
152:     }
153: 
154:     private function applySort(Builder $query, string $sort): Builder
155:     {
156:         if (in_array($sort, ['price_asc', 'price_desc'], true)) {
157:             return $query->orderByRaw('catalog_price.minimum_price '.($sort === 'price_asc' ? 'ASC' : 'DESC').' NULLS LAST')
158:                 ->orderBy('products.id');
159:         }
160: 
161:         return match ($sort) {
162:             'best_selling' => $query->orderByDesc('products.sales_count')->orderByDesc('products.id'),
163:             default => $query->orderByDesc('products.created_at')->orderByDesc('products.id'),
164:         };
165:     }
166: 
167:     private function resolveCategory(int|string $value): ?Category
168:     {
169:         $category = Category::query()->where('is_active', true)->where('slug', $value)->first();
170: 
171:         return $category ?? (ctype_digit((string) $value) && strlen((string) $value) <= 18
172:             ? Category::query()->where('is_active', true)->find((int) $value) : null);
173:     }
174: 
175:     // ------------------------------------------------------------------ أسعار العرض
176: 
177:     /**
178:      * سعر عرض بطاقة المنتج: أرخص متغير نشط قابل للتسعير عبر PricingService
179:      * (متغير بلا سعر ولا قائمة يُتخطى بدل كسر القائمة كلها).
180:      *
181:      * @return array{price: float, base_price: float, compare_at: float|null, discount_percentage: int|null, variant_id: int}|null
182:      */
183:     public function displayPrice(Product $product, ?Customer $customer): ?array
184:     {
185:         $variants = $product->relationLoaded('variants')
186:             ? $product->variants
187:             : $product->variants()->where('is_active', true)->orderBy('sort_order')->get();
188: 
189:         $best = null;
190:         foreach ($variants as $variant) {
191:             try {
192:                 $resolved = $this->variantPrice($variant, $customer);
193:             } catch (BusinessException) {
194:                 continue;
195:             }
196: 
197:             $price = (float) $resolved['unit_price'];
198:             $compareAt = $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null;
199:             $basis = max((float) $compareAt, (float) $resolved['base_price']);
200: 
201:             $display = [
202:                 'price' => $price,
203:                 'base_price' => (float) $resolved['base_price'],
204:                 'compare_at' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1 ? $basis : null,
205:                 'discount_percentage' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1
206:                     ? (int) round((1 - $price / $basis) * 100) : null,
207:                 'variant_id' => $variant->id,
208:             ];
209:             if ($best === null || $price < $best['price']) {
210:                 $best = $display;
211:             }
212:         }
213: 
214:         return $best;
215:     }
216: 
217:     public function customer(): ?Customer
218:     {
219:         $user = auth('sanctum')->user();
220: 
221:         return $user instanceof Customer && $user->status === CustomerStatus::Approved ? $user : null;
222:     }
223: 
224:     public function variantPrice(ProductVariant $variant, ?Customer $customer): array
225:     {
226:         if (! array_key_exists('store_price', $variant->getAttributes())) {
227:             return $this->pricing->resolve($variant, $customer, 1);
228:         }
229:         if ($variant->store_price === null) {
230:             throw new BusinessException('الصنف غير مُسعَّر.');
231:         }
232: 
233:         return ['unit_price' => (float) $variant->store_price, 'base_price' => (float) ($variant->retail_price === null ? $variant->store_price : $variant->base_price)];
234:     }
235: 
236:     private function minimumPriceQuery(): \Illuminate\Database\Query\Builder
237:     {
238:         $variants = $this->pricing->withStorePrice(ProductVariant::query(), $this->customer())
239:             ->where('is_active', true);
240: 
241:         return DB::query()->fromSub($variants, 'priced_variants')
242:             ->selectRaw('MIN(priced_variants.store_price) AS minimum_price')
243:             ->whereColumn('priced_variants.product_id', 'products.id');
244:     }
