292:     /**
293:      * منتجات مشابهة: نفس القسم الفرعي أولًا ثم نفس العلامة، والمتوفر أولًا.
294:      *
295:      * @return Collection<int, Product>
296:      */
297:     public function similar(Product $product): Collection
298:     {
299:         return $this->publishedQuery()
300:             ->where('products.id', '!=', $product->id)
301:             ->where(function ($q) use ($product): void {
302:                 $q->where('products.category_id', $product->category_id);
303:                 if ($product->brand_id !== null) {
304:                     $q->orWhere('products.brand_id', $product->brand_id);
305:                 }
306:             })
307:             ->reorder()
308:             ->orderByRaw('CASE WHEN products.category_id = ? THEN 0 ELSE 1 END', [$product->category_id])
309:             ->withExists(['variants as has_store_stock' => fn ($q) => $q->where('is_active', true)
310:                 ->whereHas('stockLevels', fn ($stock) => $stock->where('available', '>', 0)
311:                     ->whereHas('branch', fn ($branch) => $branch->where('is_active', true)))])
312:             ->orderByDesc('has_store_stock')
313:             ->orderByDesc('products.sales_count')
314:             ->orderByDesc('products.id')
315:             ->limit(8)
316:             ->get();
317:     }
