183:     const snapshot = viewport.cloneNode(true);
184:     const liveInputs = viewport.querySelectorAll('input');
185:     snapshot.querySelectorAll('input').forEach((input, index) => {
186:       input.value = liveInputs[index].value;
187:       input.checked = liveInputs[index].checked;
188:     });
189:     snapshot.removeAttribute('id');
190:     snapshot.style.clipPath = 'none';
191:     snapshot.style.width = viewport.offsetWidth + 'px';
192:     snapshot.style.transform = `translateY(-${scrollY}px)`;
193:     snapshot.querySelectorAll('[id]').forEach(element => element.removeAttribute('id'));
194:     underlay.replaceChildren(snapshot);
195:     underlay.classList.remove('hidden');
196:     flushSync(() => update(next => { next.darkMode = isDark; }));
197:     hostRef.current.setAttribute('data-theme', isDark ? 'dark' : 'light');
198:     viewport.classList.add('no-theme-transitions');
199:     const clipY = cy + scrollY;
200:     viewport.style.clipPath = `circle(0px at ${cx}px ${clipY}px)`;
201:     const started = performance.now();
202:     function step(now) {
203:       const progress = Math.min((now - started) / 660, 1);
204:       const eased = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
205:       viewport.style.clipPath = `circle(${(eased * maxRadius).toFixed(1)}px at ${cx}px ${clipY}px)`;
206:       if (progress < 1) timers.current.wipe = requestAnimationFrame(step);
207:       else {
208:         viewport.style.clipPath = 'none';
209:         viewport.classList.remove('no-theme-transitions');
210:         underlay.classList.add('hidden');
211:         underlay.replaceChildren();
212:       }
213:     }
214:     timers.current.wipe = requestAnimationFrame(step);
215:   }
