38:     setAuthToken(null);
39:     set({ user: null, token: null, isAuthenticated: false });
40:     if (typeof window !== 'undefined' && !window.location.pathname.includes('/login')) {
41:       window.location.href = `${WEB_URL}/auth/login`;
