 6: export interface ApiClientConfig {
 7:   baseURL?: string;
 8:   withCredentials?: boolean;
 9:   getToken?: () => string | null | undefined;
10:   onUnauthorized?: () => void;
11: }
12: 
13: let activeToken: string | null = null;
14: let unauthorizedHandler: (() => void) | null = null;
15: 
16: export function setAuthToken(token: string | null) {
17:   activeToken = token;
18: }
19: 
20: export function getAuthToken(): string | null {
21:   return activeToken;
22: }
23: 
24: export function setUnauthorizedHandler(handler: (() => void) | null) {
25:   unauthorizedHandler = handler;
26: }
