22: function AuthenticatedApp() {
23:   const user = useAuthStore((state) => state.user);
24:   const logoutRemote = useAuthStore((state) => state.logoutRemote);
25:   const readRoute = () => window.location.hash.replace(/^#/, '').split('?')[0]
26:     || window.location.pathname;
27:   const [route, setRoute] = useState(readRoute);
28:   const can = useCallback((permission: string) =>
29:     !!user?.permissions.some((granted) => granted === '*' || granted === permission), [user]);
30:   const cashierOnly = user?.roles.length === 1 && user.roles[0] === 'cashier';
31:   useEffect(() => {
32:     const changed = () => setRoute(readRoute());
33:     window.addEventListener('hashchange', changed);
34:     window.addEventListener('popstate', changed);
35:     return () => {
36:       window.removeEventListener('hashchange', changed);
37:       window.removeEventListener('popstate', changed);
38:     };
39:   }, []);
40:   useEffect(() => {
41:     if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) window.location.replace('/dashboard');
42:     else if (!['/', '/dashboard', '/categories', '/brands', '/pos'].includes(route) && !/^\/products(?:\/(?:new|[0-9]+))?$/.test(route)) window.location.replace('/dashboard');
43:   }, [cashierOnly, route]);
44:   if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) return null;
45:   if (route === '/pos') return <PosPage />;
46:   const categoriesActive = route === '/categories';
47:   const catalogActive = route.startsWith('/products') ? 'products' : route === '/brands' ? 'brands' : null;
48:   return <FinancialDashboard
49:     onLogout={logoutRemote}
50:     catalogActive={catalogActive}
51:     catalogPage={catalogActive && <CatalogMockPage key={catalogActive} can={can} page={catalogActive} />}
52:     catalogNav={!cashierOnly ? [
53:       ...(can('products.view') ? [{ id: 'products', label: 'المنتجات', onOpen: () => { window.location.hash = '/products'; } }] : []),
54:       ...(can('brands.view') ? [{ id: 'brands', label: 'البراندات', onOpen: () => { window.location.hash = '/brands'; } }] : []),
55:     ] : []}
56:     onCloseCatalog={() => { window.location.hash = '/dashboard'; }}
57:     categoriesActive={categoriesActive}
58:     categoriesPage={<CategoriesMockPage can={can} embedded />}
59:     onOpenCategories={!cashierOnly && can('categories.view')
60:       ? () => { window.location.hash = '/categories'; }
61:       : undefined}
62:     onCloseCategories={() => { window.location.hash = '/dashboard'; }}
63:   />;
64: }
