   7:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
   8:   }, [open]);
   9:   if (!open) return null;
  10:   return (
  11:     <div className="fixed inset-0 z-[60] fade" style={{ background: 'var(--overlay)', backdropFilter: 'blur(2px)' }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
  12:       <div className="drawer absolute top-3 bottom-3 start-3 v-card flex flex-col overflow-hidden" style={{ width, maxWidth: 'calc(100vw - 24px)', boxShadow: 'var(--shadow-pop)', borderRadius: 26 }}>
  13:         <div className="px-6 pt-6 pb-4 flex items-start justify-between gap-3 v-border-b">
  14:           <div>
  15:             <h3 className="font-display text-[19px] font-semibold t-1">{title}</h3>
  16:             {subtitle && <p className="text-[12.5px] t-2 mt-0.5">{subtitle}</p>}
  17:           </div>
  18:           <button className="icon-btn" onClick={onClose}><Icon name="x" size={16} /></button>
  19:         </div>
  20:         <div className="flex-1 overflow-y-auto px-6 py-5">{children}</div>
  21:         {footer && <div className="px-6 py-4 v-border-t flex items-center justify-end gap-2">{footer}</div>}
  22:       </div>
  23:     </div>
  24:   );
  25: }
  26: 
  27: function RowActions({ onEdit, onDelete, extra }) {
  28:   return (
  29:     <div className="flex items-center justify-end gap-0.5" onClick={(e) => e.stopPropagation()}>
  30:       {extra}
  31:       {onEdit && <button className="icon-btn" title="تعديل" onClick={onEdit}><Icon name="edit" size={15} /></button>}
  32:       {onDelete && <button className="icon-btn hover:!text-[var(--badge-red-text)]" title="حذف" onClick={onDelete}><Icon name="trash" size={15} /></button>}
  33:     </div>
  34:   );
  35: }
