  38: function BranchesPage() {
  39:   const { user } = useApp();
  40:   const [q, setQ] = useQueryState({ page: 1, per_page: 10, search: '', type: '', status: '' });
  41:   const [phase, retry] = useLoad([q.page, q.per_page, q.search, q.type, q.status]);
  42:   const [form, setForm] = useState(null);
  43:   const [del, setDel] = useState(null);
  44:   if (!user.can('branches.view')) return <Forbidden perm="branches.view" />;
  45:   const filtered = BRANCHES.filter((b) => (!q.search || (b.name + b.code).toLowerCase().includes(q.search.toLowerCase())) && (!q.type || b.type === q.type) && (!q.status || b.status === q.status));
  46:   const res = fakeQuery(filtered, { page: +q.page, per_page: +q.per_page });
  47:   const counts = { branch: BRANCHES.filter((b) => b.type === 'branch').length, warehouse: BRANCHES.filter((b) => b.type === 'warehouse').length };
  48:   return (
  49:     <div className="space-y-5">
  50:       <PageHeader crumbs={[{ label: 'الإدارة' }, { label: 'الفروع' }]} title="الفروع والمخازن" subtitle="أماكن البيع والتخزين، وكل فرع له مواقع تخزين خاصة بيه."
  51:         actions={user.can('branches.manage') && <button className="btn btn-ink" onClick={() => setForm({})}><Icon name="plus" size={15} />فرع جديد</button>} />
  52:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stagger s2">
  53:         <div className="v-orange rounded-[22px] p-5"><div className="flex items-center justify-between text-[12.5px] text-white/90">الإجمالي<span className="w-7 h-7 rounded-full bg-white/15 flex items-center justify-center"><Icon name="building" size={14} /></span></div><div className="font-display text-[32px] font-bold mt-3 num">{BRANCHES.length}</div></div>
  54:         <div className="v-card p-5"><div className="flex items-center justify-between text-[12.5px] t-2">فروع بيع<span className="w-7 h-7 rounded-full v-well flex items-center justify-center"><Icon name="store" size={14} /></span></div><div className="font-display text-[32px] font-bold mt-3 num t-1">{counts.branch}</div></div>
  55:         <div className="v-card p-5"><div className="flex items-center justify-between text-[12.5px] t-2">مخازن<span className="w-7 h-7 rounded-full v-well flex items-center justify-center"><Icon name="warehouse" size={14} /></span></div><div className="font-display text-[32px] font-bold mt-3 num t-1">{counts.warehouse}</div></div>
  56:         <div className="v-card p-5"><div className="flex items-center justify-between text-[12.5px] t-2">مواقع تخزين<span className="w-7 h-7 rounded-full v-well flex items-center justify-center"><Icon name="layers" size={14} /></span></div><div className="font-display text-[32px] font-bold mt-3 num t-1">{BRANCHES.reduce((a, b) => a + b.locations, 0)}</div></div>
  57:       </div>
  58:       <div className="stagger s3">
  59:         <DataTable state={phase} onRetry={retry} rows={res.data} meta={res.meta} filtered={q.search || q.type || q.status}
  60:           onPage={(p) => setQ({ page: p })} onPerPage={(n) => setQ({ per_page: n, page: 1 })}
  61:           onRowClick={(r) => nav('/branches/' + r.id)}
  62:           empty={!(q.search || q.type || q.status) && <EmptyState icon="building" title="لا توجد فروع بعد" body="أضف أول فرع أو مخزن عشان تبدأ تربط المستخدمين والمخزون بيه." action={<button className="btn btn-ink" onClick={() => setForm({})}><Icon name="plus" size={15} />فرع جديد</button>} />}
  63:           toolbar={
  64:             <div className="flex flex-wrap items-center gap-2">
  65:               <SearchBox value={q.search} onChange={(v) => setQ({ search: v, page: 1 })} placeholder="ابحث بالاسم أو الكود…" />
  66:               <FilterMenu label="النوع" value={q.type || null} onChange={(v) => setQ({ type: v, page: 1 })} options={[{ value: 'branch', label: 'فرع' }, { value: 'warehouse', label: 'مخزن' }]} />
  67:               <FilterMenu label="الحالة" value={q.status || null} onChange={(v) => setQ({ status: v, page: 1 })} options={[{ value: 'active', label: 'نشط', dot: 'var(--badge-green-text)' }, { value: 'inactive', label: 'غير نشط', dot: 'var(--text-muted)' }]} />
  68:             </div>
  69:           }
  70:           columns={[
  71:             { key: 'name', label: 'الفرع', render: (r) => (
  72:               <div className="flex items-center gap-3">
  73:                 <span className={cx('w-9 h-9 rounded-full flex items-center justify-center', r.type === 'warehouse' ? 'b-blue' : 'b-acc')}><Icon name={r.type === 'warehouse' ? 'warehouse' : 'store'} size={16} /></span>
  74:                 <div><div className="font-semibold t-1">{r.name}</div><div className="text-[11.5px] t-3 ltr text-end inline-block">{r.code}</div></div>
  75:               </div>), skel: () => <div className="flex items-center gap-3"><Skel w={36} h={36} r={999} /><div className="space-y-1.5 flex-1"><Skel w="60%" h={10} /><Skel w="30%" h={8} /></div></div> },
  76:             { key: 'type', label: 'النوع', render: (r) => <Badge tone={r.type === 'warehouse' ? 'blue' : 'acc'}>{r.type === 'warehouse' ? 'مخزن' : 'فرع'}</Badge> },
  77:             { key: 'city', label: 'المدينة', render: (r) => <span className="t-2">{r.city}</span> },
  78:             { key: 'phone', label: 'الهاتف', render: (r) => r.phone ? <span className="ltr inline-block t-2 num">{r.phone}</span> : <span className="t-3">—</span> },
  79:             { key: 'locations', label: 'مواقع التخزين', render: (r) => <span className="num font-semibold t-1">{r.locations}</span> },
  80:             { key: 'status', label: 'الحالة', render: (r) => <StatusBadge s={r.status} /> },
  81:             { key: 'a', label: '', render: (r) => user.can('branches.manage') && <RowActions onEdit={() => setForm(r)} onDelete={() => setDel(r)} /> },
  82:           ]}
  83:         />
  84:       </div>
  85:       <BranchForm open={!!form} branch={form} onClose={() => setForm(null)} />
  86:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} danger title={`حذف «${del && del.name}»؟`} message="الحذف نهائي. المستخدمون المرتبطون بالفرع هيفقدوا ارتباطهم بيه." confirmLabel="حذف الفرع"
  87:         serverError={del && del.locations > 0 ? { title: 'لا يمكن حذف هذا الفرع', body: 'الفرع مرتبط ببيانات لازم تتنقل أو تتحذف الأول:', items: [`${del.locations} موقع تخزين`, `${del.users} مستخدم`, 'أرصدة مخزون حالية'] } : null} />
  88:     </div>
  89:   );
  90: }
