 321: /* ====================== USERS ====================== */
 322: function UsersPage() {
 323:   const { user } = useApp();
 324:   const [q, setQ] = useQueryState({ page: 1, per_page: 10, search: '', role: '', status: '' });
 325:   const [phase, retry] = useLoad([q.page, q.per_page, q.search, q.role, q.status]);
 326:   const [form, setForm] = useState(null);
 327:   if (!user.can('users.view')) return <Forbidden perm="users.view" />;
 328:   const rows = USERS.filter((u) => (!q.search || (u.name + u.email).toLowerCase().includes(q.search.toLowerCase())) && (!q.role || u.roles.includes(+q.role)) && (!q.status || u.status === q.status));
 329:   const res = fakeQuery(rows, { page: +q.page, per_page: +q.per_page });
 330:   return (
 331:     <div className="space-y-5">
 332:       <PageHeader crumbs={[{ label: 'الإدارة' }, { label: 'المستخدمون' }]} title="المستخدمون" subtitle="حسابات فريق العمل، الفرع، والأدوار."
 333:         actions={user.can('users.manage') && <button className="btn btn-ink" onClick={() => setForm({})}><Icon name="plus" size={15} />مستخدم جديد</button>} />
 334:       <div className="stagger s2">
 335:         <DataTable state={phase} onRetry={retry} rows={res.data} meta={res.meta} filtered={q.search || q.role || q.status} onPage={(p) => setQ({ page: p })} onPerPage={(n) => setQ({ per_page: n, page: 1 })}
 336:           toolbar={<div className="flex flex-wrap items-center gap-2">
 337:             <SearchBox value={q.search} onChange={(v) => setQ({ search: v, page: 1 })} placeholder="ابحث بالاسم أو البريد…" />
 338:             <FilterMenu label="الدور" value={q.role ? +q.role : null} onChange={(v) => setQ({ role: v, page: 1 })} options={ROLES.map((r) => ({ value: r.id, label: r.name }))} />
 339:             <FilterMenu label="الحالة" value={q.status || null} onChange={(v) => setQ({ status: v, page: 1 })} options={[{ value: 'active', label: 'نشط' }, { value: 'inactive', label: 'موقوف' }]} />
 340:           </div>}
 341:           columns={[
 342:             { key: 'name', label: 'المستخدم', render: (r) => <div className="flex items-center gap-3"><Avatar name={r.name} size={36} /><div><div className="font-semibold t-1">{r.name}</div><div className="text-[11.5px] t-3 ltr">{r.email}</div></div></div>, skel: () => <div className="flex items-center gap-3"><Skel w={36} h={36} r={999} /><div className="space-y-1.5 flex-1"><Skel w="60%" h={10} /><Skel w="45%" h={8} /></div></div> },
 343:             { key: 'branch', label: 'الفرع', render: (r) => r.allBranches ? <Badge tone="acc"><Icon name="globe" size={11} />كل الفروع</Badge> : r.branch ? <span className="t-1">{BRANCHES.find((b) => b.id === r.branch).name}</span> : <span className="t-3">بدون فرع</span> },
 344:             { key: 'roles', label: 'الأدوار', render: (r) => <div className="flex flex-wrap gap-1">{r.roles.map((id) => <Badge key={id}>{ROLES.find((x) => x.id === id).name}</Badge>)}</div> },
 345:             { key: 'last', label: 'آخر نشاط', render: (r) => <span className="t-2 text-[12px]">{r.last}</span> },
 346:             { key: 'status', label: 'الحالة', render: (r) => r.status === 'active' ? <Badge tone="green" dot>نشط</Badge> : <Badge dot>موقوف</Badge> },
 347:             { key: 'a', label: '', render: (r) => user.can('users.manage') && <RowActions onEdit={() => setForm(r)} /> },
 348:           ]} />
 349:       </div>
 350:       <UserForm open={!!form} u={form} onClose={() => setForm(null)} />
 351:     </div>
 352:   );
 353: }
