 403: /* ====================== SETTINGS ====================== */
 404: function SettingsPage() {
 405:   const { user } = useApp();
 406:   const [sec, setSec] = useQueryState({ s: 'company' });
 407:   const init = { company_name: 'Vortix Home', company_name_en: 'Vortix Home LLC', tax_number: '512-889-301', cr: '88231', tax_enabled: true, tax_rate: 14, prices_include_tax: true,
 408:     num: { invoice: { prefix: 'INV-', pad: 6, next: 1042, year: true }, purchase: { prefix: 'PO-', pad: 5, next: 318, year: true }, transfer: { prefix: 'TR-', pad: 5, next: 77, year: false }, return: { prefix: 'RT-', pad: 5, next: 24, year: true } },
 409:     return_mode: 'days', return_days: 14, self_approve: false, logo: '' };
 410:   const [v, setV] = useState(init);
 411:   const [saved, setSaved] = useState(init);
 412:   const [conflict, setConflict] = useState(false);
 413:   const dirty = JSON.stringify(v) !== JSON.stringify(saved);
 414:   useUnsavedGuard(dirty);
 415:   if (!user.can('settings.view')) return <Forbidden perm="settings.view" />;
 416:   const ro = !user.can('settings.update');
 417:   const sections = [['company', 'بيانات الشركة', 'building'], ['tax', 'الضرائب', 'percent'], ['numbering', 'ترقيم المستندات', 'hash'], ['returns', 'سياسة الإرجاع', 'rotate'], ['purchases', 'المشتريات', 'receipt']];
 418:   const preview = (n) => `${n.prefix}${n.year ? '2026-' : ''}${String(n.next).padStart(n.pad, '0')}`;
 419:   const setNum = (k, patch) => setV({ ...v, num: { ...v.num, [k]: { ...v.num[k], ...patch } } });
 420:   const numLabels = { invoice: 'فواتير البيع', purchase: 'أوامر الشراء', transfer: 'التحويلات', return: 'المرتجعات' };
 421:   return (
 422:     <div className="space-y-5">
 423:       <PageHeader crumbs={[{ label: 'الإدارة' }, { label: 'الإعدادات' }]} title="الإعدادات" subtitle="إعدادات عامة بتأثر على كل الفروع والمستندات." badge={ro && <Badge tone="amber"><Icon name="eye" size={11} />قراءة فقط</Badge>} />
 424:       {conflict && <Banner tone="amber" icon="refresh" title="الإعدادات اتعدلت من مستخدم آخر (409)" className="pop" onClose={() => setConflict(false)}
 425:         action={<button className="btn btn-sm btn-ink" onClick={() => { setConflict(false); vtoast('تم تحميل أحدث نسخة', 'info'); }}>تحميل أحدث نسخة</button>}>
 426:         تعديلاتك لسه موجودة هنا. حمّل النسخة الأحدث وراجع الفروقات قبل الحفظ مرة أخرى.
 427:       </Banner>}
 428:       <div className="grid lg:grid-cols-[240px_1fr] gap-5 items-start">
 429:         <div className="v-card p-2 lg:sticky lg:top-5 stagger s2">
 430:           {sections.map(([k, l, ic]) => (
 431:             <button key={k} onClick={() => setSec({ s: k })} className={cx('w-full flex items-center gap-3 p-2.5 rounded-[14px] text-[13px] font-medium transition text-start', sec.s === k ? 'bg-ink' : 't-2 hover:bg-[var(--bg-subcard)] hover:t-1')}>
 432:               <span className={cx('w-8 h-8 rounded-full flex items-center justify-center', sec.s === k ? 'bg-white/15' : 'v-well')}><Icon name={ic} size={15} /></span>{l}
 433:             </button>
 434:           ))}
 435:         </div>
 436:         <div className="space-y-5 stagger s3">
 437:           {sec.s === 'company' && (
 438:             <SectionCard title="بيانات الشركة" subtitle="تظهر في رأس الفواتير والمستندات المطبوعة.">
 439:               <div className="space-y-5">
 440:                 <Field label="لوجو الشركة" hint="حاليًا الحقل company_logo نصّي (رابط). الرفع المباشر يحتاج مسار رفع في الـ API — لحين توفره أدخل رابط الصورة.">
 441:                   <div className="flex items-center gap-4">
 442:                     <div className="w-[72px] h-[72px] rounded-[18px] checker shrink-0 flex items-center justify-center t-3 overflow-hidden">{v.logo ? <div className="w-full h-full" style={{ background: 'radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%)' }} /> : <Icon name="image" size={20} />}</div>
 443:                     <div className="flex-1"><Input ltr icon="link" value={v.logo} onChange={(e) => setV({ ...v, logo: e.target.value })} disabled={ro} placeholder="https://cdn.company.com/logo.png" /></div>
 444:                     <button className="btn btn-soft" disabled title="يتطلب مسار رفع في الـ API"><Icon name="upload" size={14} />رفع<Badge tone="amber" className="!py-0 !text-[9.5px]">قريبًا</Badge></button>
 445:                   </div>
 446:                 </Field>
 447:                 <div className="grid md:grid-cols-2 gap-4">
 448:                   <Field label="اسم الشركة (عربي)" required><Input value={v.company_name} onChange={(e) => setV({ ...v, company_name: e.target.value })} readOnly={ro} /></Field>
 449:                   <Field label="اسم الشركة (إنجليزي)"><Input ltr value={v.company_name_en} onChange={(e) => setV({ ...v, company_name_en: e.target.value })} readOnly={ro} /></Field>
 450:                   <Field label="السجل التجاري"><Input ltr value={v.cr} onChange={(e) => setV({ ...v, cr: e.target.value })} readOnly={ro} /></Field>
 451:                   <Field label="البطاقة الضريبية"><Input ltr value={v.tax_number} onChange={(e) => setV({ ...v, tax_number: e.target.value })} readOnly={ro} /></Field>
 452:                 </div>
 453:               </div>
 454:             </SectionCard>
 455:           )}
 456:           {sec.s === 'tax' && (
 457:             <SectionCard title="الضرائب">
 458:               <div className="space-y-4">
 459:                 <div className="v-subcard p-4 flex items-center justify-between"><div><div className="text-[13px] font-semibold t-1">تفعيل ضريبة القيمة المضافة</div><div className="text-[11.5px] t-3">تُحسب على فواتير البيع والشراء.</div></div><Toggle on={v.tax_enabled} disabled={ro} onChange={(x) => setV({ ...v, tax_enabled: x })} /></div>
 460:                 <div className="grid md:grid-cols-2 gap-4">
 461:                   <Field label="نسبة الضريبة" required hint="منزلتين عشريتين بحد أقصى"><Input ltr suffix="%" value={v.tax_rate} onChange={(e) => setV({ ...v, tax_rate: e.target.value })} disabled={!v.tax_enabled || ro} /></Field>
 462:                   <Field label="الأسعار المدخلة">
 463:                     <Seg value={v.prices_include_tax ? 'inc' : 'exc'} onChange={(x) => !ro && setV({ ...v, prices_include_tax: x === 'inc' })} options={[{ value: 'inc', label: 'شاملة الضريبة' }, { value: 'exc', label: 'غير شاملة' }]} />
 464:                   </Field>
 465:                 </div>
 466:                 <div className="v-subcard p-4 text-[12.5px] flex items-center justify-between"><span className="t-2">مثال: منتج بسعر <b className="t-1 num">1,000</b></span><span className="t-1 font-semibold num">{v.prices_include_tax ? `صافي ${fmtMoney(1000 / (1 + v.tax_rate / 100))} + ضريبة ${fmtMoney(1000 - 1000 / (1 + v.tax_rate / 100))}` : `الإجمالي ${fmtMoney(1000 * (1 + v.tax_rate / 100))}`}</span></div>
 467:               </div>
 468:             </SectionCard>
 469:           )}
 470:           {sec.s === 'numbering' && (
 471:             <SectionCard title="ترقيم المستندات" subtitle="المعاينة توضح شكل رقم المستند التالي.">
 472:               <div className="space-y-3">
 473:                 {Object.entries(v.num).map(([k, n]) => (
 474:                   <div key={k} className="v-subcard p-4">
 475:                     <div className="flex flex-wrap items-center justify-between gap-3 mb-3.5">
 476:                       <div className="text-[13px] font-semibold t-1">{numLabels[k]}</div>
 477:                       <div className="flex items-center gap-2 text-[11.5px] t-3">المستند التالي
 478:                         <span className="ltr font-display text-[15px] font-bold px-3 py-1 rounded-full t-1" style={{ background: 'var(--bg-card)', border: '1px solid var(--border-subtle)' }}>
 479:                           <span className="t-acc">{n.prefix}</span>{n.year && <span className="t-2">2026-</span>}<span>{String(n.next).padStart(n.pad, '0')}</span>
 480:                         </span>
 481:                       </div>
 482:                     </div>
 483:                     <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
 484:                       <Field label="البادئة"><Input ltr value={n.prefix} onChange={(e) => setNum(k, { prefix: e.target.value })} readOnly={ro} /></Field>
 485:                       <Field label="عدد الخانات"><Input ltr type="number" min={1} max={10} value={n.pad} onChange={(e) => setNum(k, { pad: +e.target.value || 1 })} readOnly={ro} /></Field>
 486:                       <Field label="الرقم التالي"><Input ltr type="number" value={n.next} onChange={(e) => setNum(k, { next: +e.target.value || 1 })} readOnly={ro} /></Field>
 487:                       <Field label="إضافة السنة"><div className="h-[42px] flex items-center"><Toggle on={n.year} disabled={ro} onChange={(x) => setNum(k, { year: x })} /></div></Field>
 488:                     </div>
 489:                   </div>
 490:                 ))}
 491:               </div>
 492:             </SectionCard>
 493:           )}
 494:           {sec.s === 'returns' && (
 495:             <SectionCard title="سياسة الإرجاع" subtitle="بتتطبق على فواتير البيع في كل الفروع.">
 496:               <div className="grid md:grid-cols-3 gap-3">
 497:                 {[['off', 'متوقف', 'لا يُسمح بالإرجاع', 'ban', 'return_enabled=false'], ['unlimited', 'بدون حد زمني', 'الإرجاع مسموح في أي وقت', 'rotate', 'return_days=null'], ['days', 'خلال عدد أيام', 'من تاريخ الفاتورة', 'clock', `return_days=${v.return_days}`]].map(([k, l, s, ic, api]) => (
 498:                   <button key={k} disabled={ro} onClick={() => setV({ ...v, return_mode: k })} className={cx('rounded-[18px] p-4 text-start border transition', v.return_mode === k ? 'border-[var(--accent)] bg-[var(--accent-soft)]' : 'border-[var(--border-field)] hover:bg-[var(--bg-subcard)]')}>
 499:                     <div className="flex items-center justify-between"><span className={cx('w-9 h-9 rounded-full flex items-center justify-center', v.return_mode === k ? 'bg-acc' : 'v-well')}><Icon name={ic} size={16} /></span><span className={cx('w-5 h-5 rounded-full border-2 flex items-center justify-center', v.return_mode === k ? 'border-[var(--accent)]' : 'border-[var(--border-field)]')}>{v.return_mode === k && <span className="w-2.5 h-2.5 rounded-full bg-[var(--accent)]" />}</span></div>
 500:                     <div className="text-[13.5px] font-semibold t-1 mt-3">{l}</div><div className="text-[11.5px] t-3 mt-0.5">{s}</div>
 501:                     <div className="text-[10px] t-3 mt-3 ltr text-end opacity-70">{api}</div>
 502:                   </button>
 503:                 ))}
 504:               </div>
 505:               {v.return_mode === 'days' && (
 506:                 <div className="pop mt-4 v-subcard p-4 flex flex-wrap items-center gap-4">
 507:                   <div className="w-[160px]"><Input ltr type="number" min={1} suffix="يوم" value={v.return_days} onChange={(e) => setV({ ...v, return_days: +e.target.value })} readOnly={ro} /></div>
 508:                   <div className="flex gap-1.5">{[7, 14, 30].map((d) => <button key={d} onClick={() => setV({ ...v, return_days: d })} className={cx('h-8 px-3 rounded-full text-[12px] font-semibold num', v.return_days === d ? 'bg-ink' : 'btn-outline')}>{d}</button>)}</div>
 509:                   <span className="text-[12px] t-2">فاتورة يوم ١ أكتوبر تقبل الإرجاع حتى <b className="t-1 num">{v.return_days + 1}</b> أكتوبر.</span>
 510:                 </div>
 511:               )}
 512:             </SectionCard>
 513:           )}
 514:           {sec.s === 'purchases' && (
 515:             <SectionCard title="المشتريات">
 516:               <div className="v-subcard p-4 flex items-start justify-between gap-4">
 517:                 <div><div className="text-[13px] font-semibold t-1">السماح باعتماد المشتريات ذاتيًا</div><div className="text-[11.5px] t-3 mt-0.5 leading-relaxed max-w-[460px]">لو مفعّل، المستخدم اللي أنشأ أمر الشراء ويملك صلاحية الاعتماد يقدر يعتمده بنفسه. لو متوقف، لازم مستخدم آخر يعتمده.</div></div>
 518:                 <Toggle on={v.self_approve} disabled={ro} onChange={(x) => setV({ ...v, self_approve: x })} />
 519:               </div>
 520:               {v.self_approve && <Banner tone="amber" icon="alert" className="mt-3 pop">تفعيل الاعتماد الذاتي يقلل الفصل بين المهام. ننصح بإبقائه متوقف للفرق الكبيرة.</Banner>}
 521:             </SectionCard>
 522:           )}
 523:         </div>
 524:       </div>
 525:       {!ro && <StickyBar dirty={dirty}>
 526:         <button className="btn btn-ghost" disabled={!dirty} onClick={() => setV(saved)}>تجاهل التغييرات</button>
 527:         <button className="btn btn-ink" disabled={!dirty} onClick={() => { if (v.company_name === 'تعارض') { setConflict(true); return; } setSaved(v); vtoast('تم حفظ الإعدادات'); }}>حفظ الإعدادات</button>
 528:       </StickyBar>}
 529:     </div>
 530:   );
 531: }
 532: 
 533: Object.assign(window, { Drawer, RowActions, BranchesPage, BranchDetail, RolesPage, UsersPage, SettingsPage });
 534: 
 535: // Phase 2 — Categories tree, Brands, Products list
 536: 
 537: /* ====================== CATEGORIES ====================== */
 538: const MAX_DEPTH = 3;
 539: function treeDepth(n) { return 1 + Math.max(0, ...(n.children || []).map(treeDepth)); }
 540: function findNode(nodes, id, parent = null, depth = 1) {
 541:   for (const n of nodes) {
 542:     if (n.id === id) return { node: n, parent, depth };
 543:     const r = findNode(n.children || [], id, n, depth + 1); if (r) return r;
 544:   }
 545:   return null;
 546: }
 547: function isDescendant(node, id) { return (node.children || []).some((c) => c.id === id || isDescendant(c, id)); }
 548: function removeNode(nodes, id) { return nodes.filter((n) => n.id !== id).map((n) => ({ ...n, children: removeNode(n.children || [], id) })); }
 549: function insertInto(nodes, parentId, node) {
 550:   if (parentId == null) return [...nodes, node];
 551:   return nodes.map((n) => n.id === parentId ? { ...n, children: [...(n.children || []), node] } : { ...n, children: insertInto(n.children || [], parentId, node) });
 552: }
 553: function sumProducts(n) { return (n.products || 0) + (n.children || []).reduce((a, c) => a + sumProducts(c), 0); }
 554: 
 555: function CategoriesPage() {
 556:   const { user } = useApp();
 557:   const [tree, setTree] = useState(CATEGORIES);
 558:   const [saved, setSaved] = useState(CATEGORIES);
 559:   const [open, setOpen] = useState({ 1: true, 11: true, 2: true });
 560:   const [sel, setSel] = useState(11);
 561:   const [drag, setDrag] = useState(null);
 562:   const [over, setOver] = useState(null);
 563:   const [invalid, setInvalid] = useState(null);
 564:   const [form, setForm] = useState(null);
 565:   const [del, setDel] = useState(null);
 566:   const [disable, setDisable] = useState(null);
 567:   const [search, setSearch] = useState('');
 568:   const [phase, retry] = useLoad([]);
 569:   if (!user.can('categories.view')) return <Forbidden perm="categories.view" />;
 570:   const dirty = JSON.stringify(tree) !== JSON.stringify(saved);
 571:   const canManage = user.can('categories.manage');
 572: 
 573:   const canDropInto = (dragId, targetId) => {
 574:     if (dragId === targetId) return { ok: false, why: 'لا يمكن نقل القسم داخل نفسه' };
 575:     const d = findNode(tree, dragId); if (!d) return { ok: false };
 576:     if (targetId != null) {
 577:       if (isDescendant(d.node, targetId)) return { ok: false, why: 'لا يمكن نقل القسم داخل أحد أقسامه الفرعية' };
 578:       const t = findNode(tree, targetId);
 579:       if (t.depth + treeDepth(d.node) > MAX_DEPTH) return { ok: false, why: `النقل هنا يتجاوز الحد الأقصى (${MAX_DEPTH} مستويات)` };
 580:     }
 581:     return { ok: true };
 582:   };
 583:   const doMove = (dragId, targetId) => {
 584:     const chk = canDropInto(dragId, targetId);
 585:     if (!chk.ok) { vtoast(chk.why, 'error'); return; }
 586:     const d = findNode(tree, dragId);
 587:     setTree(insertInto(removeNode(tree, dragId), targetId, d.node));
 588:     if (targetId) setOpen({ ...open, [targetId]: true });
 589:   };
 590: 
 591:   const selected = sel && findNode(tree, sel);
 592:   const flat = flattenCats(tree);
 593:   const matches = (n) => !search || n.ar.includes(search) || n.en.toLowerCase().includes(search.toLowerCase()) || (n.children || []).some(matches);
 594: 
 595:   const Node = ({ n, depth }) => {
 596:     const has = (n.children || []).length > 0;
 597:     const isOpen = open[n.id] || !!search;
 598:     const chk = drag != null && over === n.id ? canDropInto(drag, n.id) : null;
 599:     if (!matches(n)) return null;
 600:     return (
 601:       <div>
 602:         <div draggable={canManage} onDragStart={(e) => { e.stopPropagation(); setDrag(n.id); }} onDragEnd={() => { setDrag(null); setOver(null); setInvalid(null); }}
 603:           onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); if (over !== n.id) { setOver(n.id); const c = canDropInto(drag, n.id); setInvalid(c.ok ? null : c.why); } }}
 604:           onDrop={(e) => { e.preventDefault(); e.stopPropagation(); doMove(drag, n.id); setDrag(null); setOver(null); setInvalid(null); }}
 605:           onClick={() => setSel(n.id)}
 606:           className={cx('group flex items-center gap-2 h-12 pe-2 rounded-[14px] cursor-pointer transition relative',
 607:             sel === n.id ? 'bg-[var(--bg-subcard)]' : 'hover:bg-[var(--bg-subcard)]',
 608:             drag === n.id && 'opacity-40',
 609:             chk && (chk.ok ? 'ring-2 ring-[var(--accent)] bg-[var(--accent-soft)]' : 'ring-2 ring-[var(--badge-red-text)] bg-[var(--badge-red-bg)]'))}
 610:           style={{ paddingInlineStart: 8 + (depth - 1) * 26 }}>
 611:           {depth > 1 && <span className="absolute top-0 bottom-1/2 w-3 border-b border-s rounded-es-lg" style={{ insetInlineStart: (depth - 1) * 26 - 10, borderColor: 'var(--border-field)' }} />}
 612:           {canManage && <span className="t-3 opacity-0 group-hover:opacity-100 cursor-grab"><Icon name="drag" size={14} /></span>}
 613:           <button onClick={(e) => { e.stopPropagation(); setOpen({ ...open, [n.id]: !isOpen }); }} className={cx('w-6 h-6 rounded-full flex items-center justify-center t-3 hover:bg-[var(--bg-card)]', !has && 'invisible')}>
 614:             <Icon name="chevLeft" size={13} className={cx('transition', isOpen && '-rotate-90')} />
 615:           </button>
 616:           <span className={cx('w-8 h-8 rounded-[10px] flex items-center justify-center shrink-0', depth === 1 ? '' : 'v-well')} style={depth === 1 ? { background: n.img || IMG[0] } : null}>
 617:             {depth > 1 && <Icon name={has ? (isOpen ? 'folderOpen' : 'folder') : 'tag'} size={14} />}
 618:           </span>
 619:           <div className="flex-1 min-w-0">
 620:             <div className="flex items-center gap-2"><span className={cx('text-[13px] truncate', depth === 1 ? 'font-semibold t-1' : 'font-medium t-1', n.status === 'inactive' && 'opacity-50')}>{n.ar}</span>{n.status === 'inactive' && <Badge className="!py-0 !text-[10px]">غير نشط</Badge>}</div>
 621:             <div className="text-[11px] t-3 ltr text-end inline-block">{n.en}</div>
 622:           </div>
 623:           <span className="text-[11px] t-3 num hidden sm:inline">{sumProducts(n)} منتج</span>
 624:           <span className="text-[10px] font-bold w-5 h-5 rounded-full v-well flex items-center justify-center num">{depth}</span>
 625:           {canManage && (
 626:             <div className="flex items-center opacity-0 group-hover:opacity-100 transition" onClick={(e) => e.stopPropagation()}>
 627:               {depth < MAX_DEPTH ? <button title="إضافة قسم فرعي" className="icon-btn !w-8 !h-8" onClick={() => setForm({ parent: n.id })}><Icon name="plus" size={14} /></button>
 628:                 : <span title="الحد الأقصى ٣ مستويات" className="icon-btn !w-8 !h-8 opacity-30 cursor-not-allowed"><Icon name="plus" size={14} /></span>}
 629:               <button title="تعديل" className="icon-btn !w-8 !h-8" onClick={() => setForm(n)}><Icon name="edit" size={14} /></button>
 630:               <button title="حذف" className="icon-btn !w-8 !h-8" onClick={() => setDel(n)}><Icon name="trash" size={14} /></button>
 631:             </div>
 632:           )}
 633:         </div>
 634:         {chk && !chk.ok && <div className="pop text-[11px] font-semibold flex items-center gap-1 my-1" style={{ color: 'var(--badge-red-text)', paddingInlineStart: 40 + (depth - 1) * 26 }}><Icon name="ban" size={12} />{chk.why}</div>}
 635:         {has && isOpen && <div className="mt-0.5 space-y-0.5">{n.children.map((c) => <Node key={c.id} n={c} depth={depth + 1} />)}</div>}
 636:       </div>
 637:     );
 638:   };
 639: 
 640:   return (
 641:     <div className="space-y-5">
 642:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'الأقسام' }]} title="الأقسام" subtitle={`شجرة أقسام حتى ${MAX_DEPTH} مستويات. اسحب لإعادة الترتيب أو استخدم «نقل إلى».`}
 643:         actions={canManage && <button className="btn btn-ink" onClick={() => setForm({ parent: null })}><Icon name="plus" size={15} />قسم رئيسي</button>} />
 644:       <div className="grid lg:grid-cols-[1fr_340px] gap-5 items-start">
 645:         <div className="v-card p-4 stagger s2">
 646:           <div className="flex flex-wrap items-center justify-between gap-2 mb-3 px-1">
 647:             <SearchBox value={search} onChange={setSearch} placeholder="ابحث في الأقسام…" width={260} />
 648:             <div className="flex items-center gap-1.5">
 649:               <button className="btn btn-ghost btn-sm" onClick={() => setOpen(Object.fromEntries(flat.map((f) => [f.id, true])))}>فتح الكل</button>
 650:               <button className="btn btn-ghost btn-sm" onClick={() => setOpen({})}>طي الكل</button>
 651:             </div>
 652:           </div>
 653:           {phase === 'loading' ? <div className="space-y-2 p-2">{[0, 1, 2, 3, 4, 5].map((i) => <div key={i} className="flex items-center gap-3 h-11" style={{ paddingInlineStart: (i % 3) * 26 }}><Skel w={32} h={32} r={10} /><Skel w={`${40 - (i % 3) * 8}%`} h={10} /></div>)}</div>
 654:             : phase === 'error' ? <ErrorState onRetry={retry} />
 655:             : phase === 'empty' ? <EmptyState icon="tree" title="لا توجد أقسام بعد" body="ابدأ بقسم رئيسي، وبعدها أضف أقسام فرعية لحد ٣ مستويات." action={<button className="btn btn-ink" onClick={() => setForm({ parent: null })}><Icon name="plus" size={15} />قسم رئيسي</button>} />
 656:             : (
 657:               <div className="space-y-0.5" onDragOver={(e) => e.preventDefault()}>
 658:                 {tree.map((n) => <Node key={n.id} n={n} depth={1} />)}
 659:                 {drag != null && (
 660:                   <div onDragOver={(e) => { e.preventDefault(); setOver('root'); }} onDrop={(e) => { e.preventDefault(); doMove(drag, null); setDrag(null); setOver(null); }}
 661:                     className={cx('pop mt-2 h-12 rounded-[14px] border-2 border-dashed flex items-center justify-center text-[12px] font-semibold', over === 'root' ? 'border-[var(--accent)] t-acc bg-[var(--accent-soft)]' : 'border-[var(--border-field)] t-3')}>
 662:                     أفلت هنا لجعله قسمًا رئيسيًا
 663:                   </div>
 664:                 )}
 665:               </div>
 666:             )}
 667:           <div className="flex items-center gap-4 mt-4 pt-3 px-1 v-border-t text-[11px] t-3">
 668:             <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded ring-2 ring-[var(--accent)]" />إفلات مسموح</span>
 669:             <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded ring-2 ring-[var(--badge-red-text)]" />إفلات غير مسموح</span>
 670:             <span className="flex items-center gap-1.5"><span className="w-4 h-4 rounded-full v-well text-[9px] font-bold flex items-center justify-center">2</span>رقم المستوى</span>
 671:           </div>
 672:         </div>
 673: 
 674:         {/* Detail / move-to panel */}
 675:         <div className="space-y-4 lg:sticky lg:top-5 stagger s3">
 676:           {selected ? (
 677:             <div className="v-card overflow-hidden">
 678:               <div className="h-24 relative" style={{ background: (tree.find((t) => t.id === sel || isDescendant(t, sel)) || {}).img || IMG[0] }}>
 679:                 <span className="absolute bottom-3 start-4 text-[10.5px] font-semibold px-2 py-0.5 rounded-full bg-white/90 text-[#18151c]">المستوى {selected.depth}</span>
 680:               </div>
 681:               <div className="p-5">
 682:                 <div className="flex items-start justify-between gap-2">
 683:                   <div><div className="font-display text-[17px] font-semibold t-1">{selected.node.ar}</div><div className="text-[12px] t-3 ltr inline-block">{selected.node.en} · /{selected.node.slug}</div></div>
 684:                   <StatusBadge s={selected.node.status} />
 685:                 </div>
 686:                 <div className="text-[11.5px] t-3 mt-3 flex items-center gap-1 flex-wrap">{flat.find((f) => f.id === sel).path.map((p, i, a) => <React.Fragment key={i}><span className={i === a.length - 1 ? 't-1 font-semibold' : ''}>{p}</span>{i < a.length - 1 && <Icon name="chevLeft" size={11} />}</React.Fragment>)}</div>
 687:                 <div className="grid grid-cols-2 gap-2.5 mt-4">
 688:                   <div className="v-subcard p-3"><div className="text-[11px] t-3">أقسام فرعية</div><div className="font-display text-[20px] font-bold t-1 num">{(selected.node.children || []).length}</div></div>
 689:                   <div className="v-subcard p-3"><div className="text-[11px] t-3">منتجات</div><div className="font-display text-[20px] font-bold t-1 num">{sumProducts(selected.node)}</div></div>
 690:                 </div>
 691:                 {canManage && <>
 692:                   <div className="mt-5"><Field label="نقل إلى" hint="بديل للسحب — الأقسام اللي تتجاوز الحد أو تقع داخل نفس الفرع غير متاحة.">
 693:                     <SearchSelect value={selected.parent ? selected.parent.id : '__root'} clearable={false} asyncSim={false}
 694:                       onChange={(pid) => doMove(sel, pid === '__root' ? null : pid)}
 695:                       options={[{ value: '__root', label: 'بدون أب (قسم رئيسي)', depth: 0 }, ...flat.filter((f) => f.depth < MAX_DEPTH - 1 + 1).map((f) => {
 696:                         const c = canDropInto(sel, f.id);
 697:                         return { value: f.id, label: f.ar, depth: f.depth, disabled: !c.ok, note: !c.ok ? (f.id === sel ? 'نفسه' : c.why.includes('الحد') ? 'يتجاوز الحد' : 'فرعي منه') : null };
 698:                       })]} />
 699:                   </Field></div>
 700:                   <div className="flex items-center gap-2 mt-4">
 701:                     <button className="btn btn-soft flex-1" onClick={() => setForm(selected.node)}><Icon name="edit" size={14} />تعديل</button>
 702:                     <button className="btn btn-outline flex-1" onClick={() => setDisable(selected.node)}>{selected.node.status === 'active' ? 'تعطيل' : 'تفعيل'}</button>
 703:                   </div>
 704:                 </>}
 705:               </div>
 706:             </div>
 707:           ) : <div className="v-card"><EmptyState compact icon="tree" title="اختر قسمًا" body="لعرض تفاصيله ونقله." /></div>}
 708:         </div>
 709:       </div>
 710: 
 711:       {dirty && <StickyBar dirty note="ترتيب الأقسام اتغيّر — التغييرات مش هتتبعت قبل الحفظ">
 712:         <button className="btn btn-ghost" onClick={() => setTree(saved)}>إلغاء التغييرات</button>
 713:         <button className="btn btn-ink" onClick={() => { setSaved(tree); vtoast('تم حفظ الترتيب'); }}>حفظ الترتيب</button>
 714:       </StickyBar>}
 715: 
 716:       <CategoryForm open={!!form} value={form} tree={tree} onClose={() => setForm(null)} />
 717:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} danger title={`حذف قسم «${del && del.ar}»؟`} message="سيتم حذف القسم نهائيًا." confirmLabel="حذف القسم"
 718:         serverError={del && ((del.children || []).length || sumProducts(del)) ? { title: 'لا يمكن حذف هذا القسم', body: 'القسم مرتبط بيانات لازم تتنقل الأول:', items: [(del.children || []).length && `${del.children.length} أقسام فرعية`, sumProducts(del) && `${sumProducts(del)} منتج مرتبط`].filter(Boolean) } : null} />
 719:       <ConfirmDialog open={!!disable} onClose={() => setDisable(null)} title={disable && disable.status === 'active' ? `تعطيل «${disable.ar}»؟` : `تفعيل «${disable && disable.ar}»؟`}
 720:         message={disable && disable.status === 'active' ? 'القسم المعطل وأقسامه الفرعية مش هيظهروا في المتجر.' : 'سيظهر القسم في المتجر.'} icon="ban" confirmLabel={disable && disable.status === 'active' ? 'تعطيل' : 'تفعيل'}
 721:         serverError={disable && disable.status === 'active' && sumProducts(disable) ? { title: 'تعذّر تعطيل القسم', body: `يوجد منتجات منشورة تحت هذا القسم أو أقسامه الفرعية. حوّلها لمسودة أو انقلها لقسم آخر أولًا.`, items: ['كنبة زاوية «ميلانو» — منشور', 'كنبة سرير «فليكس» — منشور', `+ ${Math.max(0, sumProducts(disable) - 2)} منتج آخر`] } : null} />
 722:     </div>
 723:   );
 724: }
