 833: /* ====================== PRODUCTS LIST ====================== */
 834: function ProductsPage() {
 835:   const { user } = useApp();
 836:   const [q, setQ] = useQueryState({ page: 1, per_page: 10, search: '', category: '', sub: '1', brand: '', status: '', channel: '', featured: '', sort: 'newest' });
 837:   const [phase, retry] = useLoad([q.page, q.per_page, q.search, q.category, q.sub, q.brand, q.status, q.channel, q.featured, q.sort]);
 838:   if (!user.can('products.view')) return <Forbidden perm="products.view" />;
 839:   const flat = flattenCats(CATEGORIES);
 840:   const catNode = q.category && flat.find((f) => String(f.id) === String(q.category));
 841:   let rows = PRODUCTS.filter((p) =>
 842:     (!q.search || (p.ar + p.en + p.code).toLowerCase().includes(q.search.toLowerCase())) &&
 843:     (!q.status || p.status === q.status) && (!q.channel || p.channel === q.channel) &&
 844:     (!q.brand || p.brand === (BRANDS.find((b) => String(b.id) === String(q.brand)) || {}).ar) &&
 845:     (!q.featured || p.featured) &&
 846:     (!catNode || p.cat === catNode.ar || (q.sub === '1' && p.catPath.includes(catNode.ar))));
 847:   if (q.sort === 'oldest') rows = [...rows].reverse();
 848:   if (q.sort === 'name') rows = [...rows].sort((a, b) => a.ar.localeCompare(b.ar, 'ar'));
 849:   const res = fakeQuery(rows, { page: +q.page, per_page: +q.per_page });
 850:   const activeFilters = ['category', 'brand', 'status', 'channel', 'featured'].filter((k) => q[k]).length + (q.search ? 1 : 0);
 851:   const counts = { all: PRODUCTS.length, published: PRODUCTS.filter((p) => p.status === 'published').length, draft: PRODUCTS.filter((p) => p.status === 'draft').length, archived: PRODUCTS.filter((p) => p.status === 'archived').length };
 852:   return (
 853:     <div className="space-y-5">
 854:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'المنتجات' }]} title="المنتجات" subtitle="المنتج بيتعمل مسودة الأول، بعدها الصور، وبعدها النشر."
 855:         actions={user.can('products.create') && <button className="btn btn-ink" onClick={() => nav('/products/new')}><Icon name="plus" size={15} />منتج جديد</button>} />
 856: 
 857:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stagger s2">
 858:         {[['', 'كل المنتجات', counts.all, 'box'], ['published', 'منشور', counts.published, 'globe'], ['draft', 'مسودة', counts.draft, 'edit'], ['archived', 'مؤرشف', counts.archived, 'folder']].map(([k, l, n, ic], i) => {
 859:           const on = q.status === k;
 860:           return (
 861:             <button key={k} onClick={() => setQ({ status: k, page: 1 })} className={cx('rounded-[22px] p-5 text-start transition', on ? 'v-orange shadow-sm' : 'v-card hover:shadow-sm')}>
 862:               <div className={cx('flex items-center justify-between text-[12.5px] font-medium', on ? 'text-white/90' : 't-2')}>{l}<span className={cx('w-7 h-7 rounded-full flex items-center justify-center', on ? 'bg-white/15' : 'v-well')}><Icon name={ic} size={14} /></span></div>
 863:               <div className={cx('font-display text-[32px] font-bold mt-3 num', !on && 't-1')}>{n}</div>
 864:               <div className={cx('mt-2 h-1.5 rounded-full overflow-hidden', on ? 'bg-white/20' : 'hatched-track')}><div className={cx('h-full rounded-full', on ? 'bg-white' : 'hatched-acc')} style={{ width: `${(n / counts.all) * 100}%` }} /></div>
 865:             </button>
 866:           );
 867:         })}
 868:       </div>
 869: 
 870:       <div className="stagger s3">
 871:         <DataTable state={phase} onRetry={retry} rows={res.data} meta={res.meta} filtered={activeFilters > 0}
 872:           onPage={(p) => setQ({ page: p })} onPerPage={(n) => setQ({ per_page: n, page: 1 })} onRowClick={(r) => nav('/products/' + r.id)}
 873:           empty={activeFilters > 0 ? <EmptyState icon="search" title="لا منتجات مطابقة" body="البحث بيشمل الاسم والكود وSKU والباركود. جرّب كلمات أقل أو امسح الفلاتر." action={<button className="btn btn-soft" onClick={() => setQ({ search: '', category: '', brand: '', status: '', channel: '', featured: '', page: 1 })}>مسح كل الفلاتر</button>} />
 874:             : <EmptyState icon="box" title="لا توجد منتجات بعد" body="ابدأ بأول منتج كمسودة — تقدر تضيف الصور وتنشره بعدين." action={<button className="btn btn-ink" onClick={() => nav('/products/new')}><Icon name="plus" size={15} />منتج جديد</button>} />}
 875:           toolbar={
 876:             <div className="space-y-3">
 877:               <div className="flex flex-wrap items-center gap-2">
 878:                 <SearchBox value={q.search} onChange={(v) => setQ({ search: v, page: 1 })} placeholder="الاسم، الكود، SKU أو الباركود…" width={320} />
 879:                 <div className="w-[230px]"><SearchSelect value={q.category ? +q.category : null} onChange={(v) => setQ({ category: v, page: 1 })} placeholder="كل الأقسام" options={flat.map((f) => ({ value: f.id, label: f.ar, depth: f.depth }))} /></div>
 880:                 {q.category && <label className="h-10 px-3.5 rounded-full v-subcard !rounded-full flex items-center gap-2 text-[12px] font-medium t-1 cursor-pointer" onClick={() => setQ({ sub: q.sub === '1' ? '0' : '1', page: 1 })}><Check on={q.sub === '1'} />تضمين الأقسام الفرعية</label>}
 881:                 <FilterMenu label="البراند" value={q.brand ? +q.brand : null} onChange={(v) => setQ({ brand: v, page: 1 })} options={BRANDS.map((b) => ({ value: b.id, label: b.ar }))} />
 882:                 <FilterMenu label="القناة" value={q.channel || null} onChange={(v) => setQ({ channel: v, page: 1 })} options={[{ value: 'retail', label: 'تجزئة' }, { value: 'wholesale', label: 'جملة' }, { value: 'both', label: 'تجزئة + جملة' }]} />
 883:                 <button onClick={() => setQ({ featured: q.featured ? '' : '1', page: 1 })} className={cx('h-10 px-3.5 rounded-full inline-flex items-center gap-2 text-[12.5px] font-medium border transition', q.featured ? 'bg-ink border-transparent' : 'btn-outline')}><Icon name="star" size={14} />مميز</button>
 884:                 <div className="ms-auto flex items-center gap-2">
 885:                   <span className="text-[12px] t-3">ترتيب</span>
 886:                   <Seg value={q.sort} onChange={(v) => setQ({ sort: v, page: 1 })} options={[{ value: 'newest', label: 'الأحدث' }, { value: 'oldest', label: 'الأقدم' }, { value: 'name', label: 'الاسم' }]} />
 887:                 </div>
 888:               </div>
 889:               {activeFilters > 0 && (
 890:                 <div className="flex items-center gap-2 text-[12px] pop">
 891:                   <span className="t-3"><span className="num font-semibold t-1">{res.meta.total}</span> نتيجة ·</span>
 892:                   <button className="font-semibold t-acc" onClick={() => setQ({ search: '', category: '', brand: '', status: '', channel: '', featured: '', page: 1 })}>مسح الفلاتر ({activeFilters})</button>
 893:                   <span className="t-3 ms-auto hidden md:flex items-center gap-1"><Icon name="link" size={12} />الفلاتر محفوظة في الرابط</span>
 894:                 </div>
 895:               )}
 896:             </div>
 897:           }
 898:           columns={[
 899:             { key: 'p', label: 'المنتج', render: (r) => (
 900:               <div className="flex items-center gap-3 min-w-[240px]">
 901:                 <span className="w-12 h-12 rounded-[14px] shrink-0 relative" style={{ background: r.img }}>{r.featured && <span className="absolute -top-1 -end-1 w-5 h-5 rounded-full bg-acc flex items-center justify-center" style={{ boxShadow: '0 0 0 2px var(--bg-card)' }}><Icon name="star" size={10} sw={2.5} /></span>}</span>
 902:                 <div className="min-w-0"><div className="font-semibold t-1 truncate">{r.ar}</div><div className="text-[11px] t-3 ltr inline-block">{r.code}</div></div>
 903:               </div>), skel: () => <div className="flex items-center gap-3"><Skel w={48} h={48} r={14} /><div className="space-y-1.5 flex-1"><Skel w="70%" h={10} /><Skel w="40%" h={8} /></div></div> },
 904:             { key: 'cat', label: 'القسم / البراند', render: (r) => <div><div className="t-1 text-[12.5px]">{r.cat}</div><div className="text-[11px] t-3">{r.brand}</div></div> },
 905:             { key: 'status', label: 'الحالة', render: (r) => <StatusBadge s={r.status} /> },
