1156: // Fake server: paginate + filter, returning {data, meta, links}
1157: function fakeQuery(all, { page = 1, per_page = 10 }) {
1158:   const total = all.length; const last = Math.max(1, Math.ceil(total / per_page));
1159:   const p = Math.min(page, last); const start = (p - 1) * per_page;
1160:   return {
1161:     data: all.slice(start, start + per_page),
1162:     meta: { current_page: p, last_page: last, per_page, total, from: total ? start + 1 : 0, to: Math.min(start + per_page, total) },
1163:     links: { first: '?page=1', last: `?page=${last}`, prev: p > 1 ? `?page=${p - 1}` : null, next: p < last ? `?page=${p + 1}` : null },
1164:   };
1165: }
