1241: function Icon({ name, size = 16, className = '', style, sw = 1.9 }) {
1242:   return (
1243:     <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
1244:       strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round" className={'shrink-0 ' + className} style={style} aria-hidden="true">
1245:       {ICON_PATHS[name] || ICON_PATHS.info}
1246:     </svg>
1247:   );
1248: }
