1278: function ProductForm({ id }) {
1279:   const { user, publishScenario } = useApp();
1280:   const isNew = id === 'new';
1281:   const [p, setP] = useState(() => isNew ? blankProduct() : (seedProduct(id) || blankProduct()));
1282:   const [saved, setSaved] = useState(JSON.stringify(p));
1283:   const [tab, setTabQ] = useQueryState({ tab: 'basic' });
1284:   const [errs, setErrs] = useState({ basic: {}, variants: {} });
1285:   const [summary, setSummary] = useState(null);
1286:   const [flow, setFlow] = useState(null); // {steps:[{k,label,state}], done}
1287:   const [blockModal, setBlockModal] = useState(null);
1288:   const [leave, setLeave] = useState(false);
1289:   const canCost = user.can('products.view_cost');
1290:   const canPublish = user.can('products.publish');
1291:   const dirty = JSON.stringify(p) !== saved;
1292:   useUnsavedGuard(dirty);
1293:   const setBasic = (k, val) => setP({ ...p, basic: { ...p.basic, [k]: val } });
1294:   const B = p.basic;
1295:   const flat = flattenCats(CATEGORIES);
1296:   const catNode = flat.find((f) => f.id === B.category);
1297:   const vErrs = validateVariants(p.rows, B.channel, p.mode);
1298: 
1299:   // Readiness
1300:   const catChain = catNode ? catNode.path.map((name) => flat.find((f) => f.ar === name)) : [];
1301:   const inactiveAncestor = catChain.find((c) => c && c.status !== 'active');
1302:   const activeRows = p.rows.filter((r) => r.status === 'active' && r.available);
1303:   const needRetail = B.channel !== 'wholesale', needWh = B.channel !== 'retail';
1304:   const missingPrice = activeRows.filter((r) => (needRetail && !r.retail) || (needWh && !r.wholesale));
1305:   const imgCount = p.media.general.length + Object.values(p.media.byVariant).flat().length;
1306:   const ready = [
1307:     { k: 'cat', ok: !!catNode && !inactiveAncestor, label: 'القسم وكل الأقسام الأب نشطين', detail: !catNode ? 'لم يتم اختيار قسم' : inactiveAncestor ? `القسم «${inactiveAncestor.ar}» غير نشط` : catNode.path.join(' › '), tab: 'basic' },
1308:     { k: 'var', ok: activeRows.length > 0, label: 'متغير نشط واحد على الأقل', detail: `${activeRows.length} متغير نشط من ${p.rows.length}`, tab: 'variants' },
1309:     { k: 'price', ok: activeRows.length > 0 && missingPrice.length === 0, label: 'أسعار المتغيرات النشطة مكتملة حسب قناة البيع', detail: missingPrice.length ? `${missingPrice.length} متغير ناقصه ${needRetail && needWh ? 'سعر تجزئة أو جملة' : needRetail ? 'سعر التجزئة' : 'سعر الجملة'}` : `القناة: ${CHANNEL_LABEL[B.channel]}`, tab: 'variants' },
1310:     { k: 'img', ok: imgCount > 0, label: 'صورة واحدة على الأقل', detail: `${imgCount} صورة`, tab: 'media' },
1311:     { k: 'perm', ok: canPublish, label: 'صلاحية نشر المنتجات', detail: canPublish ? 'متاحة لدورك' : 'دورك لا يحتوي products.publish', tab: null },
1312:   ];
1313:   const readyCount = ready.filter((r) => r.ok).length;
1314: 
1315:   const tabState = (t) => {
1316:     if (t === 'basic') return Object.keys(errs.basic).length ? 'error' : (B.ar && B.en && B.category ? 'done' : null);
1317:     if (t === 'variants') return Object.keys(vErrs).length && (errs.variantsShown) ? 'error' : (activeRows.length && !missingPrice.length ? 'done' : null);
1318:     if (t === 'media') return imgCount ? 'done' : null;
1319:     if (t === 'review') return readyCount === ready.length ? 'done' : null;
1320:   };
1321: 
1322:   const validateBasic = () => {
1323:     const e = {};
1324:     if (!B.ar) e.ar = 'الاسم العربي مطلوب';
1325:     if (!B.en) e.en = 'الاسم الإنجليزي مطلوب';
1326:     if (!B.category) e.category = 'اختر القسم';
1327:     if (!B.channel) e.channel = 'اختر قناة البيع';
1328:     return e;
1329:   };
1330: 
1331:   const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
1332:   const run = async (publish) => {
1333:     const be = validateBasic();
1334:     const ve = validateVariants(p.rows, B.channel, p.mode);
1335:     // Drafts tolerate missing prices; only structural errors block
1336:     const structural = Object.fromEntries(Object.entries(ve).map(([k, e]) => [k, Object.fromEntries(Object.entries(e).filter(([f]) => publish || !['retail', 'wholesale'].includes(f)))]).filter(([, e]) => Object.keys(e).length));
1337:     setErrs({ basic: be, variants: structural, variantsShown: true });
1338:     if (Object.keys(be).length || Object.keys(structural).length) {
1339:       const items = [
1340:         ...Object.values(be).map((t) => ({ text: t, tab: 'البيانات الأساسية', go: 'basic' })),
1341:         ...Object.entries(structural).flatMap(([rid, e]) => { const i = p.rows.findIndex((r) => r._id === rid); return Object.entries(e).map(([f, t]) => ({ text: `variants.${i}.${f === 'dup' ? 'combination' : f === 'retail' ? 'retail_price' : f === 'wholesale' ? 'wholesale_price' : f} — ${t}`, tab: 'المتغيرات', go: 'variants' })); }),
1342:       ];
1343:       setSummary({ title: 'تعذّر الحفظ — راجع الحقول التالية', subtitle: 'الخادم رجّع 422. كل خطأ مربوط بالحقل بتاعه في التبويب.', items });
1344:       setTabQ({ tab: items[0].go });
1345:       return;
1346:     }
1347:     setSummary(null);
1348:     const steps = [
1349:       { k: 'save', label: p.status ? 'تحديث المسودة والمتغيرات' : 'حفظ المسودة والمتغيرات', state: 'run' },
1350:       { k: 'upload', label: `رفع الصور (${p.media.general.filter((f) => f.status !== 'done').length + Object.values(p.media.byVariant).flat().filter((f) => f.status !== 'done').length + (p.media.video && p.media.video.status !== 'done' ? 1 : 0)} ملف)`, state: 'wait' },
1351:       ...(publish ? [{ k: 'publish', label: 'تحديث الحالة إلى منشور', state: 'wait' }] : []),
1352:     ];
1353:     setFlow({ steps: [...steps], publish });
1354:     const mark = (k, state, extra) => setFlow((f) => ({ ...f, steps: f.steps.map((s) => s.k === k ? { ...s, state, ...extra } : s) }));
1355:     await sleep(900);
1356:     mark('save', 'done');
1357:     const code = p.code || 'PRD-000' + (111 + Math.floor(Math.random() * 80));
1358:     let next = { ...p, code, status: p.status || 'draft', rows: p.rows.map((r, i) => ({ ...r, sku: r.sku || `${(B.en || 'PRD').slice(0, 3).toUpperCase()}-${String(i + 1).padStart(3, '0')}`, barcode: r.barcode || `6221${String(Date.now()).slice(-8)}${i}` })) };
1359:     // Upload
1360:     mark('upload', 'run');
1361:     const pending = next.media.general.filter((f) => f.status !== 'done');
1362:     for (let pct = 0; pct <= 100; pct += 20) {
1363:       await sleep(160);
1364:       next = { ...next, media: { ...next.media, general: next.media.general.map((f, i) => f.status === 'done' ? f : (publishScenario === 'upload_fail' && i === next.media.general.length - 1 && pct >= 60) ? { ...f, status: 'failed', progress: 60, error: 'انقطع الاتصال أثناء الرفع' } : { ...f, status: pct >= 100 ? 'done' : 'uploading', progress: pct }) } };
1365:       setP(next);
1366:     }
1367:     const failed = next.media.general.filter((f) => f.status === 'failed').length;
1368:     if (failed) {
1369:       mark('upload', 'fail', { note: `${failed} صورة فشلت — المسودة محفوظة` });
1370:       if (publish) mark('publish', 'skip');
1371:       setSaved(JSON.stringify(next)); setFlow((f) => ({ ...f, done: 'upload_fail', code }));
1372:       if (isNew) history.replaceState(null, '', '#/products/101?tab=media');
1373:       return;
1374:     }
1375:     mark('upload', 'done');
1376:     if (publish) {
1377:       mark('publish', 'run'); await sleep(800);
1378:       if (publishScenario === 'publish_blocked') {
1379:         mark('publish', 'fail', { note: 'errors.status' });
1380:         setSaved(JSON.stringify(next)); setFlow((f) => ({ ...f, done: 'blocked', code }));
1381:         return;
1382:       }
1383:       next = { ...next, status: 'published' }; mark('publish', 'done');
1384:     }
1385:     setP(next); setSaved(JSON.stringify(next)); setFlow((f) => ({ ...f, done: 'ok', code }));
1386:   };
1387: 
1388:   const onDeactivateLast = () => {
