1390:     return false;
1391:   };
1392: 
1393:   const tabs = [
1394:     { value: 'basic', label: 'البيانات الأساسية', num: 1, state: tabState('basic') },
1395:     { value: 'variants', label: 'المتغيرات والأسعار', num: 2, state: tabState('variants') },
1396:     { value: 'media', label: 'الصور والفيديو', num: 3, state: tabState('media') },
