1403:         title={isNew && !p.code ? 'منتج جديد' : B.ar || 'بدون اسم'}
1404:         badge={<>{p.status ? <StatusBadge s={p.status} /> : <Badge>لم يُحفظ بعد</Badge>}{p.code && <span className="ltr text-[12px] font-semibold px-2.5 py-1 rounded-full v-pill t-2">{p.code}</span>}</>}
1405:         actions={<button className="btn btn-soft" onClick={() => dirty ? setLeave(true) : nav('/products')}><Icon name="arrowRight" size={14} />المنتجات</button>} />
