1549: /* ---------- Tab C: Media ---------- */
1550: function MediaTab({ media, setMedia, axes, mode, saved }) {
1551:   const [dragIdx, setDragIdx] = useState(null);
1552:   const [scope, setScope] = useState('general');
1553:   const [sizeErr, setSizeErr] = useState(null);
1554:   const addFiles = (n = 3, target = 'general') => {
1555:     const names = ['living-room-01.jpg', 'angle-left.png', 'fabric-closeup.webp', 'lifestyle.jpg', 'top-view.jpg'];
1556:     const fresh = Array.from({ length: n }).map((_, i) => ({ id: Math.random().toString(36).slice(2), name: names[(media.general.length + i) % names.length], size: (1 + Math.random() * 3).toFixed(1) + 'MB', status: saved ? 'uploading' : 'queued', progress: 0, bg: IMG[(media.general.length + i + 2) % IMG.length] }));
1557:     if (target === 'general') {
1558:       if (media.general.length + n > 10) { setSizeErr('الحد الأقصى ١٠ صور في طلب الرفع الواحد'); return; }
1559:       const next = { ...media, general: [...media.general, ...fresh] };
1560:       setMedia(next);
1561:       if (saved) simulateUpload(next, fresh.map((f) => f.id));
1562:     } else {
1563:       setMedia({ ...media, byVariant: { ...media.byVariant, [target]: [...(media.byVariant[target] || []), ...fresh.slice(0, 1).map((f) => ({ ...f, status: saved ? 'done' : 'queued' }))] } });
1564:     }
1565:   };
1566:   const simulateUpload = (start, ids) => {
1567:     let pct = 0; let cur = start;
1568:     const t = setInterval(() => {
1569:       pct += 20;
1570:       cur = { ...cur, general: cur.general.map((f) => ids.includes(f.id) ? { ...f, progress: pct, status: pct >= 100 ? (f.name.includes('webp') ? 'failed' : 'done') : 'uploading', error: f.name.includes('webp') && pct >= 100 ? 'الأبعاد تتجاوز 6000×6000' : null } : f) };
1571:       setMedia(cur);
1572:       if (pct >= 100) clearInterval(t);
1573:     }, 220);
1574:   };
1575:   const reorder = (to) => {
1576:     if (dragIdx == null || dragIdx === to) return;
1577:     const g = [...media.general]; const [m] = g.splice(dragIdx, 1); g.splice(to, 0, m);
1578:     setMedia({ ...media, general: g }); setDragIdx(to);
1579:   };
1580:   const retry = (id) => {
1581:     const next = { ...media, general: media.general.map((f) => f.id === id ? { ...f, status: 'uploading', progress: 0, error: null, name: f.name.replace('webp', 'jpg') } : f) };
1582:     setMedia(next); simulateUpload(next, [id]);
1583:   };
1584:   const failed = media.general.filter((f) => f.status === 'failed').length;
1585:   const queued = media.general.filter((f) => f.status === 'queued').length;
1586:   return (
1587:     <div className="grid lg:grid-cols-[1fr_340px] gap-5 items-start">
1588:       <div className="space-y-5">
1589:         {!saved && <Banner tone="blue" icon="info" title="الصور هتترفع بعد حفظ المسودة">تقدر تختار الملفات دلوقتي. الرفع الفعلي بيبدأ تلقائيًا بعد ما المنتج والمتغيرات يتحفظوا.</Banner>}
1590:         {failed > 0 && <Banner tone="red" icon="alertCircle" title={`${failed} صورة فشل رفعها`} action={<button className="btn btn-sm btn-ink" onClick={() => media.general.filter((f) => f.status === 'failed').forEach((f) => retry(f.id))}><Icon name="refresh" size={13} />إعادة رفع الكل</button>}>المسودة محفوظة. أعد رفع الصور الفاشلة بدون إنشاء منتج جديد.</Banner>}
1591:         <SectionCard title="صور المنتج" subtitle="اسحب لتغيير الترتيب. الصورة الأولى هي الرئيسية في المتجر." aside={<span className="text-[12px] t-3 num">{media.general.length} / 10</span>}>
1592:           {sizeErr && <Banner tone="red" icon="alertCircle" className="mb-4 pop" onClose={() => setSizeErr(null)}>{sizeErr}</Banner>}
1593:           <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-3">
1594:             {media.general.map((f, i) => (
1595:               <FileTile key={f.id} file={f} index={i + 1} primary={i === 0 && f.status !== 'failed'} draggable
1596:                 onDragStart={() => setDragIdx(i)} onDragOver={(e) => { e.preventDefault(); reorder(i); }} onDrop={() => setDragIdx(null)}
1597:                 onRemove={() => setMedia({ ...media, general: media.general.filter((x) => x.id !== f.id) })} onRetry={() => retry(f.id)} />
1598:             ))}
1599:             {media.general.length < 10 && (
1600:               <button onClick={() => addFiles(2)} className="dropzone aspect-[4/3] sm:aspect-auto min-h-[150px] flex flex-col items-center justify-center gap-2 t-2">
1601:                 <span className="w-10 h-10 rounded-full b-acc flex items-center justify-center"><Icon name="plus" size={18} /></span>
1602:                 <span className="text-[12.5px] font-semibold t-1">إضافة صور</span>
1603:               </button>
1604:             )}
1605:           </div>
1606:           {media.general.length === 0 && <div className="mt-3"><DropZone title="اسحب صور المنتج هنا" rules={['JPG · PNG · WebP', 'حتى 5MB للصورة', 'حتى 6000×6000', 'حتى ١٠ صور في المرة']} onPick={() => addFiles(3)} /></div>}
1607:           {media.general.length > 0 && <div className="flex flex-wrap gap-1.5 mt-4">{['JPG · PNG · WebP', 'حتى 5MB للصورة', 'حتى 6000×6000', 'حتى ١٠ صور في الطلب'].map((r) => <span key={r} className="text-[10.5px] font-medium px-2 py-0.5 rounded-full v-well">{r}</span>)}{queued > 0 && <Badge tone="amber" className="ms-auto">{queued} بانتظار الحفظ</Badge>}</div>}
1608:         </SectionCard>
1609: 
1610:         {mode === 'matrix' && axes.colors.length > 0 && (
1611:           <SectionCard title="صور حسب اللون" subtitle="بتظهر لما العميل يختار اللون ده. اختيارية.">
1612:             <div className="space-y-3">
1613:               {axes.colors.map((c) => {
1614:                 const list = media.byVariant[c.en] || [];
1615:                 return (
1616:                   <div key={c.en} className="v-subcard p-3.5 flex items-center gap-4">
1617:                     <div className="flex items-center gap-2.5 w-[150px] shrink-0"><Swatch c={c.hex} size={28} /><div><div className="text-[12.5px] font-semibold t-1">{c.ar}</div><div className="text-[10.5px] t-3 ltr">{c.en}</div></div></div>
1618:                     <div className="flex-1 flex items-center gap-2 overflow-x-auto">
1619:                       {list.map((f) => <div key={f.id} className="w-16 shrink-0"><FileTile compact file={f} onRemove={() => setMedia({ ...media, byVariant: { ...media.byVariant, [c.en]: list.filter((x) => x.id !== f.id) } })} /></div>)}
1620:                       <button onClick={() => addFiles(1, c.en)} className="dropzone w-16 h-16 shrink-0 flex items-center justify-center t-3"><Icon name="plus" size={16} /></button>
1621:                     </div>
1622:                   </div>
1623:                 );
1624:               })}
1625:             </div>
1626:           </SectionCard>
1627:         )}
1628: 
1629:         <SectionCard title="فيديو المنتج" subtitle="فيديو واحد للمنتج كله — مش مرتبط بمتغير.">
1630:           {media.video ? (
1631:             <div className="flex items-center gap-4 v-subcard p-3.5">
1632:               <div className="w-28 aspect-video rounded-[12px] flex items-center justify-center" style={{ background: IMG[6], color: 'rgba(255,255,255,.7)' }}><Icon name="video" size={22} /></div>
1633:               <div className="flex-1"><div className="text-[12.5px] font-semibold t-1 ltr text-end">{media.video.name}</div><div className="text-[11px] t-3 num">{media.video.size}</div>
1634:                 {media.video.status === 'queued' && <Badge tone="amber" className="mt-1.5">بانتظار الحفظ</Badge>}</div>
1635:               <button className="icon-btn" onClick={() => setMedia({ ...media, video: null })}><Icon name="trash" size={15} /></button>
1636:             </div>
1637:           ) : <DropZone icon="video" title="اختر فيديو" rules={['MP4 · MOV', 'حتى 50MB', 'فيديو واحد فقط']} onPick={() => setMedia({ ...media, video: { name: 'milano-360.mp4', size: '38.2MB', status: saved ? 'done' : 'queued' } })} />}
1638:         </SectionCard>
1639:       </div>
1640: 
1641:       <div className="v-card p-5 lg:sticky lg:top-5">
1642:         <div className="text-[13px] font-semibold t-1 mb-1">معاينة ترتيب العرض</div>
1643:         <div className="text-[11.5px] t-3 mb-4">كده هتظهر في صفحة المنتج.</div>
1644:         <div className="rounded-[18px] aspect-square relative overflow-hidden" style={{ background: (media.general[0] && media.general[0].bg) || 'var(--bg-subcard)' }}>
1645:           {!media.general[0] && <div className="absolute inset-0 flex items-center justify-center t-3"><Icon name="image" size={30} /></div>}
1646:           {media.video && <span className="absolute bottom-3 end-3 h-7 px-2.5 rounded-full bg-black/55 text-white text-[11px] font-semibold flex items-center gap-1"><Icon name="video" size={12} />فيديو</span>}
1647:         </div>
1648:         <div className="grid grid-cols-5 gap-1.5 mt-2">
1649:           {media.general.slice(0, 5).map((f, i) => <div key={f.id} className={cx('aspect-square rounded-[10px] relative', i === 0 && 'ring-2 ring-[var(--accent)] ring-offset-2 ring-offset-[var(--bg-card)]')} style={{ background: f.bg, opacity: f.status === 'failed' ? .35 : 1 }} />)}
1650:           {Array.from({ length: Math.max(0, 5 - media.general.length) }).map((_, i) => <div key={i} className="aspect-square rounded-[10px] v-subcard" />)}
1651:         </div>
1652:       </div>
1653:     </div>
1654:   );
1655: }
