1657: /* ---------- Tab D: Review ---------- */
1658: function ReviewTab({ p, ready, canCost, canPublish, goto, catNode }) {
1659:   const B = p.basic;
1660:   const prices = p.rows.map((r) => +r.retail).filter(Boolean);
1661:   const okCount = ready.filter((r) => r.ok).length;
1662:   return (
1663:     <div className="grid lg:grid-cols-[1fr_380px] gap-5 items-start">
1664:       <div className="v-card p-6">
1665:         <div className="flex items-start justify-between gap-3">
1666:           <div><div className="font-display text-[17px] font-semibold t-1">قائمة الجاهزية للنشر</div><div className="text-[12.5px] t-2 mt-0.5">كل البنود لازم تكون مكتملة قبل النشر. الحفظ كمسودة متاح دائمًا.</div></div>
1667:           <div className="text-end"><div className="font-display text-[28px] font-bold t-1 num leading-none">{okCount}<span className="t-3 text-[16px]">/{ready.length}</span></div></div>
1668:         </div>
1669:         <div className="mt-5 space-y-2">
1670:           {ready.map((r) => (
1671:             <div key={r.k} className={cx('flex items-center gap-3.5 p-4 rounded-[16px]', r.ok ? 'v-subcard' : 'border border-dashed')} style={!r.ok ? { borderColor: 'var(--badge-red-text)', background: 'var(--badge-red-bg)' } : null}>
1672:               <span className={cx('w-9 h-9 rounded-full flex items-center justify-center shrink-0', r.ok ? 'b-green' : 'bg-[var(--bg-card)]')} style={!r.ok ? { color: 'var(--badge-red-text)' } : null}><Icon name={r.ok ? 'check' : r.k === 'perm' ? 'lock' : 'x'} size={16} sw={2.5} /></span>
1673:               <div className="flex-1 min-w-0"><div className="text-[13px] font-semibold t-1">{r.label}</div><div className="text-[11.5px] t-2 mt-0.5">{r.detail}</div></div>
1674:               {!r.ok && r.tab && <button className="btn btn-sm btn-outline" onClick={() => goto(r.tab)}>إصلاح<Icon name="chevLeft" size={13} /></button>}
1675:             </div>
1676:           ))}
1677:         </div>
1678:         <div className="mt-5 v-subcard p-4">
1679:           <div className="text-[12px] font-semibold t-2 mb-3">تسلسل التنفيذ عند النشر</div>
1680:           <div className="flex items-center gap-2 text-[12px]">
1681:             {['حفظ المسودة والمتغيرات', 'رفع الصور', 'تحديث الحالة إلى منشور'].map((s, i) => (
1682:               <React.Fragment key={s}>
1683:                 {i > 0 && <span className="flex-1 h-[2px] min-w-[16px] hatched-track rounded-full" />}
1684:                 <span className="flex items-center gap-2 shrink-0"><span className="w-6 h-6 rounded-full bg-ink text-[11px] font-bold flex items-center justify-center num">{i + 1}</span><span className="t-1 font-medium">{s}</span></span>
1685:               </React.Fragment>
1686:             ))}
1687:           </div>
1688:         </div>
1689:       </div>
1690: 
1691:       <div className="v-card overflow-hidden">
1692:         <div className="aspect-[4/3] relative" style={{ background: (p.media.general[0] && p.media.general[0].bg) || 'var(--bg-subcard)' }}>
1693:           {B.featured && <span className="absolute top-3 start-3 h-7 px-2.5 rounded-full bg-acc text-[11px] font-semibold flex items-center gap-1"><Icon name="star" size={11} sw={2.5} />مميز</span>}
1694:           <span className="absolute top-3 end-3">{p.status ? <StatusBadge s={p.status} /> : <Badge>جديد</Badge>}</span>
1695:         </div>
1696:         <div className="p-5">
1697:           <div className="text-[11.5px] t-3">{catNode ? catNode.path.join(' › ') : 'بدون قسم'}</div>
1698:           <div className="font-display text-[18px] font-semibold t-1 mt-1">{B.ar || 'بدون اسم'}</div>
1699:           <div className="text-[12px] t-3 ltr text-end">{B.en}</div>
1700:           <div className="font-display text-[22px] font-bold t-1 mt-3 num">{prices.length ? (Math.min(...prices) === Math.max(...prices) ? fmtMoney(prices[0]) : `${fmtMoney(Math.min(...prices))} – ${fmtMoney(Math.max(...prices))}`) : '—'} <span className="text-[12px] t-3 font-medium">ج.م</span></div>
1701:           {p.mode === 'matrix' && p.axes.colors.length > 0 && <div className="flex gap-1.5 mt-3">{p.axes.colors.map((c) => <Swatch key={c.en} c={c.hex} size={22} />)}</div>}
1702:           <div className="v-divide mt-4">
1703:             <KV k="قناة البيع" v={CHANNEL_LABEL[B.channel]} />
1704:             <KV k="المتغيرات" v={<span className="num">{p.rows.length}</span>} />
1705:             <KV k="الصور" v={<span className="num">{p.media.general.length}</span>} />
1706:             {canCost && prices.length > 0 && <KV k="متوسط الهامش" v={<span className="num" style={{ color: 'var(--badge-green-text)' }}>{Math.round(100 - (p.rows.reduce((a, r) => a + (+r.cost || 0), 0) / p.rows.reduce((a, r) => a + (+r.retail || 1), 0)) * 100)}%</span>} />}
1707:           </div>
1708:         </div>
1709:       </div>
1710:     </div>
1711:   );
1712: }
