1714: /* ---------- Publish flow modal ---------- */
1715: function PublishFlow({ flow, onClose, onRetryUpload, onGoto }) {
1716:   if (!flow) return null;
1717:   const icon = (s) => s === 'done' ? <span className="w-8 h-8 rounded-full b-green flex items-center justify-center"><Icon name="check" size={15} sw={2.6} /></span>
1718:     : s === 'run' ? <span className="w-8 h-8 rounded-full b-acc flex items-center justify-center"><Spinner size={15} /></span>
1719:     : s === 'fail' ? <span className="w-8 h-8 rounded-full b-red flex items-center justify-center"><Icon name="x" size={15} sw={2.6} /></span>
1720:     : s === 'skip' ? <span className="w-8 h-8 rounded-full v-well flex items-center justify-center"><Icon name="minus" size={15} /></span>
1721:     : <span className="w-8 h-8 rounded-full v-well flex items-center justify-center"><span className="w-2 h-2 rounded-full bg-current opacity-40" /></span>;
1722:   const d = flow.done;
1723:   return (
1724:     <Modal open onClose={d ? onClose : null} width={500}
1725:       title={!d ? (flow.publish ? 'جارٍ النشر…' : 'جارٍ الحفظ…') : d === 'ok' ? (flow.publish ? 'تم نشر المنتج' : 'تم حفظ المسودة') : d === 'upload_fail' ? 'المسودة اتحفظت، لكن بعض الصور فشلت' : 'المسودة اتحفظت، لكن النشر اترفض'}
1726:       subtitle={d === 'ok' ? <>كود المنتج <span className="ltr inline-block font-semibold t-1">{flow.code}</span></> : d === 'upload_fail' ? 'ما اتعملش منتج جديد. أعد رفع الصور الفاشلة من تبويب الصور.' : d === 'blocked' ? 'الخادم رفض تحديث الحالة. صلّح البنود دي وجرّب تاني.' : 'ما تقفلش الصفحة لحد ما تخلص الخطوات.'}
1727:       icon={!d ? 'send' : d === 'ok' ? 'checkCircle' : 'alert'} iconTone={!d ? 'acc' : d === 'ok' ? 'green' : 'amber'}>
1728:       <div className="v-subcard p-2">
1729:         {flow.steps.map((s, i) => (
1730:           <div key={s.k} className="flex items-center gap-3 p-2.5">
1731:             {icon(s.state)}
1732:             <div className="flex-1"><div className={cx('text-[13px] font-medium', s.state === 'wait' || s.state === 'skip' ? 't-3' : 't-1')}>{s.label}</div>{s.note && <div className="text-[11.5px] mt-0.5" style={{ color: s.state === 'fail' ? 'var(--badge-red-text)' : undefined }}>{s.note}</div>}</div>
1733:             <span className="text-[10.5px] t-3 num">{i + 1}/{flow.steps.length}</span>
1734:           </div>
1735:         ))}
1736:       </div>
1737:       {d === 'blocked' && (
1738:         <div className="mt-4 pop">
1739:           <div className="text-[11.5px] t-3 mb-2 ltr text-end">422 · errors.status</div>
1740:           <div className="space-y-1.5">
1741:             {[{ t: 'القسم الأب «غرف المعيشة» أصبح غير نشط', tab: 'basic', tl: 'البيانات الأساسية' }, { t: 'المتغير «بيج · 280×180» بدون سعر جملة', tab: 'variants', tl: 'المتغيرات' }].map((x) => (
