1995:                     <div className="mt-2.5 h-1.5 rounded-full overflow-hidden" style={{ background: 'color-mix(in oklab, currentColor 14%, transparent)' }}><div className="h-full rounded-full bg-current transition-all duration-1000" style={{ width: `${(lock / 60) * 100}%` }} /></div>
