2383: /* ---------------- Searchable Select ---------------- */
2384: function SearchSelect({ value, onChange, options = [], placeholder = 'اختر…', error, disabled, loading: forceLoading, emptyText, multi, clearable = true, renderOption, asyncSim = true, searchPlaceholder = 'ابحث…' }) {
2385:   const [open, setOpen] = useState(false);
2386:   const [q, setQ] = useState('');
2387:   const [loading, setLoading] = useState(false);
2388:   const [hi, setHi] = useState(0);
2389:   const ref = useRef(null);
2390:   useOutside(ref, () => setOpen(false), open);
2391:   useEffect(() => {
2392:     if (!open || !asyncSim) return;
2393:     setLoading(true);
2394:     const t = setTimeout(() => setLoading(false), q ? 420 : 300);
2395:     return () => clearTimeout(t);
2396:   }, [q, open]);
2397:   const isLoading = forceLoading || loading;
2398:   const list = options.filter((o) => !q || (o.label + ' ' + (o.sub || '')).toLowerCase().includes(q.toLowerCase()));
2399:   const selected = multi ? options.filter((o) => (value || []).includes(o.value)) : options.find((o) => o.value === value);
2400:   const pick = (o) => {
2401:     if (multi) {
2402:       const cur = value || [];
2403:       onChange(cur.includes(o.value) ? cur.filter((v) => v !== o.value) : [...cur, o.value]);
2404:     } else { onChange(o.value); setOpen(false); setQ(''); }
2405:   };
2406:   const onKey = (e) => {
2407:     if (e.key === 'ArrowDown') { e.preventDefault(); setHi((h) => Math.min(h + 1, list.length - 1)); }
2408:     if (e.key === 'ArrowUp') { e.preventDefault(); setHi((h) => Math.max(h - 1, 0)); }
2409:     if (e.key === 'Enter' && list[hi]) { e.preventDefault(); pick(list[hi]); }
2410:     if (e.key === 'Escape') setOpen(false);
2411:   };
2412:   return (
2413:     <div className="relative" ref={ref}>
2414:       <button type="button" disabled={disabled} onClick={() => setOpen(!open)}
2415:         className={cx('v-input flex items-center justify-between gap-2 text-start', open && 'is-focus', error && 'is-error', disabled && 'is-disabled', multi && selected.length && '!h-auto min-h-[42px] py-1.5')}>
2416:         <span className="flex-1 min-w-0 flex items-center gap-1.5 flex-wrap">
2417:           {multi ? (selected.length ? selected.map((s) => (
2418:             <span key={s.value} className="inline-flex items-center gap-1 ps-2.5 pe-1 h-7 rounded-full text-[12px] font-medium" style={{ background: 'var(--bg-card)', border: '1px solid var(--border-field)' }}>
2419:               {s.label}
2420:               <span role="button" onClick={(e) => { e.stopPropagation(); pick(s); }} className="w-5 h-5 rounded-full inline-flex items-center justify-center hover:bg-[var(--bg-subcard-hover)] t-3"><Icon name="x" size={11} /></span>
2421:             </span>
2422:           )) : <span className="t-3">{placeholder}</span>)
2423:             : selected ? <span className="truncate flex items-center gap-2">{selected.icon}{selected.label}{selected.sub && <span className="t-3 text-[11.5px]">· {selected.sub}</span>}</span>
2424:             : <span className="t-3">{placeholder}</span>}
2425:         </span>
2426:         {!multi && clearable && selected && !disabled && (
2427:           <span role="button" onClick={(e) => { e.stopPropagation(); onChange(null); }} className="w-6 h-6 rounded-full inline-flex items-center justify-center t-3 hover:bg-[var(--bg-subcard-hover)]"><Icon name="x" size={12} /></span>
2428:         )}
2429:         <Icon name="chevDown" size={14} className={cx('t-3 transition-transform', open && 'rotate-180')} />
2430:       </button>
2431:       {open && (
2432:         <div className="pop absolute z-40 mt-2 w-full min-w-[260px] v-card p-2" style={{ boxShadow: 'var(--shadow-pop)', borderRadius: 18 }}>
2433:           <div className="relative mb-1.5">
2434:             <Icon name="search" size={14} className="absolute top-1/2 -translate-y-1/2 start-3 t-3" />
2435:             <input autoFocus value={q} onChange={(e) => { setQ(e.target.value); setHi(0); }} onKeyDown={onKey} placeholder={searchPlaceholder}
2436:               className="w-full h-9 rounded-xl ps-9 pe-8 text-[12.5px] outline-none" style={{ background: 'var(--bg-subcard)', color: 'var(--text-primary)' }} />
2437:             {isLoading && <Spinner size={14} className="absolute top-1/2 -translate-y-1/2 end-3 t-acc" />}
2438:           </div>
2439:           <div className="max-h-[248px] overflow-y-auto">
2440:             {isLoading ? (
2441:               <div className="p-2 space-y-3">{[0, 1, 2].map((i) => <div key={i} className="flex items-center gap-2.5"><Skel w={22} h={22} r={8} /><Skel w={`${70 - i * 15}%`} h={10} /></div>)}</div>
2442:             ) : list.length === 0 ? (
2443:               <div className="py-6 px-3 text-center">
2444:                 <div className="w-10 h-10 rounded-full v-well mx-auto flex items-center justify-center mb-2"><Icon name="search" size={16} /></div>
2445:                 <div className="text-[12.5px] font-semibold t-1">{emptyText || 'لا توجد نتائج'}</div>
2446:                 {q && <div className="text-[11.5px] t-3 mt-0.5">لا شيء يطابق «{q}»</div>}
2447:               </div>
2448:             ) : list.map((o, i) => {
2449:               const sel = multi ? (value || []).includes(o.value) : o.value === value;
2450:               return (
2451:                 <button type="button" key={o.value} onMouseEnter={() => setHi(i)} onClick={() => !o.disabled && pick(o)} disabled={o.disabled}
2452:                   className={cx('w-full flex items-center gap-2.5 px-2.5 py-2 rounded-xl text-start text-[12.5px] transition', hi === i && 'bg-[var(--bg-subcard)]', o.disabled && 'opacity-40 cursor-not-allowed')}
2453:                   style={{ paddingInlineStart: o.depth ? 10 + o.depth * 16 : undefined }}>
2454:                   {multi && <Check on={sel} />}
2455:                   {o.icon}
2456:                   <span className="flex-1 min-w-0">
2457:                     <span className={cx('block truncate', sel ? 'font-semibold t-1' : 't-1')}>{o.label}</span>
2458:                     {o.sub && <span className="block text-[11px] t-3 truncate">{o.sub}</span>}
2459:                   </span>
2460:                   {o.note && <span className="text-[10.5px] t-3">{o.note}</span>}
2461:                   {!multi && sel && <Icon name="check" size={14} className="t-acc" sw={2.4} />}
2462:                 </button>
2463:               );
2464:             })}
2465:           </div>
2466:         </div>
2467:       )}
2468:     </div>
2469:   );
2470: }
