2630: /* ---------------- DataTable ---------------- */
2631: function DataTable({ columns, rows, state = 'ready', meta, onPage, onPerPage, onRetry, empty, toolbar, rowKey = 'id', onRowClick, skeletonRows = 6, filtered }) {
2632:   return (
2633:     <div className="v-card overflow-hidden">
2634:       {toolbar && <div className="p-4 v-border-b">{toolbar}</div>}
2635:       {state === 'error' ? <ErrorState onRetry={onRetry} code="GET /api/admin/… → 500" /> :
2636:        state === 'empty' || (state === 'ready' && rows.length === 0) ? (empty || <EmptyState title={filtered ? 'لا نتائج مطابقة للفلاتر' : 'لا توجد بيانات بعد'} body={filtered ? 'جرّب تعديل البحث أو إزالة بعض الفلاتر.' : null} />) : (
2637:         <div className="overflow-x-auto">
2638:           <table className="v-table">
2639:             <thead><tr>{columns.map((c) => <th key={c.key} style={{ width: c.width, textAlign: c.align }}>{c.label}</th>)}</tr></thead>
2640:             <tbody>
2641:               {state === 'loading' ? Array.from({ length: skeletonRows }).map((_, i) => (
2642:                 <tr key={i}>{columns.map((c, j) => <td key={c.key}>{c.skel ? c.skel(i) : <Skel w={j === 0 ? '70%' : `${40 + ((i * 7 + j * 13) % 40)}%`} h={10} />}</td>)}</tr>
2643:               )) : rows.map((r, i) => (
2644:                 <tr key={r[rowKey]} onClick={() => onRowClick && onRowClick(r)} className={cx(onRowClick && 'cursor-pointer')}>
2645:                   {columns.map((c) => <td key={c.key} style={{ textAlign: c.align }}>{c.render ? c.render(r, i) : r[c.key]}</td>)}
2646:                 </tr>
2647:               ))}
2648:             </tbody>
2649:           </table>
2650:         </div>
2651:       )}
2652:       {meta && state !== 'error' && state !== 'empty' && rows.length > 0 && <Pagination meta={meta} onPage={onPage} onPerPage={onPerPage} />}
2653:       {meta && state === 'loading' && (
2654:         <div className="flex items-center justify-between px-5 py-3.5 v-border-t"><Skel w={140} h={10} /><Skel w={160} h={26} r={999} /></div>
2655:       )}
2656:     </div>
2657:   );
2658: }
