2876: ];
2877: const vKey = (c, s, cap) => [(c && c.en || '').trim().toLowerCase(), (s || '').trim().toLowerCase(), (cap || '').trim().toLowerCase()].join('|');
2878: const priceOk = (x) => x === '' || x == null || /^\d+(\.\d{1,2})?$/.test(String(x));
