2880: function emptyVariant(c, s, cap, i) {
2881:   return { _id: Math.random().toString(36).slice(2), color: c || null, size: s || '', capacity: cap || '', sku: '', barcode: '', retail: '', wholesale: '', cost: '', compare: '', weight: '', reorder: '', order: i + 1, status: 'active', available: true };
2882: }
