2884: function validateVariants(rows, channel, mode) {
2885:   const errs = {}; const seen = {};
2886:   rows.forEach((r, i) => {
2887:     const e = {};
2888:     if (r.color && (r.color.ar || r.color.hex) && !r.color.en) e.color_en = 'الاسم الإنجليزي للون مطلوب';
2889:     ['retail', 'wholesale', 'cost', 'compare'].forEach((k) => { if (!priceOk(r[k])) e[k] = 'منزلتين عشريتين بحد أقصى'; });
2890:     if (r.status === 'active') {
2891:       if ((channel === 'retail' || channel === 'both') && !r.retail) e.retail = 'سعر التجزئة مطلوب';
2892:       if ((channel === 'wholesale' || channel === 'both') && !r.wholesale) e.wholesale = 'سعر الجملة مطلوب';
2893:     }
2894:     if (r.compare && r.retail && +r.compare <= +r.retail) e.compare = 'لازم يكون أعلى من سعر التجزئة';
2895:     const k = vKey(r.color, r.size, r.capacity);
2896:     if (mode === 'matrix') { if (seen[k] != null) { e.dup = `نفس تركيبة الصف ${seen[k] + 1}`; } else seen[k] = i; }
2897:     if (Object.keys(e).length) errs[r._id] = e;
2898:   });
2899:   return errs;
2900: }
