2958: function VariantsTab({ channel, mode, setMode, axes, setAxes, rows, setRows, errs, canCost }) {
2959:   const [sel, setSel] = useState([]);
2960:   const [open, setOpen] = useState({});
2961:   const [bulk, setBulk] = useState({ field: 'retail', value: '' });
2962:   const [genNote, setGenNote] = useState(null);
2963:   const gridRef = useRef(null);
2964:   const priceCols = [
2965:     { k: 'retail', l: 'سعر التجزئة', req: channel !== 'wholesale' },
2966:     { k: 'wholesale', l: 'سعر الجملة', req: channel !== 'retail' },
2967:     ...(canCost ? [{ k: 'cost', l: 'التكلفة', req: false }] : []),
2968:     { k: 'compare', l: 'سعر المقارنة', req: false },
2969:   ];
2970:   const combos = (axes.colors.length || 1) * (axes.sizes.length || 1) * (axes.capacities.length || 1);
2971:   const anyAxis = axes.colors.length + axes.sizes.length + axes.capacities.length > 0;
2972: 
2973:   const generate = () => {
2974:     const cs = axes.colors.length ? axes.colors : [null];
2975:     const ss = axes.sizes.length ? axes.sizes : [''];
2976:     const ps = axes.capacities.length ? axes.capacities : [''];
2977:     const existing = Object.fromEntries(rows.map((r) => [vKey(r.color, r.size, r.capacity), r]));
2978:     const next = []; let kept = 0, added = 0;
2979:     cs.forEach((c) => ss.forEach((s) => ps.forEach((p) => {
2980:       const k = vKey(c, s, p);
2981:       if (existing[k]) { next.push({ ...existing[k], color: c }); kept++; } else { next.push(emptyVariant(c, s, p, next.length)); added++; }
2982:     })));
2983:     const removed = rows.length - kept;
